// Flags that never take a value — they must not swallow a following
// positional (e.g. `piezas init --wait mydir` targets mydir/).
const BOOLEAN_FLAGS = new Set([
  'delete',
  'fromLogin',
  'allowEmpty',
  'context',
  'isolated',
  'json',
  'mcp',
  'mixed',
  'noDeps',
  'skipDeps',
  'skipInstall',
  'status',
  'strict',
  'verbose',
  'wait',
  'yes',
]);

export function parseCliArgs(args) {
  const flags = {};
  const positional = [];

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (!arg.startsWith('--')) {
      positional.push(arg);
      continue;
    }

    const [rawKey, inlineValue] = arg.slice(2).split('=');
    const key = rawKey.replace(/-([a-z])/g, (_, char) => char.toUpperCase());
    if (inlineValue !== undefined) {
      flags[key] = appendFlagValue(flags[key], inlineValue);
    } else if (!BOOLEAN_FLAGS.has(key) && args[i + 1] && !args[i + 1].startsWith('--')) {
      flags[key] = appendFlagValue(flags[key], args[i + 1]);
      i += 1;
    } else {
      flags[key] = appendFlagValue(flags[key], true);
    }
  }

  return { flags, positional };
}

function appendFlagValue(existing, value) {
  if (existing === undefined) return value;
  return Array.isArray(existing) ? [...existing, value] : [existing, value];
}

// spliceMarkerBlock replaces the START..END block inside `existing` with the
// block from `content`, preserving any user content around the markers. Falls
// back to a full replace when the block cannot be located on both sides.
function spliceMarkerBlock(existing, content, startMarker, endMarker) {
  if (!endMarker) return content;
  const start = existing.indexOf(startMarker);
  const end = existing.indexOf(endMarker, start);
  const newStart = content.indexOf(startMarker);
  const newEnd = content.indexOf(endMarker, newStart);
  if (start < 0 || end < 0 || newStart < 0 || newEnd < 0) return content;
  return (
    existing.slice(0, start) +
    content.slice(newStart, newEnd + endMarker.length) +
    existing.slice(end + endMarker.length)
  );
}

// A tool's config folder can be write-protected by the agent that is running
// init (Codex's sandbox protects .codex/). One unwritable integration file must
// not abort setup: skip it, say so, carry on.
const PROTECTED_FS_CODES = new Set(['EPERM', 'EACCES', 'EROFS']);

function safeMkdir(dir) {
  try {
    mkdirSync(dir, { recursive: true });
    return true;
  } catch (error) {
    if (PROTECTED_FS_CODES.has(error?.code)) return false;
    throw error;
  }
}

function writeIfNew(filePath, content, label, options = {}) {
  try {
    return writeIfNewUnsafe(filePath, content, label, options);
  } catch (error) {
    if (PROTECTED_FS_CODES.has(error?.code)) {
      log(`  Skipped ${label} (that folder is protected in this environment)`);
      return;
    }
    throw error;
  }
}

function writeIfNewUnsafe(filePath, content, label, options = {}) {
  if (!safeMkdir(dirname(filePath))) {
    log(`  Skipped ${label} (that folder is protected in this environment)`);
    return;
  }
  const startMarker = options.startMarker || PIEZAS_CONTEXT_START;
  const endMarker = options.endMarker ?? (startMarker === PIEZAS_CONTEXT_START ? PIEZAS_CONTEXT_END : undefined);
  const appendIfNoMarker = options.appendIfNoMarker ?? true;

  if (existsSync(filePath)) {
    const existing = readFileSync(filePath, 'utf-8');
    if (existing === content) {
      detail(`  ${label} is up to date - skipping`);
      return;
    }
    if (existing.includes(startMarker)) {
      const updated = spliceMarkerBlock(existing, content, startMarker, endMarker);
      if (updated === existing) {
        detail(`  ${label} is up to date - skipping`);
        return;
      }
      writeFileSync(filePath, updated);
      detail(`  Updated ${label}`);
      return;
    }
    if (!appendIfNoMarker) {
      detail(`  ${label} exists - skipping`);
      return;
    }
    writeFileSync(filePath, `${existing.trimEnd()}\n\n${content}`);
    detail(`  Updated ${label}`);
  } else {
    writeFileSync(filePath, content);
    detail(`  Created ${label}`);
  }
}

function writeFileIfMissing(filePath, content, label) {
  if (existsSync(filePath)) {
    const existing = readFileSync(filePath, 'utf-8');
    if (existing === content) {
      detail(`  ${label} is up to date - skipping`);
    } else {
      detail(`  ${label} exists - skipping`);
    }
    return false;
  }

  mkdirSync(dirname(filePath), { recursive: true });
  writeFileSync(filePath, content);
  detail(`  Created ${label}`);
  return true;
}

// upsertManifest creates piezas.manifest.json when missing, or extends an
// existing one with app metadata (appName, apiBaseUrl) without touching any
// other field the project may have customized.
function upsertManifest(manifestPath, buildOptions) {
  if (!existsSync(manifestPath)) {
    const manifest = buildDefaultManifest(buildOptions);
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
    detail('  Created piezas.manifest.json');
    return manifest;
  }

  let manifest;
  try {
    manifest = readJsonFile(manifestPath);
  } catch {
    log('  piezas.manifest.json is not valid JSON - leaving it untouched');
    return null;
  }

  let changed = false;
  if (buildOptions.appName && manifest.appName !== buildOptions.appName) {
    manifest.appName = buildOptions.appName;
    changed = true;
  }
  if (manifest.appName === undefined) {
    manifest.appName = null;
    changed = true;
  }
  if (manifest.apiBaseUrl === undefined) {
    manifest.apiBaseUrl = DEFAULT_API_BASE_URL;
    changed = true;
  }
  // The contract stamp records which version this project adopted and WHEN.
  // The fetch timestamp moves only when the VERSION changes — re-running init
  // against the same served version re-fetches but adopts nothing new, so the
  // manifest stays byte-stable (init is idempotent on an unchanged contract).
  const contractVersion = buildOptions.contractVersion ?? null;
  const contractFetchedAt = buildOptions.contractFetchedAt ?? null;
  if (manifest.contractVersion !== contractVersion) {
    manifest.contractVersion = contractVersion;
    manifest.contractFetchedAt = contractFetchedAt;
    changed = true;
  } else if (manifest.contractFetchedAt === undefined) {
    // Legacy manifest recorded a version but never a fetch time — backfill it.
    manifest.contractFetchedAt = contractFetchedAt;
    changed = true;
  }

  if (changed) {
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
    detail('  Updated piezas.manifest.json (app metadata)');
  } else {
    log('  piezas.manifest.json is up to date - skipping');
  }
  return manifest;
}

function mcpRouteContent() {
  return `import { piezasMcp } from '@piezas/sdk';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const handler = piezasMcp({
  entitiesUrl: process.env.PIEZAS_ENTITIES_URL || 'https://api.piezas.ai/entities',
  pipelineUrl: process.env.PIEZAS_PIPELINE_URL || 'https://api.piezas.ai/pipeline',
  tasksUrl: process.env.PIEZAS_TASKS_URL || 'https://api.piezas.ai/tasks',
  name: process.env.MCP_SERVER_NAME || 'piezas-app',
});

function requireMcpAccess(req: Request) {
  const hasAppSession = Boolean(req.headers.get('authorization') || req.headers.get('cookie'));
  const hasTenantContext = Boolean(req.headers.get('x-tenant-id') && req.headers.get('x-user-id'));
  if (hasAppSession && hasTenantContext) return null;

  return Response.json(
    { error: 'MCP route requires app auth plus X-Tenant-Id and X-User-Id.' },
    { status: 401 },
  );
}

export async function POST(req: Request) {
  // Replace this guard with your app session/auth check before exposing MCP publicly.
  const denied = requireMcpAccess(req);
  if (denied) return denied;

  return handler(req);
}
`;
}

function scaffoldMcpRoute(projectDir, deploymentMode, requested) {
  if (!requested) {
    return { enabled: false, routePath: null };
  }

  if (!supportsMcpRoute(deploymentMode)) {
    if (deploymentMode === 'static') {
      log('  Skipped MCP route: static deployment mode cannot host server routes.');
    } else {
      log('  Skipped MCP route: mount `piezasMcp` in your server framework for this deployment mode.');
    }
    return {
      enabled: false,
      routePath: null,
      skippedReason: deploymentMode === 'static' ? 'static-deployment-mode' : 'manual-server-framework',
    };
  }

  writeFileIfMissing(
    resolve(projectDir, MCP_ROUTE_PATH),
    mcpRouteContent(),
    MCP_ROUTE_PATH,
  );
  return { enabled: true, routePath: MCP_ROUTE_PATH };
}

// --- the scenario test harness --------------------------------------------
//
// The protocol's BUILD gate is "one test per S-nnn, suite green".
// That is only cheap if the harness is already
// there: a config, a smoke test, a place for the scenario files, and a seed
// stub. Everything here is written ONLY when absent — a project's own harness
// is never touched.

const PLAYWRIGHT_TEST_VERSION = '^1.47.0';
const HARNESS_FILES = {
  config: 'playwright.config.ts',
  smoke: 'tests/smoke.spec.ts',
  scenarios: 'tests/scenarios/README.md',
  seed: 'scripts/seed.ts',
};

function playwrightConfigContent() {
  return `import { defineConfig, devices } from '@playwright/test';

// The Piezas scenario harness. \`npx piezas test\` runs this suite and writes
// .piezas/test-attestation.json — the evidence \`npx piezas deploy\` reports.
// PW_BASE_URL points the SAME suite at local dev, a preview, or the deployed
// app, so nothing about a test changes when the target does.
export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  forbidOnly: Boolean(process.env.CI),
  retries: process.env.CI ? 1 : 0,
  reporter: 'list',
  use: {
    baseURL: process.env.PW_BASE_URL || 'http://localhost:3000',
    trace: 'on-first-retry',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
});
`;
}

function smokeTestContent() {
  return `import { expect, test } from '@playwright/test';

// The one test every app has. A red smoke test means nothing below it is worth
// reading: the page either renders or it does not.
test('the home page renders with a clean console', async ({ page }) => {
  const errors: string[] = [];
  page.on('console', (message) => {
    if (message.type() === 'error') errors.push(message.text());
  });
  page.on('pageerror', (error) => errors.push(error.message));

  const response = await page.goto('/');

  expect(response?.ok(), \`GET / returned \${response?.status()}\`).toBeTruthy();
  await expect(page.locator('body')).not.toBeEmpty();
  expect(errors, \`console errors on /:\\n\${errors.join('\\n')}\`).toEqual([]);
});
`;
}

function scenariosReadmeContent() {
  return `# Acceptance scenarios

One file per acceptance scenario in \`SPEC.md\`, named for the scenario it
proves: \`S-001.spec.ts\` tests \`### S-001\`, and nothing else. Write each file
from the scenario's own Given/When/Then — the Given is the fixture setup (see
\`scripts/seed.ts\`), the When is the interaction, the Then is the assertion —
and keep the scenario title in the test name so a red run names the requirement
that broke. \`npx piezas spec coverage\` fails until every \`S-nnn\` in the spec
has a file here, and \`npx piezas test\` records how many of them ran.

**Select by \`data-testid\`.** Text and CSS selectors break on the next redesign
and turn a passing suite into a maintenance tax; a test id survives copy
changes, restyling and layout moves. Add \`data-testid\` to the elements a
scenario drives, name it for the thing (\`data-testid="cancel-booking"\`), and
select it with \`page.getByTestId('cancel-booking')\`. \`npx piezas doctor\`
counts the interactive elements that still have none (PZ026).
`;
}

function seedScriptContent() {
  return `// Seed the fixture data the scenario tests assume, through @piezas/sdk — the
// same services the app itself calls, so a test that passes here exercises the
// real substrate rather than a mock of it.
//
// Two rules make a suite trustworthy:
//   1. Deterministic — fixed ids and fixed dates, so the same run gives the
//      same result today and in March.
//   2. Re-runnable — clean up or upsert; a second run must not double the data.
//
// Point it at a TEST app's key, never a live one:
//   PIEZAS_API_KEY=<test key> npx tsx scripts/seed.ts

import { createPiezasClient } from '@piezas/sdk';

const client = createPiezasClient({
  apiKey: process.env.PIEZAS_API_KEY,
  baseUrl: process.env.PIEZAS_API_URL,
});

export async function seed() {
  // TODO(you): create the fixtures your S-nnn scenarios say "Given ...".
  // Example:
  // await client.records.upsert('bookings', { id: 'seed-booking-1', startTime: '2026-01-05T19:00:00Z' });
  return client;
}

if (process.argv[1]?.endsWith('seed.ts')) {
  seed().then(() => console.log('seeded'));
}
`;
}

// ensurePlaywrightDependency declares the harness's ONLY dependency. An
// existing pin is never touched — the project's choice outranks ours.
function ensurePlaywrightDependency(projectDir) {
  const packagePath = resolve(projectDir, 'package.json');
  let pkg;
  try {
    pkg = readJsonFile(packagePath);
  } catch {
    return false;
  }
  if (pkg.dependencies?.['@playwright/test'] || pkg.devDependencies?.['@playwright/test']) return false;
  pkg.devDependencies = { ...(pkg.devDependencies || {}), '@playwright/test': PLAYWRIGHT_TEST_VERSION };
  writeFileSync(packagePath, `${JSON.stringify(pkg, null, 2)}\n`);
  detail(`  Added @playwright/test ${PLAYWRIGHT_TEST_VERSION} to devDependencies`);
  return true;
}

function scaffoldTestHarness(projectDir) {
  const created = [];
  const files = [
    [HARNESS_FILES.config, playwrightConfigContent()],
    [HARNESS_FILES.smoke, smokeTestContent()],
    [HARNESS_FILES.scenarios, scenariosReadmeContent()],
    [HARNESS_FILES.seed, seedScriptContent()],
  ];
  for (const [rel, content] of files) {
    if (writeFileIfMissing(resolve(projectDir, rel), content, rel)) created.push(rel);
  }
  const dependencyAdded = ensurePlaywrightDependency(projectDir);
  if (created.length > 0 || dependencyAdded) {
    detail('  Scenario harness ready — install it once with: npm install && npx playwright install');
  }
  return { created, dependencyAdded };
}

function packageNameFromDir(projectDir) {
  const name = basename(projectDir)
    .toLowerCase()
    .replace(/^@/, '')
    .replace(/[^a-z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return name || 'piezas-app';
}

function ensurePackageJson(projectDir) {
  const pkgJsonPath = resolve(projectDir, 'package.json');
  if (existsSync(pkgJsonPath)) {
    return;
  }

  const pkg = {
    name: packageNameFromDir(projectDir),
    version: '0.1.0',
    private: true,
    type: 'module',
  };

  writeFileSync(pkgJsonPath, `${JSON.stringify(pkg, null, 2)}\n`);
  detail('  Created package.json');
}

function stripQuotes(value) {
  const match = /^(['"])(.*)\1$/.exec(value);
  return match ? match[2] : value;
}

// readEnvKeyValue returns the PIEZAS_API_KEY value from a dotenv-style file,
// or undefined when the file or the line is absent.
function readEnvKeyValue(filePath) {
  if (!existsSync(filePath)) return undefined;
  for (const line of readFileSync(filePath, 'utf-8').split(/\r?\n/)) {
    const match = ENV_KEY_LINE.exec(line);
    if (match) return stripQuotes(match[1].trim());
  }
  return undefined;
}

// writeEnvKey merges PIEZAS_API_KEY=<key> into the project .env: creates the
// file, appends the line, or replaces ONLY the existing PIEZAS_API_KEY line.
// Every other byte — including CRLF/LF line endings — is preserved.
function writeEnvKey(envPath, key) {
  if (!existsSync(envPath)) {
    writeFileSync(envPath, `PIEZAS_API_KEY=${key}\n`);
    return 'created';
  }

  const content = readFileSync(envPath, 'utf-8');
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const parts = content.split(/(\r?\n)/);
  for (let i = 0; i < parts.length; i += 2) {
    const match = ENV_KEY_LINE.exec(parts[i]);
    if (!match) continue;
    if (stripQuotes(match[1].trim()) === key) return 'kept';
    parts[i] = `PIEZAS_API_KEY=${key}`;
    writeFileSync(envPath, parts.join(''));
    return 'replaced';
  }

  const needsNewline = content.length > 0 && !content.endsWith('\n');
  writeFileSync(envPath, `${content}${needsNewline ? eol : ''}PIEZAS_API_KEY=${key}${eol}`);
  return 'appended';
}

// writeEnvVar merges NAME=<value> into .env with the same preservation
// semantics as writeEnvKey (create / append / replace only that line).
function writeEnvVar(envPath, name, value) {
  const lineRe = new RegExp(`^\\s*(?:export\\s+)?${name}\\s*=\\s*(.*)$`);
  if (!existsSync(envPath)) {
    writeFileSync(envPath, `${name}=${value}\n`);
    return 'created';
  }
  const content = readFileSync(envPath, 'utf-8');
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const parts = content.split(/(\r?\n)/);
  for (let i = 0; i < parts.length; i += 2) {
    const match = lineRe.exec(parts[i]);
    if (!match) continue;
    if (stripQuotes(match[1].trim()) === value) return 'kept';
    parts[i] = `${name}=${value}`;
    writeFileSync(envPath, parts.join(''));
    return 'replaced';
  }
  const needsNewline = content.length > 0 && !content.endsWith('\n');
  writeFileSync(envPath, `${content}${needsNewline ? eol : ''}${name}=${value}${eol}`);
  return 'appended';
}

const GITIGNORE_ENV_PATTERNS = new Set(['.env', '/.env', '.env*', '*.env', '**/.env']);

// ensureGitignore makes sure .env is git-ignored. Respects existing patterns
// (.env, .env*, *.env, ...) and appends a "# piezas" section only when needed.
function ensureGitignore(projectDir) {
  const gitignorePath = resolve(projectDir, '.gitignore');
  if (!existsSync(gitignorePath)) {
    writeFileSync(gitignorePath, '# piezas\n.env\n');
    detail('  Created .gitignore (.env ignored)');
    return true;
  }

  const content = readFileSync(gitignorePath, 'utf-8');
  const covered = content
    .split(/\r?\n/)
    .some((line) => GITIGNORE_ENV_PATTERNS.has(line.trim()));
  if (covered) {
    return false;
  }

  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  let updated = content;
  if (updated.length > 0 && !updated.endsWith('\n')) updated += eol;
  if (updated.length > 0) updated += eol;
  updated += `# piezas${eol}.env${eol}`;
  writeFileSync(gitignorePath, updated);
  detail('  Updated .gitignore (.env ignored)');
  return true;
}

function promptViaTerminal(question) {
  return new Promise((resolvePrompt) => {
    const rl = createInterface({ input: process.stdin, output: process.stdout });
    rl.question(question, (answer) => {
      rl.close();
      resolvePrompt(answer);
    });
  });
}

// waitForEnvKey polls the project dir for a dropped-in .env (or the names a
// browser may give the dashboard download) containing PIEZAS_API_KEY.
async function waitForEnvKey(projectDir, timeoutSeconds, intervalMs) {
  log(`  Waiting for your API key: drop a ${WAIT_FILE_CANDIDATES.join(' or ')} file`);
  log(`  containing PIEZAS_API_KEY into ${projectDir}`);
  log(`  (dashboard -> API Keys -> "Download .env"). Checking every ${Math.round(intervalMs / 100) / 10}s, timeout ${timeoutSeconds}s.`);

  const deadline = Date.now() + timeoutSeconds * 1000;
  for (;;) {
    for (const name of WAIT_FILE_CANDIDATES) {
      const value = readEnvKeyValue(resolve(projectDir, name));
      if (value) {
        log(`  Found PIEZAS_API_KEY in ${name}`);
        return { value, file: name };
      }
    }
    if (Date.now() >= deadline) {
      log(`  No key file appeared within ${timeoutSeconds}s - continuing without a key.`);
      return undefined;
    }
    await new Promise((resolveDelay) => setTimeout(resolveDelay, intervalMs));
  }
}

// resolveApiKey implements the key-intake precedence:
// existing .env key > --key flag > process env > `piezas login` auto-mint >
// interactive paste prompt > --wait.
// Only explicitly provided keys (--key/prompt/wait) may replace an existing
// .env value; the process env never overrides an already-configured project.
async function resolveApiKey(envPath, projectDir, options) {
  const existingValue = readEnvKeyValue(envPath);
  const flagKey = typeof options.key === 'string' && options.key.trim() ? options.key.trim() : undefined;

  if (existingValue && !flagKey) {
    return { key: existingValue, source: 'env-file' };
  }
  if (flagKey) {
    return { key: flagKey, source: 'flag' };
  }

  const processKey = (options.env ?? process.env).PIEZAS_API_KEY;
  if (processKey) {
    return { key: processKey, source: 'process-env' };
  }

  // Signed in via `piezas login`? Create the app and mint its key right here,
  // from the terminal -- no dashboard visit, no copy-paste. This runs BEFORE the
  // manual paste prompt so a logged-in user is never sent to the web UI to fetch
  // a key by hand. Declining the offer falls through to the manual paths below.
  const minted = await resolveKeyViaLogin(projectDir, options);
  if (minted) {
    return minted;
  }

  if (options.interactive && !options.yes) {
    const promptFn = options.promptFn ?? promptViaTerminal;
    const answer = String((await promptFn(KEY_PROMPT)) ?? '').trim();
    if (answer) {
      return { key: answer, source: 'prompt' };
    }
  }

  if (options.wait) {
    const timeoutSeconds = options.waitTimeout ?? DEFAULT_WAIT_TIMEOUT_SECONDS;
    const intervalMs = options.waitIntervalMs ?? DEFAULT_WAIT_INTERVAL_MS;
    const found = await waitForEnvKey(projectDir, timeoutSeconds, intervalMs);
    if (found) {
      return { key: found.value, source: 'wait', sourceFile: found.file };
    }
  }

  return { key: undefined, source: 'none' };
}

// --- Platform auth (piezas login / logout / whoami) ---------------------

// resolveApiBase: --api-base flag > PIEZAS_API_BASE env > fallback (the
// default recorded in piezas.manifest.json's apiBaseUrl).
function resolveApiBase(options, env, fallback = DEFAULT_API_BASE_URL) {
  const flagBase = typeof options.apiBase === 'string' && options.apiBase.trim()
    ? options.apiBase.trim()
    : undefined;
  const envBase = typeof env.PIEZAS_API_BASE === 'string' && env.PIEZAS_API_BASE.trim()
    ? env.PIEZAS_API_BASE.trim()
    : undefined;
  return (flagBase || envBase || fallback).replace(/\/+$/, '');
}

function adminBaseUrl(apiBase) {
  return `${apiBase}${ADMIN_PATH_PREFIX}`;
}

// credentialsFilePath honors PIEZAS_HOME (used by tests) and defaults to
// ~/.piezas/credentials.json.
export function credentialsFilePath(env = process.env) {
  const home = typeof env.PIEZAS_HOME === 'string' && env.PIEZAS_HOME.trim()
    ? env.PIEZAS_HOME.trim()
    : join(homedir(), '.piezas');
  return join(home, 'credentials.json');
}

// readCredentials returns the stored CLI session or undefined. Corrupt or
// token-less files read as "logged out" — never throw.
function readCredentials(env = process.env) {
  const filePath = credentialsFilePath(env);
  if (!existsSync(filePath)) return undefined;
  try {
    const parsed = JSON.parse(readFileSync(filePath, 'utf-8'));
    if (!parsed || typeof parsed !== 'object' || typeof parsed.cliToken !== 'string' || !parsed.cliToken) {
      return undefined;
    }
    return parsed;
  } catch {
    return undefined;
  }
}

function writeCredentials(credentials, env = process.env) {
  const filePath = credentialsFilePath(env);
  mkdirSync(dirname(filePath), { recursive: true, mode: 0o700 });
  writeFileSync(filePath, `${JSON.stringify(credentials, null, 2)}\n`, { mode: 0o600 });
  // writeFileSync's mode only applies on create — enforce on rewrite too.
  chmodSync(filePath, 0o600);
  return filePath;
}

// fetchJson: built-in fetch with a hard timeout and JSON parse guards.
// Non-2xx statuses are returned (not thrown); network errors/timeouts throw.
async function fetchJson(fetchFn, url, { method = 'GET', body, token, timeoutMs = HTTP_TIMEOUT_MS } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const headers = { accept: 'application/json' };
    if (body !== undefined) headers['content-type'] = 'application/json';
    if (token) headers.authorization = `Bearer ${token}`;
    const response = await fetchFn(url, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
      signal: controller.signal,
    });
    let data;
    try {
      data = await response.json();
    } catch {
      data = undefined;
    }
    return { status: response.status, data };
  } finally {
    clearTimeout(timer);
  }
}

// openInBrowser best-effort opens a URL. Failures are swallowed — the URL is
// always printed, so the user can click/copy it manually.
function openInBrowser(url) {
  try {
    const [command, args] = process.platform === 'darwin'
      ? ['open', [url]]
      : process.platform === 'win32'
        ? ['cmd', ['/c', 'start', '', url]]
        : ['xdg-open', [url]];
    const child = spawn(command, args, { stdio: 'ignore', detached: true });
    child.on('error', () => {});
    child.unref();
    return true;
  } catch {
    return false;
  }
}

function printUserCode(userCode) {
  const inner = `   ${userCode}   `;
  const line = '─'.repeat(inner.length);
  log(`      ╭${line}╮`);
  log(`      │${inner}│`);
  log(`      ╰${line}╯`);
}

const LOGIN_RETRY_HINT = 'Run `npx piezas login` to get a new code.';

// offerBrowserOpen offers "hit ENTER to open the browser" WITHOUT blocking the
// approval poll: polling runs concurrently, so approving via the pasted link
// completes login even if ENTER is never pressed. Returns cancel() to detach the
// listener once polling ends, so the process exits cleanly instead of hanging on
// stdin.
function offerBrowserOpen(options, url, opener) {
  const promptText =
    '  Press ENTER to open your browser (or open the link above yourself)... ';
  let done = false;
  const openNow = () => {
    if (done) return;
    done = true;
    if (opener(url)) {
      log('  Opening your browser... (if nothing happens, use the link above)');
    }
  };
  if (options.promptFn) {
    // Injected/non-terminal caller: resolve the prompt → open. Nothing to detach.
    Promise.resolve(options.promptFn(promptText)).then(openNow).catch(() => {});
    return () => { done = true; };
  }
  // Real terminal: a one-shot stdin line. Opening is optional and non-blocking —
  // the poll is what actually completes login.
  log(promptText.trimEnd());
  const stdin = process.stdin;
  const detach = () => {
    stdin.removeListener('data', onData);
    stdin.pause();
  };
  const onData = () => { detach(); openNow(); };
  stdin.resume();
  stdin.on('data', onData);
  return () => { if (!done) { done = true; detach(); } };
}

export async function login(options = {}) {
  const previousEmit = emit;
  if (options.json) {
    emit = (message) => process.stderr.write(`${message}\n`);
  }
  let outcome;
  try {
    outcome = await runLogin(options);
  } finally {
    emit = previousEmit;
  }
  if (options.json) {
    console.log(JSON.stringify(outcome.summary, null, 2));
  }
  return { exitCode: outcome.exitCode, ...outcome.summary };
}

async function runLogin(options) {
  const env = options.env ?? process.env;
  const fetchFn = options.fetchFn ?? fetch;
  const apiBase = resolveApiBase(options, env);
  const admin = adminBaseUrl(apiBase);

  log('\n  🧱 Piezas login\n');

  let start;
  try {
    start = await fetchJson(fetchFn, `${admin}/v1/portal/device-codes`, {
      method: 'POST',
      timeoutMs: options.httpTimeoutMs,
    });
  } catch (error) {
    log(`  Could not reach ${apiBase} (${error?.message || 'network error'}). Check your connection and try again.`);
    return { exitCode: 1, summary: { command: 'login', status: 'error', error: 'unreachable', apiBase } };
  }

  if (start.status === 429) {
    log('  Too many sign-in requests are pending right now - wait a few minutes and try again.');
    return { exitCode: 1, summary: { command: 'login', status: 'error', error: 'rate-limited', apiBase } };
  }
  const device = start.data;
  if (start.status !== 201 || !device || typeof device.deviceCode !== 'string' || typeof device.userCode !== 'string') {
    log(`  Sign-in could not be started (HTTP ${start.status}). Try again in a moment.`);
    return { exitCode: 1, summary: { command: 'login', status: 'error', error: `http-${start.status}`, apiBase } };
  }

  const verificationUri = device.verificationUri || 'https://app.piezas.ai/device';
  const confirmUrl = `${verificationUri}${verificationUri.includes('?') ? '&' : '?'}code=${encodeURIComponent(device.userCode)}`;

  log('  Confirm this code in your browser to sign in:');
  log('');
  printUserCode(device.userCode);
  log('');
  log(`  ${confirmUrl}`);
  log('');
  const opener = options.openBrowserFn ?? openInBrowser;
  // Offer to open the browser (npm/gh style — never auto-hijack). Interactive when
  // the caller says so (main() passes it based on a real TTY) or provides a
  // promptFn; --json and interactive:false stay hands-off and just print the link.
  const wantsPrompt =
    options.interactive !== false &&
    !options.json &&
    (options.interactive === true ||
      (options.promptFn !== undefined && options.promptFn !== null));
  // CRITICAL: the offer must NOT block the poll below. Approving via the pasted
  // link has to complete login even if ENTER is never pressed, so the "hit ENTER
  // to open" offer runs concurrently and is cancelled once polling ends.
  const cancelOffer = wantsPrompt
    ? offerBrowserOpen(options, confirmUrl, opener)
    : () => {};
  log('  Waiting for approval...');

  const intervalMs = options.pollIntervalMs
    ?? (Number(device.interval) > 0 ? Number(device.interval) : 5) * 1000;
  const lifetimeMs = (Number(device.expiresIn) > 0 ? Number(device.expiresIn) : 900) * 1000;
  const deadline = Date.now() + lifetimeMs;

  try {
    while (Date.now() < deadline) {
      await new Promise((resolveDelay) => setTimeout(resolveDelay, intervalMs));
      let poll;
      try {
        poll = await fetchJson(fetchFn, `${admin}/v1/portal/device-codes/token`, {
          method: 'POST',
          body: { deviceCode: device.deviceCode },
          timeoutMs: options.httpTimeoutMs,
        });
      } catch {
        continue; // transient network trouble — keep polling until expiry
      }

      if (poll.status === 200 && poll.data?.status === 'ok' && typeof poll.data.cliToken === 'string') {
        const credentials = {
          cliToken: poll.data.cliToken,
          tenantId: poll.data.tenantId,
          tenantName: poll.data.tenantName,
          email: poll.data.email,
          apiBase,
        };
        const credentialsPath = writeCredentials(credentials, env);
        log('');
        log(`  Logged in as ${credentials.email}${credentials.tenantName ? ` (${credentials.tenantName})` : ''}.`);
        log(`  Session saved to ${credentialsPath}`);
        log('  Next: run `npx piezas init` in your project folder.\n');
        return {
          exitCode: 0,
          summary: {
            command: 'login',
            status: 'ok',
            tenantId: credentials.tenantId ?? null,
            tenantName: credentials.tenantName ?? null,
            email: credentials.email ?? null,
            apiBase,
            credentialsPath,
          },
        };
      }
      if (poll.status === 200) continue; // pending
      if (poll.status === 404 || poll.status === 400) {
        log(`  This sign-in code is no longer valid (expired or already used). ${LOGIN_RETRY_HINT}`);
        return { exitCode: 1, summary: { command: 'login', status: 'expired', apiBase } };
      }
      // Any other status (e.g. a transient 5xx) — keep polling until expiry.
    }

    log(`  The sign-in code expired before it was approved. ${LOGIN_RETRY_HINT}`);
    return { exitCode: 1, summary: { command: 'login', status: 'expired', apiBase } };
  } finally {
    cancelOffer();
  }
}

// How long logout waits for the server-side session revocation before giving
// up and deleting the local credentials anyway.
const LOGOUT_REVOKE_TIMEOUT_MS = 2000;

export async function logout(options = {}) {
  const env = options.env ?? process.env;
  const credentialsPath = credentialsFilePath(env);
  const credentials = readCredentials(env);

  // Best-effort server-side revocation BEFORE deleting the local file: the
  // 30-day cliToken is bound to a revocable server session, so logging out
  // kills any copy of the token, not just this machine's file. Failures
  // (offline, expired, 5xx, hung server) never block the local logout.
  let revoked = false;
  if (credentials?.cliToken) {
    const fetchFn = options.fetchFn ?? fetch;
    const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
    try {
      const response = await fetchJson(fetchFn, `${adminBaseUrl(apiBase)}/v1/portal/cli-sessions/revoke`, {
        method: 'POST',
        token: credentials.cliToken,
        timeoutMs: options.revokeTimeoutMs ?? LOGOUT_REVOKE_TIMEOUT_MS,
      });
      revoked = response.status === 200;
    } catch {
      // ignore — logout is local-first
    }
  }

  let removed = false;
  if (existsSync(credentialsPath)) {
    unlinkSync(credentialsPath);
    removed = true;
  }
  const summary = { command: 'logout', removed, revoked, credentialsPath };
  if (options.json) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log(removed ? '  Logged out of Piezas.' : '  Not logged in - nothing to remove.');
  }
  return { exitCode: 0, ...summary };
}

export function whoami(options = {}) {
  const env = options.env ?? process.env;
  const credentials = readCredentials(env);
  if (!credentials) {
    if (options.json) {
      console.log(JSON.stringify({ command: 'whoami', loggedIn: false }, null, 2));
    } else {
      console.log('  Not logged in. Run `npx piezas login` to sign in.');
    }
    return { exitCode: 1, command: 'whoami', loggedIn: false };
  }

  // Never include the cliToken here — whoami output is safe to paste anywhere.
  const summary = {
    command: 'whoami',
    loggedIn: true,
    tenantId: credentials.tenantId ?? null,
    tenantName: credentials.tenantName ?? null,
    email: credentials.email ?? null,
    apiBase: credentials.apiBase ?? DEFAULT_API_BASE_URL,
  };
  if (options.json) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log('\n  🧱 Piezas CLI session\n');
    console.log(`  Tenant: ${summary.tenantName ?? 'unknown'}${summary.tenantId ? ` (${summary.tenantId})` : ''}`);
    console.log(`  Email:  ${summary.email ?? 'unknown'}`);
    console.log(`  API:    ${summary.apiBase}\n`);
  }
  return { exitCode: 0, ...summary };
}

// slugifyAppName mirrors the Go control plane's slugify (and the dashboard
// BFF): lowercase, [a-z0-9] runs joined by single hyphens, trimmed.
function slugifyAppName(name) {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// resolveKeyViaLogin: when no key was found by the normal intake chain but a
// CLI session exists, create the app (or reuse it on a name conflict) and
// mint a live key bound to it — the same composition the dashboard's
// onboarding performs. Every failure degrades to "no key" with a friendly
// message; init never crashes because of this step.
async function resolveKeyViaLogin(projectDir, options) {
  if (!options.fromLogin && !(options.interactive && !options.yes)) return undefined;
  const env = options.env ?? process.env;
  const credentials = platformCredentials(projectDir, env);
  if (!credentials) return undefined;

  const flagApp = (typeof options.app === 'string' && options.app.trim())
    ? options.app.trim()
    : undefined;
  const defaultName = flagApp || basename(projectDir);
  let appName = defaultName;

  // Interactive (and not the non-interactive --from-login shortcut, and no
  // explicit --app): offer an explicit choice -- create a new app now (which
  // mints its key for you), or paste a key you already made in the dashboard.
  // Choosing "paste" (2) returns undefined so the caller falls through to the
  // paste prompt. Choosing "create" (1, the default) asks for the app name and
  // mints its key here -- no dashboard visit. An explicit --app skips the menu
  // and creates that app directly.
  if (!flagApp && !options.fromLogin && options.interactive && !options.yes) {
    const promptFn = options.promptFn ?? promptViaTerminal;
    log('');
    log(`  Signed in as ${credentials.email}. How would you like to get your API key?`);
    log("    1) Create a new app now - we'll mint its key  (recommended)");
    log('    2) Paste a key you already created in the dashboard');
    const choice = String((await promptFn('  Choose 1 or 2 [1]: ')) ?? '').trim();
    if (choice === '2') return undefined;
    const answer = String((await promptFn(`  Name for the new app [${defaultName}]: `)) ?? '').trim();
    appName = answer || defaultName;
  }

  const fetchFn = platformFetch(projectDir, options);
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const admin = adminBaseUrl(apiBase);
  const tenantPath = `${admin}/v1/tenants/${credentials.tenantId}`;
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const sessionExpired = () => {
    log('  Your Piezas session has expired - run `npx piezas login`, then rerun init.');
    return undefined;
  };

  try {
    let app;
    const created = await fetchJson(fetchFn, `${tenantPath}/partitions`, {
      ...httpOptions,
      method: 'POST',
      body: { name: appName },
    });
    if (created.status === 201 && created.data?.id) {
      app = created.data;
      detail(`  Created app "${app.name}"${credentials.tenantName ? ` in ${credentials.tenantName}` : ''}`);
    } else if (created.status === 409) {
      // The app already exists — find it by the same slug the platform
      // derived (or by exact name) and reuse it, exactly like the dashboard.
      // LIST via my-apps (an admin sees all; create already proved admin here).
      const listed = await fetchJson(fetchFn, `${tenantPath}/my-apps`, httpOptions);
      if (listed.status === 401) return sessionExpired();
      const slug = slugifyAppName(appName);
      const existing = Array.isArray(listed.data?.data)
        ? listed.data.data.find((p) => p?.slug === slug || p?.name === appName)
        : undefined;
      if (!existing) {
        log('  An app with that name already exists but could not be found - continuing without a key.');
        return undefined;
      }
      app = existing;
      log(`  Reusing existing app "${app.name}"`);
    } else if (created.status === 401) {
      return sessionExpired();
    } else if (created.status === 403) {
      // Creating an app is admin-only — don't pretend a developer can self-serve.
      log('  Only an admin can create an app — ask an admin to create it and grant you');
      log('  access, then rerun init (or paste an existing key). Continuing without a key.');
      return undefined;
    } else {
      log(`  Could not create the app (HTTP ${created.status}) - continuing without a key.`);
      return undefined;
    }

    const minted = await fetchJson(fetchFn, `${tenantPath}/api-keys`, {
      ...httpOptions,
      method: 'POST',
      body: { name: appName, environment: 'live', partitionId: app.id },
    });
    if (minted.status === 401) return sessionExpired();
    if (minted.status !== 201 || typeof minted.data?.key !== 'string' || !minted.data.key) {
      log(`  Could not mint an API key (HTTP ${minted.status}) - continuing without a key.`);
      return undefined;
    }
    detail(`  Minted a live API key for "${app.name}"`);

    // Provision the HOSTED environment at birth: stage the freshly-minted key
    // into the apps server's cloud env store, bound to the app's durable id.
    // Best-effort — hosting may not be provisioned in every install — and the
    // local .env copy remains for LOCAL development only; deploys never read it.
    try {
      const appsBase = appsBaseUrl(options, env);
      const stagedRes = await fetchJson(fetchFn,
        `${appsBase}/v1/deployments/${slugifyAppName(app.name)}/env?appId=${encodeURIComponent(app.id)}`,
        { token: credentials.cliToken, method: 'PATCH', body: { set: { PIEZAS_API_KEY: minted.data.key } }, timeoutMs: 4000 });
      if (stagedRes.status === 200) {
        detail('  Hosted env provisioned — PIEZAS_API_KEY is already staged for deploys');
      }
    } catch { /* hosting is optional at init time */ }

    return { key: minted.data.key, source: 'login', appName: app.name, appId: app.id };
  } catch (error) {
    log(`  Could not reach Piezas (${error?.message || 'network error'}) - continuing without a key.`);
    return undefined;
  }
}

// --- End platform auth ---------------------------------------------------

// --- piezas deploy: ship the built app to the shared apps server ----------

const DEFAULT_APPS_URL = 'https://apps.piezas.ai';
const DEPLOY_TIMEOUT_MS = 10 * 60 * 1000; // uploads can be slow; be patient
// Client-side artifact cap — a FAST-FAIL courtesy so an oversized bundle is
// caught before a slow upload. Piezas hosting enforces its own limit
// server-side and is the authoritative check; this only exists to save
// a doomed round-trip. Configurable via PIEZAS_MAX_ARTIFACT_MB so it tracks the
// server default and can be raised without a CLI release. A full Piezas app
// (Next standalone) is ~10 MB compressed, so blowing this almost always means
// node_modules or media that belongs in the Documents service.
export function resolveMaxArtifactMB(env = process.env) {
  const raw = Number(env.PIEZAS_MAX_ARTIFACT_MB);
  return Number.isFinite(raw) && raw > 0 ? raw : 60;
}

function appsBaseUrl(options, env) {
  const flag = typeof options.appsUrl === 'string' && options.appsUrl.trim()
    ? options.appsUrl.trim() : undefined;
  const fromEnv = typeof env.PIEZAS_APPS_URL === 'string' && env.PIEZAS_APPS_URL.trim()
    ? env.PIEZAS_APPS_URL.trim() : undefined;
  return (flag || fromEnv || DEFAULT_APPS_URL).replace(/\/+$/, '');
}

// deploySlugFor mirrors the server's base slugify so status/logs/delete can
// address the deployment. The authoritative (possibly suffixed) slug returned
// by a deploy is persisted into piezas.manifest.json for later commands.
function deploySlugFor(projectDir, options) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  let manifest = null;
  try { manifest = readJsonFile(manifestPath); } catch { /* absent/corrupt is fine */ }
  if (manifest?.deploy?.slug && !options.app) return manifest.deploy.slug;
  const name = (typeof options.app === 'string' && options.app.trim())
    ? options.app.trim()
    : manifest?.appName || basename(projectDir);
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

// stageArtifact assembles the deployable tree in a temp dir and detects the
// app's shape (preflight, part 1), in priority order:
//   - --dir <path>: server.js -> server, index.html -> static
//   - Next standalone output                          -> kind "server"
//   - static export (out/ or dist/ with index.html)   -> kind "static"
//   - plain app at the project root (server.js / index.html) — LAST, so real
//     framework projects prefer their build output over their source tree
// Returns null when nothing deployable exists (with build guidance).
function stageArtifact(projectDir, stagingDir, options) {
  const copyInto = (src) => execSync(`cp -R ${JSON.stringify(src)}/. ${JSON.stringify(stagingDir)}/`);
  // Every artifact is scrubbed, whatever its shape: no .env or .env.* file
  // (examples included) and no .git, at ANY depth. Build output is not clean
  // by itself: `next build` with output: "standalone" copies the project's
  // .env files into .next/standalone/, and server.js loads them at startup.
  const done = (result) => (result ? { ...result, removed: scrubArtifact(stagingDir) } : null);
  const stageFolder = (src, source) => {
    copyInto(src);
    if (existsSync(resolve(stagingDir, 'server.js'))) return done({ kind: 'server', source });
    if (existsSync(resolve(stagingDir, 'index.html'))) return done({ kind: 'static', source });
    return null; // has neither entry file -> caller explains
  };

  if (typeof options.dir === 'string' && options.dir.trim()) {
    const src = resolve(projectDir, options.dir.trim());
    if (!existsSync(src)) return null;
    return stageFolder(src, options.dir.trim());
  }

  const standalone = resolve(projectDir, '.next', 'standalone');
  if (existsSync(resolve(standalone, 'server.js'))) {
    copyInto(standalone);
    const staticDir = resolve(projectDir, '.next', 'static');
    if (existsSync(staticDir)) {
      mkdirSync(resolve(stagingDir, '.next'), { recursive: true });
      execSync(`cp -R ${JSON.stringify(staticDir)} ${JSON.stringify(resolve(stagingDir, '.next', 'static'))}`);
    }
    const publicDir = resolve(projectDir, 'public');
    if (existsSync(publicDir)) {
      execSync(`cp -R ${JSON.stringify(publicDir)} ${JSON.stringify(resolve(stagingDir, 'public'))}`);
    }
    return done({ kind: 'server', source: 'next standalone' });
  }

  // Static exports: Next `output: "export"` writes out/, Vite writes dist/.
  for (const candidate of ['out', 'dist']) {
    const src = resolve(projectDir, candidate);
    if (existsSync(resolve(src, 'index.html'))) {
      copyInto(src);
      return done({ kind: 'static', source: `${candidate}/` });
    }
  }

  // Plain app at the project root — a bare `deploy` should just work when
  // server.js (or index.html) sits right there.
  if (existsSync(resolve(projectDir, 'server.js')) || existsSync(resolve(projectDir, 'index.html'))) {
    return stageFolder(projectDir, 'project root');
  }
  return null;
}

// scrubArtifact removes local-only files from a staged artifact, at any depth:
// every .env and .env.* (templates like .env.example too: the running app
// never needs them, and people do put real values in them) and every .git.
// Symlinks are removed as entries, never followed. Returns the removed paths,
// relative to the artifact root, for the one-line notice.
export function scrubArtifact(root) {
  const removed = [];
  const walk = (dir) => {
    let entries;
    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      const full = join(dir, entry.name);
      if (entry.name === '.git' || entry.name === '.env' || entry.name.startsWith('.env.')) {
        rmSync(full, { recursive: true, force: true });
        removed.push(relative(root, full));
      } else if (entry.isDirectory() && !entry.isSymbolicLink()) {
        walk(full);
      }
    }
  };
  walk(root);
  return removed.sort();
}

// detectStaleBuild (CLI-1): `deploy` ships the LAST build as-is — it never
// builds. That contract is invisible in the happy path (users build right
// before deploying) and bites exactly when a dependency or source file changed
// under an existing build: the deploy silently ships old code. Compare the
// build marker's mtime against the newest source file and warn.
// Returns { stale, buildPath, buildMtimeMs, newestSourcePath, newestSourceMtimeMs }
// or null when there is no separate build to compare (no artifact yet, or the
// project root IS the artifact so "source vs build" is meaningless).
export function detectStaleBuild(projectDir, options = {}) {
  // Resolve the build marker with the same search order stageArtifact uses.
  let buildPath = null;
  let excludeDir = null;
  if (typeof options.dir === 'string' && options.dir.trim()) {
    const src = resolve(projectDir, options.dir.trim());
    for (const marker of ['server.js', 'index.html']) {
      if (existsSync(resolve(src, marker))) { buildPath = resolve(src, marker); break; }
    }
    excludeDir = src;
  } else if (existsSync(resolve(projectDir, '.next', 'standalone', 'server.js'))) {
    buildPath = resolve(projectDir, '.next', 'standalone', 'server.js');
  } else {
    for (const candidate of ['out', 'dist']) {
      if (existsSync(resolve(projectDir, candidate, 'index.html'))) {
        buildPath = resolve(projectDir, candidate, 'index.html');
        break;
      }
    }
  }
  if (!buildPath) return null;
  const buildMtimeMs = statSync(buildPath).mtimeMs;

  // Newest source file: walk the project, skipping build outputs and noise.
  // Bounded (files + depth) so a huge tree can't stall the deploy.
  const skip = new Set([...DEFAULT_EXCLUDED_DIRS, '.vercel', '.cache']);
  let newest = { path: null, mtimeMs: 0 };
  let budget = 4000;
  const walk = (d, depth) => {
    if (budget <= 0 || depth > 8) return;
    let entries;
    try { entries = readdirSync(d, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      if (budget-- <= 0) return;
      const full = join(d, entry.name);
      if (entry.isDirectory()) {
        if (skip.has(entry.name) || (excludeDir && full === excludeDir)) continue;
        walk(full, depth + 1);
      } else if (entry.isFile()) {
        if (entry.name === '.env' || entry.name.startsWith('.env.')) continue;
        if (!TEXT_EXTENSIONS.has(extname(entry.name))) continue;
        try {
          const m = statSync(full).mtimeMs;
          if (m > newest.mtimeMs) newest = { path: full, mtimeMs: m };
        } catch { /* raced away */ }
      }
    }
  };
  walk(projectDir, 0);
  if (!newest.path) return null;

  // 2s slack: build outputs are written moments after the last source touch.
  return {
    stale: newest.mtimeMs > buildMtimeMs + 2000,
    buildPath,
    buildMtimeMs,
    newestSourcePath: newest.path,
    newestSourceMtimeMs: newest.mtimeMs,
  };
}

// sdkVersionNudge (CLI-1): a fixed @piezas/sdk only reaches production when the
// app updates + rebuilds + redeploys — and nothing tells users a fix exists.
// Best-effort, never blocks: any failure (offline, timeout, no dep) => null.
export async function sdkVersionNudge(projectDir, fetchFn = fetch) {
  let installed;
  try {
    const pkg = readJsonFile(resolve(projectDir, 'package.json'));
    const spec = pkg.dependencies?.['@piezas/sdk'] ?? pkg.devDependencies?.['@piezas/sdk'];
    if (!spec) return null;
    // Local/workspace links track the repo, not npm — a registry nudge is noise.
    if (/^(file:|link:|workspace:)/.test(spec)) return null;
    installed = readJsonFile(
      resolve(projectDir, 'node_modules', '@piezas', 'sdk', 'package.json'),
    ).version;
    if (!installed) return null;
  } catch { return null; }

  try {
    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), 2000);
    const res = await fetchFn('https://registry.npmjs.org/@piezas/sdk/latest', {
      signal: ac.signal,
      headers: { Accept: 'application/json' },
    });
    clearTimeout(timer);
    if (!res.ok) return null;
    const latest = (await res.json())?.version;
    if (!latest) return null;
    const lt = (a, b) => {
      const pa = String(a).split('.').map(Number);
      const pb = String(b).split('.').map(Number);
      for (let i = 0; i < 3; i++) {
        if ((pa[i] || 0) !== (pb[i] || 0)) return (pa[i] || 0) < (pb[i] || 0);
      }
      return false;
    };
    if (!lt(installed, latest)) return null;
    return (
      `  ℹ @piezas/sdk ${installed} is installed; ${latest} is available with fixes.\n` +
      `     npm install @piezas/sdk@latest   then rebuild and deploy again.`
    );
  } catch { return null; }
}

// hasPiezasEvidence: the shared apps server hosts PIEZAS apps, not arbitrary
// sites. A real Piezas app leaves fingerprints in its build — the traced
// @piezas/sdk in standalone output, or api.piezas.ai / PIEZAS_API_KEY
// references in its code. This client check gives instant feedback; the
// server runs the same check authoritatively.
function hasPiezasEvidence(dir) {
  if (existsSync(resolve(dir, 'node_modules', '@piezas', 'sdk', 'package.json'))) {
    return true;
  }
  const markers = ['api.piezas.ai', '@piezas/sdk', 'PIEZAS_API_KEY'];
  const exts = new Set(['.js', '.mjs', '.cjs', '.html', '.json']);
  let budget = 64 * 1024 * 1024; // hard scan bound
  const walk = (d) => {
    for (const entry of readdirSync(d)) {
      if (entry === 'node_modules') continue; // third-party noise; SDK checked above
      const full = join(d, entry);
      const st = statSync(full);
      if (st.isDirectory()) {
        if (walk(full)) return true;
        continue;
      }
      if (!exts.has(extname(entry).toLowerCase()) || st.size > 4 * 1024 * 1024) continue;
      if ((budget -= st.size) < 0) return false;
      const content = readFileSync(full, 'utf-8');
      if (markers.some((m) => content.includes(m))) return true;
    }
    return false;
  };
  try {
    return walk(dir);
  } catch {
    return true; // scanning trouble must not block a legitimate deploy — the server re-checks
  }
}

// detectOtherRuntime names the ecosystem when a project clearly isn't a
// Node/static app, so the "can't deploy" message can be honest and specific
// instead of offering Next.js advice to a Python developer.
function detectOtherRuntime(projectDir) {
  const signals = [
    ['requirements.txt', 'Python'],
    ['pyproject.toml', 'Python'],
    ['Pipfile', 'Python'],
    ['go.mod', 'Go'],
    ['Cargo.toml', 'Rust'],
    ['Gemfile', 'Ruby'],
    ['composer.json', 'PHP'],
    ['pom.xml', 'Java'],
    ['build.gradle', 'Java'],
  ];
  for (const [file, runtime] of signals) {
    if (existsSync(resolve(projectDir, file))) return runtime;
  }
  return null;
}

// findNextConfig returns the Next config the project ACTUALLY has (first match
// wins, the way Next itself resolves it). Both the deploy diagnosis and the
// doctor preflight name that exact file — generic advice about "next.config" is
// what left users editing the wrong thing.
const NEXT_CONFIG_FILES = ['next.config.js', 'next.config.mjs', 'next.config.ts'];

function findNextConfig(projectDir) {
  for (const name of NEXT_CONFIG_FILES) {
    const path = resolve(projectDir, name);
    if (!existsSync(path)) continue;
    let text = '';
    try { text = readFileSync(path, 'utf-8'); } catch { /* unreadable -> treat as empty */ }
    return { name, path, text };
  }
  return null;
}

// diagnoseNextBuild explains THE deploy-day trap: `npm run build` succeeds,
// `next dev`/`next start` work for days, but next.config never set
// output: 'standalone' — so no .next/standalone/server.js exists and there is
// nothing to ship. Nothing before deploy day needs that line, which is exactly
// why it goes missing. Returns null unless a Next build ran (.next/ present)
// AND a config file exists to name; the generic guidance covers everything else.
function diagnoseNextBuild(projectDir) {
  if (!existsSync(resolve(projectDir, '.next'))) return null;
  const config = findNextConfig(projectDir);
  if (!config) return null;
  return {
    status: config.text.includes('standalone') ? 'rebuild-needed' : 'standalone-missing',
    configFile: config.name,
  };
}

// collectExplicitEnv: deploy NEVER reads the local .env file — the hosted
// runtime's environment lives in the cloud store (console-managed, or staged
// at app creation). The only env that travels with a deploy is what the user
// consciously types as --env KEY=VALUE (the Heroku config:set posture). This
// is a security property, not a convenience trade-off: the CLI has no code
// path that opens .env, so no bug or compromised release can exfiltrate it.
function collectExplicitEnv(options) {
  const sent = {};
  const pairs = Array.isArray(options.envPairs) ? options.envPairs : options.envPairs ? [options.envPairs] : [];
  for (const pair of pairs) {
    const m = /^([A-Za-z_][A-Za-z0-9_]*)=([\s\S]*)$/.exec(String(pair));
    if (m) sent[m[1]] = m[2];
  }
  return sent;
}

// mintAndStageHostedKey mints a live API key for the app (the same
// control-plane call init uses) and stages it into the HOSTED env store —
// bound by durable id, value never shown, never written to any local file.
// Returns { ok, stage, status }: ok=true when the hosted env ends up holding
// PIEZAS_API_KEY; on failure, `stage` names which half broke ('mint' at the
// control plane, or 'stage' at the apps-server) and `status` is its HTTP code,
// so callers can tell the user WHY instead of a bare "could not mint".
async function mintAndStageHostedKey(linked, credentials, options, fetchFn) {
  const env = options.env ?? process.env;
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const minted = await fetchJson(fetchFn,
    `${adminBaseUrl(apiBase)}/v1/tenants/${credentials.tenantId}/api-keys`, {
      token: credentials.cliToken,
      timeoutMs: options.httpTimeoutMs,
      method: 'POST',
      body: { name: linked.appName, environment: 'live', partitionId: linked.appId },
    });
  if (minted.status !== 201 || typeof minted.data?.key !== 'string' || !minted.data.key) {
    return { ok: false, stage: 'mint', status: minted.status };
  }
  const base = appsBaseUrl(options, env);
  const stagedRes = await fetchJson(fetchFn,
    `${base}/v1/deployments/${slugifyAppName(linked.appName)}/env?appId=${encodeURIComponent(linked.appId)}`, {
      token: credentials.cliToken,
      method: 'PATCH',
      body: { set: { PIEZAS_API_KEY: minted.data.key } },
      timeoutMs: 8000,
    });
  return { ok: stagedRes.status === 200, stage: 'stage', status: stagedRes.status };
}

// ensureAppLink resolves this project's durable app identity (the control
// plane app/partition UUID), EB-style: prefer the binding already recorded in
// piezas.manifest.json (deploy.appId, written by init); otherwise pull the
// tenant's app NAMES from the platform and let the user pick — confirming
// identity from the web without any secret involved — then persist the
// binding. Returns null when unlinked and unable to ask.
async function ensureAppLink(projectDir, options, credentials, fetchFn) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  let manifest = null;
  try { manifest = readJsonFile(manifestPath); } catch { /* no manifest yet */ }
  if (manifest?.deploy?.appId) {
    return { appId: manifest.deploy.appId, appName: manifest.appName || basename(projectDir) };
  }

  const env = options.env ?? process.env;
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const adminBase = adminBaseUrl(apiBase);
  // LIST via my-apps: it returns the CALLER's apps — an admin sees all, a
  // developer sees only granted apps — so the picker works for both roles with
  // no client-side role logic. CREATE still targets /partitions (admin-only).
  const myAppsUrl = `${adminBase}/v1/tenants/${credentials.tenantId}/my-apps`;
  const partitionsUrl = `${adminBase}/v1/tenants/${credentials.tenantId}/partitions`;
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  let apps = [];
  let listFailed = false;   // a genuine network failure — the platform was unreachable
  let authFailed = false;   // 401/403 — the session isn't authorized or has expired
  try {
    const res = await fetchJson(fetchFn, myAppsUrl, httpOptions);
    if (res.status === 200 && Array.isArray(res.data?.data)) apps = res.data.data;
    else if (res.status === 401 || res.status === 403) authFailed = true;
    else listFailed = true;
  } catch {
    listFailed = true;
  }

  // --app <name>: auto-link on an exact name/slug match, no prompt needed.
  const wanted = typeof options.app === 'string' && options.app.trim() ? options.app.trim() : null;
  if (wanted) {
    const slug = wanted.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
    const hit = apps.find((a) => a.slug === slug || a.name === wanted);
    if (hit) return persistAppLink(manifestPath, manifest, hit);
  }

  const interactive = options.interactive && options.promptFn !== null;
  const promptFn = options.promptFn ?? promptViaTerminal;

  // createApp: a fresh account (or a deliberate choice) creates the app right
  // here — same control-plane call init uses. No key is minted (that's init's
  // job); hosting only needs the app record to exist.
  const createApp = async () => {
    const def = wanted || manifest?.appName || basename(projectDir);
    const answer = String((await promptFn(`  App name [${def}]: `)) ?? '').trim();
    const name = answer || def;
    const res = await fetchJson(fetchFn, partitionsUrl, { ...httpOptions, method: 'POST', body: { name } });
    if (res.status === 201 && res.data?.id) {
      log(`  Created app "${res.data.name}" — it's in your console now.`);
      const link = persistAppLink(manifestPath, manifest, res.data);
      // App creation provisions the key — same behavior as init and the
      // console welcome flow. The hosted env holds it before first boot.
      if (link) {
        const staged = await mintAndStageHostedKey(link, credentials, options, fetchFn);
        if (staged.ok) {
          log('  Minted its API key and staged it in the hosted environment.');
          log('  (For local development, run `npx piezas init` to write a key into .env.)');
          return { ...link, keyStaged: true };
        }
        log(`  Could not mint/stage its API key automatically (${staged.stage} HTTP ${staged.status}) — you'll be asked before deploy.`);
      }
      return link;
    }
    if (res.status === 401) {
      log('  Your session has expired — run `npx piezas login`, then retry.\n');
      return null;
    }
    if (res.status === 403) {
      // Creating an app is admin-only. A developer who reaches here (empty list,
      // or chose "+ Create") is NOT looped on a dead end — tell them the truth
      // and exactly what unblocks them. Point at an admin; don't imply self-serve.
      log('  Only an admin can create an app, so it can\'t be created from here.');
      log('  Ask an admin to create it (in the console, or from their own CLI) and grant');
      log('  you access. Once you\'re granted, `npx piezas deploy` will find it here.\n');
      return null;
    }
    if (res.status === 409) {
      // Name already taken in this tenant — link to the existing app instead.
      try {
        const l = await fetchJson(fetchFn, myAppsUrl, httpOptions);
        const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
        const hit = (l.data?.data ?? []).find((a) => a.slug === slug || a.name === name);
        if (hit) {
          log(`  App "${hit.name}" already exists — linking this project to it.`);
          return persistAppLink(manifestPath, manifest, hit);
        }
      } catch { /* fall through */ }
    }
    log(`  Could not create the app (HTTP ${res.status}) — try again, or create it in the console.\n`);
    return null;
  };

  // Honest, distinct outcomes when the list yielded nothing to auto-pick from.
  // These are checked in order and each is DIFFERENT from a network failure:
  //   authFailed → the session, not the connection (never "check your connection")
  //   listFailed → a genuine network/unreachable failure (keep the old copy)
  //   empty list → NOT an error: fall through to create; a developer's create
  //                403s into the honest "ask your admin" message (no dead-end loop).
  if (authFailed) {
    log('  Your Piezas session isn\'t authorized (it may have expired) — run `npx piezas login`, then retry.\n');
    return null;
  }
  if (listFailed) {
    log(`  Could not reach ${apiBase} to look up your apps — check your connection and retry.\n`);
    return null;
  }

  if (interactive) {
    if (!apps.length) {
      // Could be a brand-new admin (create succeeds) or a developer with no
      // grants yet (create 403s → "ask your admin"). createApp() branches on the
      // response — either way, there is no dead-end loop.
      return await createApp();
    }
    log('  Which app is this project? (identity confirmed from your account — nothing is uploaded)');
    apps.forEach((a, i) => log(`    ${i + 1}) ${a.name}`));
    log(`    ${apps.length + 1}) + Create a new app`);
    const answer = String((await promptFn(`  Choose 1-${apps.length + 1}: `)) ?? '').trim();
    const idx = Number(answer) - 1;
    if (Number.isInteger(idx) && idx >= 0 && idx < apps.length) {
      return persistAppLink(manifestPath, manifest, apps[idx]);
    }
    if (idx === apps.length) {
      return await createApp();
    }
  }

  log('  This project is not linked to an app yet.');
  log('  Run `npx piezas deploy` from a terminal (interactive) to link or create one,');
  log('  or set deploy.appId in piezas.manifest.json to your app\'s id.\n');
  return null;
}

// persistAppLink records the confirmed identity in the manifest.
function persistAppLink(manifestPath, manifest, app) {
  try {
    const m = manifest ?? {};
    m.appName = app.name;
    m.deploy = { ...(m.deploy || {}), appId: app.id };
    writeFileSync(manifestPath, `${JSON.stringify(m, null, 2)}\n`);
    log(`  Linked to "${app.name}" (${app.id.slice(0, 8)}…) — recorded in piezas.manifest.json`);
  } catch { /* linking is a convenience record; deploy still carries the id */ }
  return { appId: app.id, appName: app.name };
}

// persistDeploySlug records the server-assigned slug + URL in the manifest so
// later `deploy --status/--logs/--delete` target the right deployment.
function persistDeploySlug(projectDir, slug, url) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  try {
    const manifest = readJsonFile(manifestPath);
    manifest.deploy = { ...(manifest.deploy || {}), mode: 'mixed', slug, url };
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  } catch {
    // No manifest (deploy outside an init'd project): skip — slug can still be
    // re-derived from the app name.
  }
}

export async function deploy(options = {}) {
  const env = options.env ?? process.env;
  const projectDir = options.cwd || process.cwd();
  const fetchFn = platformFetch(projectDir, options);
  const sandbox = isSandboxProject(projectDir);
  const base = appsBaseUrl(options, env);

  log('\n  🧱 Piezas deploy\n');

  if (sandbox) log(`  ${SANDBOX_NOTE}\n`);

  if (options.isolated) {
    log('  --isolated gives your app its own infrastructure: a dedicated server,');
    log('  private network, its own database, storage, and access logs — nothing');
    log('  shared with anyone. It\'s how our compliance-heavy clients run today.');
    log('');
    log('  It\'s coming soon. Right now `npx piezas deploy` ships to the shared');
    log('  apps server (--mixed): up to 2 apps free, isolated containers.');
    log('');
    log('  Want early access to isolated mode?  https://app.piezas.ai/contact\n');
    return { exitCode: 1, command: 'deploy', status: 'unsupported-mode' };
  }

  const credentials = platformCredentials(projectDir, env);
  if (!credentials) {
    log('  You need to sign in first: run `npx piezas login`, then retry.\n');
    return { exitCode: 1, command: 'deploy', status: 'not-logged-in' };
  }
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const slug = deploySlugFor(projectDir, options);
  // The durable identity, if this project is linked; lookups prefer it over
  // the (rename-able) slug.
  const knownAppId = (() => {
    try { return readJsonFile(resolve(projectDir, 'piezas.manifest.json')).deploy?.appId ?? null; } catch { return null; }
  })();
  const idQS = knownAppId ? `?appId=${encodeURIComponent(knownAppId)}` : '';

  // --status / --logs / --delete address an existing deployment and skip packaging.
  if (options.status) {
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, httpOptions);
    if (res.status === 404) {
      log(`  No deployment named "${slug}" — run \`npx piezas deploy\` first.\n`);
      return { exitCode: 1, command: 'deploy', status: 'not-found', slug };
    }
    if (res.status !== 200) {
      log(`  Could not fetch status (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}`, slug };
    }
    log(`  ${res.data.slug}: ${res.data.status}`);
    log(`  ${res.data.url}\n`);
    return { exitCode: 0, command: 'deploy', ...res.data };
  }
  if (options.logs) {
    // Bare `--logs` arrives as boolean true — and Number(true) is 1, which
    // would silently tail a single line. Explicit numbers only; else 200.
    const tail = options.logs !== true && Number.isFinite(Number(options.logs)) && Number(options.logs) > 0
      ? Number(options.logs) : 200;
    const res = await fetchJson(fetchFn,
      `${base}/v1/deployments/${slug}/logs?tail=${tail}${knownAppId ? `&appId=${encodeURIComponent(knownAppId)}` : ''}`,
      httpOptions);
    if (res.status !== 200) {
      log(`  Could not fetch logs (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}`, slug };
    }
    console.log(res.data.logs || '(no output yet)');
    return { exitCode: 0, command: 'deploy', slug, status: 'logs' };
  }
  if (options.delete) {
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, { ...httpOptions, method: 'DELETE' });
    if (res.status === 404) {
      log(`  No deployment named "${slug}" — nothing to delete.\n`);
      return { exitCode: 1, command: 'deploy', status: 'not-found', slug };
    }
    if (res.status !== 200) {
      log(`  Could not delete (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}`, slug };
    }
    log(`  Deleted "${slug}" from the apps server — its URL no longer serves.`);
    log('  (The app itself still exists in your console; delete it there if you');
    log('  want the app record and its keys gone too.)\n');
    return { exitCode: 0, command: 'deploy', status: 'deleted', slug };
  }

  // --- the deploy itself ---------------------------------------------------
  // Session preflight (fail fast, clear message). The apps-server accepts this
  // token by SIGNATURE alone, and a linked project reads its appId from the
  // local manifest — so a token whose control-plane SESSION is dead (revoked,
  // or rolled back by a DB restore) stays invisible until the key-mint 401s
  // deep in the flow, after packaging. One cheap authed GET surfaces it here.
  // Only a definitive 401/403 blocks; an unreachable/5xx control plane must
  // never gate a redeploy (the apps-server stays the authoritative enforcer).
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  try {
    // Reach my-apps (any tenant principal can), not partitions (admin-only): a
    // developer's VALID session must not read as "expired" here. A 401/403 from
    // my-apps is therefore a genuinely dead/unauthorized session, worth blocking.
    const ping = await fetchJson(fetchFn,
      `${adminBaseUrl(apiBase)}/v1/tenants/${credentials.tenantId}/my-apps`, httpOptions);
    if (ping.status === 401 || ping.status === 403) {
      log('  Your Piezas session has expired — run `npx piezas login`, then deploy again.');
      log(`  (the control plane rejected the saved token: HTTP ${ping.status})\n`);
      return { exitCode: 1, command: 'deploy', status: 'session-expired', httpStatus: ping.status };
    }
  } catch { /* control plane unreachable — do not gate; downstream calls enforce */ }

  // Identity first (EB-style): confirm WHICH app this is from the platform's
  // own list — by durable id, never by secret — before anything is packaged.
  const linked = await ensureAppLink(projectDir, options, credentials, fetchFn);
  if (!linked) {
    return { exitCode: 1, command: 'deploy', status: 'not-linked' };
  }

  // Hosted-state preflight, BEFORE any packaging: does this app already have a
  // deployment (redeploys are always allowed), and if not, is there a free
  // slot? Refusing here costs milliseconds; refusing after upload costs the
  // user a 50 MB round-trip. The server remains the authoritative enforcer.
  let hostedExists = false;
  let serverKeys = [];
  let hostedAuthFailed = false;   // 401/403 — the session is expired or absent
  try {
    const res = await fetchJson(fetchFn,
      `${base}/v1/deployments/${slug}?appId=${encodeURIComponent(linked.appId)}`, httpOptions);
    if (res.status === 200) {
      hostedExists = true;
      if (Array.isArray(res.data?.envKeys)) serverKeys = res.data.envKeys;
    } else if (res.status === 401 || res.status === 403) {
      hostedAuthFailed = true;
    }
  } catch { /* unreachable -> the server-side checks still hold */ }
  // A rejected session here reads the hosted env as EMPTY, which then misfires
  // the requiredEnv gate as "NOT SET" and blocks the deploy with a misleading
  // env message. ensureAppLink short-circuits on a cached appId, so this
  // preflight is often the FIRST authenticated call — the first place an expired
  // token surfaces. Tell the truth and stop before packaging + a 50 MB upload.
  if (hostedAuthFailed) {
    log('  Your Piezas session isn\'t valid (expired or logged out), so this app\'s');
    log('  hosted settings can\'t be read. Deploying now would wrongly report the');
    log('  environment as empty — run `npx piezas login`, then deploy again.\n');
    return { exitCode: 1, command: 'deploy', status: 'auth-expired' };
  }
  if (!hostedExists) {
    try {
      const lres = await fetchJson(fetchFn, `${base}/v1/deployments`, httpOptions);
      const lim = lres.status === 200 ? lres.data?.limits : null;
      // maxApps <= 0 = unlimited; only positive caps gate.
      if (lim && lim.maxApps > 0 && lim.used >= lim.maxApps) {
        log(`  Your plan already hosts ${lim.used} of ${lim.maxApps} apps — the --mixed limit.`);
        log('  Free a slot (delete an app from its console page), or get early access');
        log('  to dedicated infrastructure: https://app.piezas.ai/contact\n');
        return { exitCode: 1, command: 'deploy', status: 'limit-reached', limits: lim };
      }
    } catch { /* unreachable -> the server-side check still holds */ }
  }

  // Env confirmation on EVERY interactive deploy — new code is exactly when
  // new variables appear, so the reminder rides along each time (one Enter
  // per deploy is cheap insurance against a drifted environment).
  // The platform CANNOT read local .env — by design, like Vercel/EB — so the
  // human vouches against the ACTUAL hosted names shown. CI/non-interactive
  // never blocks; requiredEnv remains the hard gate for declared vars.
  if (options.interactive && options.promptFn !== null) {
    const promptFn = options.promptFn ?? promptViaTerminal;
    log('  Quick settings check before deploying:');
    log('  Apps often need saved settings to work — API keys, passwords for other');
    log('  services (Stripe, OpenAI, ...), and other configuration. Developers call');
    log('  these "environment variables".');
    log('');
    log(`  Settings saved for your LIVE app right now:  ${serverKeys.length ? serverKeys.join(', ') : '(none yet)'}`);
    log('  The .env file on this computer stays private — we never read or upload');
    log('  it — so anything that is ONLY in that file will NOT reach your live app.');
    log('');
    log('  Need to add one?  Easiest:  app.piezas.ai -> your app -> Hosting -> Environment');
    log('                    Terminal: npx piezas env set NAME=value');
    const a = String((await promptFn('  Does your live app have every setting it needs? [Y/n]: ')) ?? '')
      .trim().toLowerCase();
    if (a === 'n' || a === 'no') {
      log('  Good call — add the settings, then run deploy again.\n');
      return { exitCode: 1, command: 'deploy', status: 'env-not-confirmed' };
    }
  } else if (serverKeys.length) {
    log(`  Live app settings: ${serverKeys.join(', ')} (the local .env file is never read)`);
  }

  // The deploy attestation (warn-only in v1). `npx piezas test` writes it; we
  // report it in one line and carry it to the platform, which is where
  // "untested cannot ship" will actually get teeth. Blocking here would only teach people to deploy around the CLI.
  const attestation = readTestAttestation(projectDir);
  const attestationNote = attestationWarning(attestation);
  if (attestationNote) log(`  ⚠ ${attestationNote}`);

  const { mkdtempSync, rmSync, statSync: stat } = await import('fs');
  const { tmpdir } = await import('os');
  const staging = mkdtempSync(join(tmpdir(), 'piezas-deploy-'));
  const tarball = join(tmpdir(), `piezas-artifact-${Date.now()}.tar.gz`);
  try {
    log('  Packaging your built app...');
    const staged = stageArtifact(projectDir, staging, options);
    if (!staged) {
      // A non-Node project deserves the truth, not Next.js build advice: the
      // shared apps server runs Node and static apps today. Other runtimes
      // arrive with dedicated infrastructure (--isolated / image deploys).
      const otherRuntime = detectOtherRuntime(projectDir);
      if (otherRuntime) {
        log(`  This looks like a ${otherRuntime} app. The shared apps server currently`);
        log('  runs Node.js and static apps — other runtimes are coming with dedicated');
        log('  infrastructure (--isolated).');
        log('');
        log('  Your app can still USE Piezas from any language — every service is a');
        log('  plain HTTPS API (https://api.piezas.ai/<service>/openapi.json). Hosting');
        log('  is the only Node-specific part today.');
        log('');
        log(`  Want ${otherRuntime} hosting early?  https://app.piezas.ai/contact\n`);
        return { exitCode: 1, command: 'deploy', status: 'unsupported-runtime', runtime: otherRuntime };
      }
      // A built Next app that produced no standalone server is not a "build
      // first" problem — the user already built. Name the file and the line.
      // (--dir points the deploy at an explicit folder, so the miss is that
      // folder, not the Next config.)
      const usingExplicitDir = typeof options.dir === 'string' && Boolean(options.dir.trim());
      const nextDiagnosis = usingExplicitDir ? null : diagnoseNextBuild(projectDir);
      if (nextDiagnosis?.status === 'standalone-missing') {
        log(`  Your Next build succeeded, but ${nextDiagnosis.configFile} does not set  output: 'standalone',`);
        log('  so the build never produced .next/standalone/server.js — the bundle deploy ships.');
        log('');
        log('  Fix (one line + rebuild):');
        log(`    1. add    output: 'standalone',   to the config object in ${nextDiagnosis.configFile}`);
        log('    2. npm run build');
        log('    3. npx piezas deploy\n');
        return {
          exitCode: 1,
          command: 'deploy',
          status: 'standalone-missing',
          configFile: nextDiagnosis.configFile,
        };
      }
      if (nextDiagnosis?.status === 'rebuild-needed') {
        log('  Rebuild needed: run  npm run build  then deploy again.');
        log(`  (${nextDiagnosis.configFile} is right — it sets output: 'standalone' — but`);
        log('  .next/standalone/server.js is missing or stale. Deploy ships the build');
        log('  output as-is; it never builds.)\n');
        return {
          exitCode: 1,
          command: 'deploy',
          status: 'rebuild-needed',
          configFile: nextDiagnosis.configFile,
        };
      }
      log('  Nothing deployable found. Build first:');
      log('    server app:  next.config output: "standalone"   then   npm run build');
      log('    static app:  a build that produces out/ or dist/ with index.html');
      log('  (or point at a folder with --dir <path> whose root has server.js or index.html)\n');
      return { exitCode: 1, command: 'deploy', status: 'no-artifact' };
    }
    if (!hasPiezasEvidence(staging)) {
      log('  This build doesn\'t reference Piezas anywhere — no @piezas/sdk, no');
      log('  api.piezas.ai calls. The free apps server hosts Piezas apps only.');
      log('  If that\'s unexpected, make sure you\'re deploying the right folder;');
      log('  if you need general hosting, contact us about paid plans.\n');
      return { exitCode: 1, command: 'deploy', status: 'not-piezas-app' };
    }

    // CLI-1: deploy ships the build AS-IS (it never builds) — surface the two
    // silent traps: a build older than the source, and an outdated SDK that a
    // fix will never reach without update + rebuild + redeploy. Warn, never block.
    const staleness = detectStaleBuild(projectDir, options);
    if (staleness?.stale) {
      log('');
      log('  ⚠ Your build looks STALE — source files changed after it was built:');
      log(`     changed:   ${relative(projectDir, staleness.newestSourcePath)}  (${new Date(staleness.newestSourceMtimeMs).toLocaleString()})`);
      log(`     built:     ${relative(projectDir, staleness.buildPath)}  (${new Date(staleness.buildMtimeMs).toLocaleString()})`);
      log('     Deploy ships the build output as-is, so those changes will NOT go live.');
      log('     To include them:  npm run build   then deploy again.');
      log('');
    }
    const nudge = await sdkVersionNudge(projectDir, fetchFn);
    if (nudge) log(nudge);

    execSync(`tar -czf ${JSON.stringify(tarball)} -C ${JSON.stringify(staging)} .`);
    const size = stat(tarball).size;
    const limitMB = resolveMaxArtifactMB(env);
    if (size > limitMB * 1024 * 1024) {
      log(`  Artifact is ${(size / 1024 / 1024).toFixed(0)} MB — the limit is ${limitMB} MB per app.`);
      log('  Large media belongs in the Documents service, not the app bundle.');
      log('  (Piezas hosting has its own size limit; the local cap can be raised with PIEZAS_MAX_ARTIFACT_MB.)\n');
      return { exitCode: 1, command: 'deploy', status: 'too-large' };
    }
    log(`  Packaged ${staged.kind} app from ${staged.source} (${(size / 1024 / 1024).toFixed(1)} MB)`);
    if (staged.removed?.length) {
      const envFiles = staged.removed.filter((p) => !p.split('/').includes('.git'));
      if (envFiles.length) log(`  Left out ${envFiles.join(', ')} (local only), it is never uploaded.`);
    }

    const appName = linked.appName;

    // Env: deploy transmits ONLY values explicitly typed as --env KEY=VALUE.
    // The hosted runtime's environment is the cloud store — PIEZAS_API_KEY is
    // provisioned there when the app is created, and everything else is set
    // in the console (Hosting -> Environment). The local .env file is never
    // read: it belongs to local development.
    const sent = collectExplicitEnv(options);
    const sentNames = Object.keys(sent).sort();
    if (sentNames.length) {
      log(`  Env: sending ${sentNames.join(', ')} (typed via --env)`);
      const localish = sentNames.filter((k) => /localhost|127\.0\.0\.1/.test(String(sent[k])));
      if (localish.length) {
        log(`  Warning: ${localish.join(', ')} point${localish.length === 1 ? 's' : ''} at localhost — the hosted app cannot reach your machine.`);
      }
    }

    // Two-way env verification, client half. The manifest declares what the
    // app NEEDS (deploy.requiredEnv — coding agents keep it updated as they
    // add integrations); each requirement is checked against the CLOUD env
    // (names only, pulled from the platform) plus any typed --env pairs. If
    // anything is missing we refuse to upload, naming it precisely. The
    // server re-verifies the same list post-merge (the second half).
    let required = [];
    try {
      const man = readJsonFile(resolve(projectDir, 'piezas.manifest.json'));
      if (Array.isArray(man?.deploy?.requiredEnv)) {
        required = man.deploy.requiredEnv.filter((k) => typeof k === 'string' && k.trim());
      }
    } catch { /* no manifest -> nothing declared */ }
    // serverKeys was fetched in the pre-packaging preflight above.
    if (required.length) {
      const effective = new Set([...serverKeys, ...Object.keys(sent)]);
      const missing = required.filter((k) => !effective.has(k));
      log('  Hosted environment check (set at app.piezas.ai -> your app -> Hosting):');
      for (const k of required) {
        const how = sent[k] !== undefined ? '(sending via --env)' : serverKeys.includes(k) ? '(set in console)' : 'NOT SET';
        log(`    ${effective.has(k) ? '✓' : '✗'} ${k}  ${how}`);
      }
      if (missing.length) {
        // Couldn't read ANY hosted env (no deployment record returned) AND every
        // required var reads missing: the frequent cause is a STALE CLI session,
        // not a genuinely-empty environment. The apps-server returns empty rather
        // than 401 for a token whose control-plane session was revoked or rolled
        // back (see the preflight note above), so the real settings are invisible
        // until you re-auth — `npx piezas env ls` shows the same emptiness. Lead
        // with login; a genuinely first-time-empty deploy loses nothing by trying.
        const likelyStaleSession = !hostedExists && serverKeys.length === 0;
        log('');
        if (likelyStaleSession) {
          log('  Could not read ANY hosted settings for this app. If you already set');
          log('  them, your CLI session is probably stale — refresh it, then retry:');
          log('    npx piezas login        # then: npx piezas deploy');
          log('  (Confirm with `npx piezas env ls` — if it also shows nothing, it is');
          log('  the session, not your settings.)');
          log('');
          log('  If the environment really is empty, set the values:');
        } else {
          log('  Not deploying — the app declares env it would boot without.');
          log('  Set the missing values first (either way works):');
        }
        log(`    console:  app.piezas.ai -> your app -> Hosting -> Environment`);
        log(`    terminal: npx piezas deploy ${missing.map((k) => `--env ${k}=...`).join(' ')}\n`);
        return { exitCode: 1, command: 'deploy', status: 'missing-env', missing, likelyStaleSession };
      }
    }

    // A Piezas SERVER app without PIEZAS_API_KEY in its hosted env would boot
    // and then 401 on every backend call — the evidence gate already proved
    // this app calls Piezas, so shipping it keyless ships it broken. HARD
    // GATE: block, but first offer to fix it right here (mint + stage — the
    // same provisioning app creation does). Static apps are exempt (no
    // server-side key), and a typed --env PIEZAS_API_KEY counts.
    if (staged.kind === 'server' && !linked.keyStaged
      && !serverKeys.includes('PIEZAS_API_KEY') && !sent.PIEZAS_API_KEY) {
      log('  This app has no PIEZAS_API_KEY in its hosted environment — it would');
      log('  deploy, boot, and then fail every Piezas call.');
      let fixed = false;
      let mint;
      if (options.interactive && options.promptFn !== null) {
        const promptFn = options.promptFn ?? promptViaTerminal;
        const a = String((await promptFn('  Mint an API key for this app and stage it now? [Y/n] ')) ?? '')
          .trim().toLowerCase();
        if (a === '' || a === 'y' || a === 'yes') {
          mint = await mintAndStageHostedKey(linked, credentials, options, fetchFn);
          fixed = mint.ok;
          if (mint.ok) {
            log('  Key minted and staged in the hosted environment — continuing.');
          } else if (mint.status === 401 || mint.status === 403) {
            log(`  Could not mint the key — your session was rejected (HTTP ${mint.status}).`);
            log('  Run `npx piezas login`, then deploy again.');
          } else {
            log(`  Could not mint/stage the key automatically (${mint.stage} HTTP ${mint.status}).`);
          }
        }
      }
      if (!fixed) {
        log('  Set it first (any of these), then deploy again:');
        log('    console:   app.piezas.ai -> your app -> Hosting -> Environment');
        log('    terminal:  npx piezas env set PIEZAS_API_KEY=sk_live_...');
        log('    local dev: npx piezas init   (mints a key and writes your local .env)\n');
        return {
          exitCode: 1, command: 'deploy', status: 'missing-piezas-key',
          mintStatus: mint?.status, mintStage: mint?.stage,
        };
      }
    }

    const form = new FormData();
    form.set('app', appName);
    form.set('appId', linked.appId);
    form.set('kind', staged.kind);
    form.set('env', JSON.stringify(sent));
    // Always sent, `null` included: the platform must be able to tell "this
    // deploy was never tested" from "this client is too old to say".
    form.set('attestation', JSON.stringify(attestation ?? null));
    if (required.length) form.set('requiredEnv', JSON.stringify(required));
    if (typeof options.cmd === 'string' && options.cmd.trim()) form.set('cmd', options.cmd.trim());
    form.set('artifact', new Blob([readFileSync(tarball)]), 'app.tar.gz');
    // The owner's confirmation of exactly the findings they were shown (typed
    // "deploy anyway" in their AI tool, or answered at the terminal prompt).
    const acknowledged = options.acknowledge || confirmedDeployRisk(projectDir);
    if (acknowledged) form.set('acknowledgeHardNo', acknowledged);

    log(`  Uploading to ${base} ...`);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), options.deployTimeoutMs ?? DEPLOY_TIMEOUT_MS);
    let res;
    try {
      const raw = await fetchFn(`${base}/v1/deployments`, {
        method: 'POST',
        headers: { authorization: `Bearer ${credentials.cliToken}` },
        body: form,
        signal: controller.signal,
      });
      let data;
      try { data = await raw.json(); } catch { data = undefined; }
      res = { status: raw.status, data };
    } finally {
      clearTimeout(timer);
    }

    if (res.status === 401) {
      log('  Your session has expired — run `npx piezas login`, then retry.\n');
      return { exitCode: 1, command: 'deploy', status: 'unauthorized' };
    }
    if (res.status === 409 && res.data?.needsConfirmation) {
      return await deployNeedsConfirmation(projectDir, options, res.data);
    }
    if (res.status !== 201) {
      log(`  Deploy failed (HTTP ${res.status}): ${res.data?.error || 'unknown error'}`);
      if (res.data?.logs) {
        log('  --- app output ---');
        console.log(res.data.logs);
      }
      log('');
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}` };
    }

    if (acknowledged) clearPendingDeployRisk(projectDir);
    persistDeploySlug(projectDir, res.data.slug, res.data.url);
    log('');
    log(`  ✓ Live at ${res.data.url}${sandbox ? '  (simulated — nothing was published)' : ''}`);
    // The server's never-rule scan (warn mode): live, but the owner must know.
    for (const f of Array.isArray(res.data.hardNo) ? res.data.hardNo : []) {
      const what = f.rule === 'local-database'
        ? `the app keeps its own local database (${f.detail})`
        : `the Piezas key is visible to every visitor (${f.path})`;
      log(`  ⚠ Piezas check: ${what}. Fix this soon — the platform will start refusing it.`);
    }
    log('  Status any time:  npx piezas deploy --status');
    log('  Logs:             npx piezas deploy --logs\n');
    return { exitCode: 0, command: 'deploy', ...res.data };
  } catch (error) {
    log(`  Deploy failed: ${error?.message || error}\n`);
    return { exitCode: 1, command: 'deploy', status: 'error' };
  } finally {
    try { rmSync(staging, { recursive: true, force: true }); } catch { /* best-effort */ }
    try { unlinkSync(tarball); } catch { /* may not exist */ }
  }
}

// envCmd implements `piezas env ls|set KEY=VALUE|rm KEY` against the HOSTED
// environment (the cloud store the app actually runs with). ls prints names
// only — values are write-only everywhere, terminal included.
export async function envCmd(options = {}) {
  const env = options.env ?? process.env;
  const projectDir = options.cwd || process.cwd();
  const fetchFn = platformFetch(projectDir, options);
  const base = appsBaseUrl(options, env);

  if (isSandboxProject(projectDir)) log(`  ${SANDBOX_NOTE}\n`);

  const credentials = platformCredentials(projectDir, env);
  if (!credentials) {
    log('  You need to sign in first: run `npx piezas login`, then retry.\n');
    return { exitCode: 1, command: 'env', status: 'not-logged-in' };
  }
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const slug = deploySlugFor(projectDir, options);
  const appId = (() => {
    try { return readJsonFile(resolve(projectDir, 'piezas.manifest.json')).deploy?.appId ?? null; } catch { return null; }
  })();
  const idQS = appId ? `?appId=${encodeURIComponent(appId)}` : '';

  const action = options.action;
  if (action === 'ls' || action === undefined) {
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, httpOptions);
    if (res.status === 404) {
      log('  No hosted environment yet — set a variable (here or in the console) to create it.');
      log('  Expected settings here? Your CLI session may be stale — run `npx piezas login` and retry.\n');
      return { exitCode: 0, command: 'env', status: 'empty', keys: [] };
    }
    if (res.status !== 200) {
      log(`  Could not read the hosted environment (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'env', status: `http-${res.status}` };
    }
    const keys = res.data.envKeys ?? [];
    log(`  Hosted env for ${res.data.slug} (${res.data.status}) — names only, values are write-only:`);
    for (const k of keys) log(`    ${k}`);
    if (!keys.length) log('    (none set)');
    log('');
    return { exitCode: 0, command: 'env', status: 'ok', keys };
  }

  if (action === 'set' || action === 'rm') {
    const body = { set: {}, unset: [] };
    const refusedEmpty = [];
    for (const arg of options.args ?? []) {
      if (action === 'set') {
        const m = /^([A-Za-z_][A-Za-z0-9_]*)=([\s\S]*)$/.exec(String(arg));
        if (!m) {
          log(`  Skipping "${arg}" — expected KEY=VALUE.`);
          continue;
        }
        // An empty value is almost always a shell-expansion bug (KEY=$TYPO
        // expands to KEY=) — and it "succeeds" silently, leaving the app to
        // fail in ways that take an evening to trace back here. Refuse unless
        // the emptiness is explicit.
        if (m[2] === '' && !options.allowEmpty) {
          log(`  Refusing to set ${m[1]} to an EMPTY value — usually an unset shell variable.`);
          log(`    Meant it? Re-run with --allow-empty, or remove the variable with: env rm ${m[1]}`);
          refusedEmpty.push(m[1]);
          continue;
        }
        body.set[m[1]] = m[2];
      } else {
        body.unset.push(String(arg));
      }
    }
    // Atomic: one empty value aborts the WHOLE call. Applying the good keys
    // while a script's `&& deploy` sails past the refused one would recreate
    // exactly the silent breakage this guard exists to stop.
    if (refusedEmpty.length) {
      log(`  Nothing was applied — fix the empty value${refusedEmpty.length > 1 ? 's' : ''} and re-run.\n`);
      return { exitCode: 2, command: 'env', status: 'empty-value', refusedEmpty };
    }
    if (!Object.keys(body.set).length && !body.unset.length) {
      log(`  Nothing to ${action === 'set' ? 'set — pass KEY=VALUE' : 'remove — pass the variable name'}.\n`);
      return { exitCode: 2, command: 'env', status: 'usage' };
    }
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}/env${idQS}`, {
      ...httpOptions, method: 'PATCH', body,
    });
    if (res.status !== 200) {
      log(`  Could not update the hosted environment (HTTP ${res.status}): ${res.data?.error || ''}\n`);
      return { exitCode: 1, command: 'env', status: `http-${res.status}` };
    }
    const what = [...Object.keys(body.set), ...body.unset].join(', ');
    log(`  Hosted env updated (${what}).${res.data.status === 'not deployed' ? ' Staged — in place before first deploy.' : ' App restarted.'}\n`);
    return { exitCode: 0, command: 'env', status: 'ok', keys: res.data.envKeys ?? [] };
  }

  log(`  Unknown env action "${action}" — use ls, set KEY=VALUE, or rm KEY.\n`);
  return { exitCode: 2, command: 'env', status: 'usage' };
}

// --- End piezas deploy -----------------------------------------------------

function detectPackageManager(projectDir) {
  if (existsSync(resolve(projectDir, 'pnpm-lock.yaml'))) return 'pnpm';
  if (existsSync(resolve(projectDir, 'yarn.lock'))) return 'yarn';
  if (existsSync(resolve(projectDir, 'bun.lockb'))) return 'bun';
  return 'npm';
}

// hasSdkDependency reports whether package.json already declares @piezas/sdk
// (e.g. a `file:` tarball pin for testing a local build). Init must not clobber
// such a pin by re-adding the published package from the registry.
function hasSdkDependency(projectDir) {
  const pkgJsonPath = resolve(projectDir, 'package.json');
  if (!existsSync(pkgJsonPath)) return false;
  try {
    const pkg = JSON.parse(readFileSync(pkgJsonPath, 'utf8'));
    return Boolean(
      pkg?.dependencies?.['@piezas/sdk'] || pkg?.devDependencies?.['@piezas/sdk'],
    );
  } catch {
    return false;
  }
}

// --- The served platform contract ----------------------------------------

// resolveContractUrl: caller-supplied option > PIEZAS_CONTRACT_URL env > the
// canonical service. Mirrors resolveApiBase so staging can point elsewhere.
function resolveContractUrl(options = {}, env = process.env) {
  const fromOption = typeof options.contractUrl === 'string' && options.contractUrl.trim()
    ? options.contractUrl.trim()
    : undefined;
  const fromEnv = typeof env.PIEZAS_CONTRACT_URL === 'string' && env.PIEZAS_CONTRACT_URL.trim()
    ? env.PIEZAS_CONTRACT_URL.trim()
    : undefined;
  return (fromOption || fromEnv || DEFAULT_CONTRACT_URL).replace(/\/+$/, '');
}

// fetchContract asks the service for the LIVE contract and returns
// { version, updatedAt, etag, content } — or null on ANY failure: offline,
// timeout, non-200, unparseable body, no content, no version. It never throws.
// The caller turns a null into a clear, aborting error (init is fetch-only —
// there is no bundle to fall back to), and a contract with no version is treated
// as unusable rather than written unstamped: doctor could never tell whether
// such a copy had gone stale.
export async function fetchContract(fetchFn, url, timeoutMs = CONTRACT_TIMEOUT_MS) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetchFn(url, {
      headers: { accept: 'application/json' },
      signal: controller.signal,
    });
    if (!response || response.status !== 200) return null;
    const data = await response.json();
    const content = typeof data?.content === 'string' ? data.content.trim() : '';
    const version = data?.version === undefined || data?.version === null
      ? ''
      : String(data.version).trim();
    if (!content || !version) return null;
    return {
      version,
      updatedAt: typeof data.updatedAt === 'string' ? data.updatedAt : null,
      etag: typeof data.etag === 'string' ? data.etag : null,
      content,
    };
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

// fetchSpec mirrors fetchContract for the spec-first workflow doc, which the
// service serves as MARKDOWN (no JSON envelope, no version). On 200 it returns
// the trimmed body; on ANY failure — offline, timeout, non-200, empty — it
// returns null. It never throws.
export async function fetchSpec(fetchFn, url, timeoutMs = CONTRACT_TIMEOUT_MS) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetchFn(url, {
      headers: { accept: 'text/markdown' },
      signal: controller.signal,
    });
    if (!response || response.status !== 200) return null;
    const body = typeof response.text === 'function' ? await response.text() : '';
    const trimmed = typeof body === 'string' ? body.trim() : '';
    return trimmed || null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

// The single, actionable message init prints when a served doc can't be
// reached. Fetch-only means a miss is a hard stop, not a silent bundle swap.
function unreachableContractError(url) {
  return new Error(
    `Couldn't reach Piezas to fetch the platform contract at ${url}. ` +
      'Check your connection (or set PIEZAS_CONTRACT_URL) and try again.',
  );
}

// resolveContract fetches the LIVE contract and turns it into everything init
// needs to write: the body to put in the agent files, the provenance stamp that
// says where it came from, and the version/date to record in the manifest.
// Fetch-only: a miss THROWS rather than falling back to a bundled copy.
// bundledFile — a copy of the contract/spec shipped next to the CLI (the plugin
// bundles them in rules/). Used ONLY by sandbox init when the network is
// unreachable (e.g. Codex's default sandbox has no network). A real init stays
// download-only: the served contract is canonical.
function bundledFile(options, name) {
  const dir = options.bundledDir ?? join(dirname(fileURLToPath(import.meta.url)), '..', 'rules');
  try {
    return readFileSync(join(dir, name), 'utf-8');
  } catch {
    return null;
  }
}

const RULE_TOPICS = ['entities', 'users', 'integrations', 'calendar', 'documents', 'deploy', 'testing', 'patterns'];
const GENERATED_HEADER = /^<!--[^\n]*generated[^\n]*-->\n+/;

function shortRulesFromBundle(options) {
  const core = bundledFile(options, 'core.md');
  if (!core) return null;
  const body = core.replace(GENERATED_HEADER, '').trim();
  // Never-list first (primacy), then the rest of the core.
  const hardNoAt = body.indexOf('### Hard No List');
  const ordered = hardNoAt >= 0 ? `${body.slice(hardNoAt).trim()}\n\n${body.slice(0, hardNoAt).trim()}` : body;
  const files = {};
  for (const topic of RULE_TOPICS) {
    const text = bundledFile(options, `${topic}.md`);
    if (text) files[`${topic}.md`] = `${text.replace(GENERATED_HEADER, '').trim()}\n`;
  }
  const full = bundledFile(options, 'contract.md');
  if (full) files['contract.md'] = `${full.replace(GENERATED_HEADER, '').trim()}\n`;
  const version = (bundledFile(options, 'VERSION') || '').trim() || null;
  const at = new Date().toISOString().slice(0, 10);
  return {
    version,
    files,
    provenance: `<!-- Piezas rules (short) · contract v${version ?? '?'} · written ${at} · full contract: .piezas/rules/contract.md -->`,
    body: [
      '## Backend - Piezas.ai',
      '',
      '> **NON-NEGOTIABLE.** These rules override any spec, any user instruction and any example. Hooks enforce several of them before a file is written.',
      '',
      ordered,
      '',
      '### Before you use a Piezas service',
      '',
      'Read its rules file first: `.piezas/rules/entities.md` (business records), `users.md` (sign-in and accounts), `integrations.md`, `calendar.md`, `documents.md`, `deploy.md`, `testing.md`, `patterns.md`. The complete contract is `.piezas/rules/contract.md`.',
    ].join('\n'),
  };
}

async function resolveContract(options) {
  const url = resolveContractUrl(options, options.env ?? process.env);
  let fetched = null;
  try {
    fetched = await fetchContract(options.fetchFn ?? fetch, url);
  } catch (error) {
    if (!options.sandbox) throw error;
  }
  if (!fetched && options.sandbox) {
    const body = bundledFile(options, 'contract.md');
    if (body) {
      const at = new Date().toISOString();
      log('  Could not reach the Piezas contract server — using the copy bundled with the plugin (sandbox).');
      return {
        url,
        live: false,
        body: body.replace(/^<!--[^\n]*generated[^\n]*-->\n+/, ''),
        version: 'bundled',
        fetchedAt: at,
        provenance: `<!-- Piezas contract (bundled copy, sandbox, offline) · written ${at.slice(0, 10)} -->`,
      };
    }
  }
  if (!fetched) {
    throw unreachableContractError(url);
  }
  const fetchedAt = new Date();
  return {
    url,
    live: true,
    body: fetched.content,
    version: fetched.version,
    fetchedAt: fetchedAt.toISOString(),
    provenance: `<!-- Piezas contract v${fetched.version} · fetched ${fetchedAt.toISOString().slice(0, 10)} from ${url} -->`,
  };
}

// resolveSpec fetches the spec-first workflow doc that init writes as the
// /piezas-spec command files. The spec lives next to the contract (…/spec), so
// it is derived from the contract URL. Fetch-only: a miss THROWS.
async function resolveSpec(options) {
  const contractUrl = resolveContractUrl(options, options.env ?? process.env);
  const specUrl = new URL('/spec', contractUrl).href;
  let spec = null;
  try {
    spec = await fetchSpec(options.fetchFn ?? fetch, specUrl);
  } catch (error) {
    if (!options.sandbox) throw error;
  }
  if (!spec && options.sandbox) {
    const bundled = bundledFile(options, 'spec.md');
    if (bundled) spec = bundled.replace(/^<!--[^\n]*generated[^\n]*-->\n+/, '').trimEnd();
  }
  if (!spec) {
    throw unreachableContractError(contractUrl);
  }
  // Trailing newline keeps the written command files stable (the old bundled
  // constant ended in one, and writeIfNew markers expect it).
  return `${spec}\n`;
}

export async function init(options = {}) {
  const previousEmit = emit;
  const previousSink = detailSink;
  if (options.json) {
    emit = (message) => process.stderr.write(`${message}\n`);
  }
  detailSink = options.verbose ? null : [];
  let summary;
  try {
    summary = await runInit(options);
    if (detailSink) summary.files = detailSink.filter(Boolean);
  } finally {
    emit = previousEmit;
    detailSink = previousSink;
  }

  if (options.json) {
    console.log(JSON.stringify(summary, null, 2));
  }
  return { exitCode: 0, ...summary };
}

// askStartQuestion — the same first question the plugin asks, in a terminal.
async function askStartQuestion(options) {
  const promptFn = options.promptFn ?? promptViaTerminal;
  log('  Starting fresh, or do you already have an app?');
  log('    1) Starting fresh');
  log('    2) I already have an app (built with Lovable, Claude Code or anything else)');
  const choice = String((await promptFn('  Choose 1 or 2 [1]: ')) ?? '').trim();
  if (choice !== '2') return undefined;
  const where = cleanTypedPath(await promptFn('  Where is it on your computer? Drag the folder here or type its path: '));
  if (!where) throw new Error('No folder given. Run piezas init again and point to the folder that holds your app.');
  return where;
}

function appNameFromImport(source) {
  try {
    const pkg = JSON.parse(readFileSync(join(source, 'package.json'), 'utf-8'));
    const name = typeof pkg.name === 'string' ? pkg.name.replace(/^@[^/]+\//, '') : '';
    if (name && !/^(vite[_-]react[_-]|my-|app$|vite-project$)/i.test(name)) {
      return name.replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
    }
  } catch {
    // no package.json — fall back to the folder name
  }
  return basename(source).replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

async function runInit(options) {
  const currentDir = options.cwd || process.cwd();
  const targetArg = options.targetArg;
  log('\n  🧱 Piezas.ai\n');

  let importFrom = typeof options.import === 'string' && options.import.trim() ? cleanTypedPath(options.import) : undefined;
  if (!importFrom && options.askStart && options.interactive && !options.yes) {
    importFrom = await askStartQuestion(options);
  }
  const importSource = importFrom ? resolve(currentDir, importFrom) : undefined;
  const projectDir = importSource
    ? importDestination(importSource, currentDir, targetArg && targetArg !== '.' ? targetArg : (targetArg === '.' ? currentDir : undefined))
    : targetArg && targetArg !== '.'
      ? resolve(currentDir, targetArg)
      : currentDir;
  if (importSource && !options.app) options = { ...options, app: appNameFromImport(importSource) };

  // Inside Claude Code or Codex the rules travel with the Piezas plugin (short
  // rules + checks that run as the app is built). A CLI run there without the
  // plugin still writes the short rules when it has them, and says plainly that
  // the checks are off until the plugin is installed.
  const host = options.host !== undefined ? options.host : agentHost(options.env ?? process.env);
  const fromPlugin = options.fromPlugin ?? runningFromPlugin();
  if (host && !options.shortRules && bundledFile(options, 'core.md')) options = { ...options, shortRules: true };
  const hadAppCode = !importSource && existsSync(projectDir) && appSourceFiles(projectDir, listFiles(projectDir)).length > 0;
  const deploymentMode = options.deploymentMode || DEFAULT_DEPLOYMENT_MODE;
  const productType = options.productType || 'custom-app';
  const mcpRequested = Boolean(options.mcp);
  const appName = typeof options.app === 'string' && options.app.trim() ? options.app.trim() : undefined;

  // The contract and the spec-first workflow are SERVED — fetch both live,
  // BEFORE writing anything, and stamp the contract we wrote. This CLI is a thin
  // client: there is no bundled copy to fall back to, so a fetch miss aborts
  // init with a clear message rather than scaffolding a project around rules the
  // platform may no longer have. Fetching up front means a miss writes NO
  // project files.
  const contract = await resolveContract(options);
  const specInstructions = await resolveSpec(options);
  // --short-rules (the plugin's path): the instruction files carry the ~3 KB
  // core with the never-list FIRST; topic rules and the full contract go to
  // .piezas/rules/ to be read on demand. Long files lose rules mid-session, and
  // Codex reads only the first 32 KB of AGENTS.md (the served contract is 42 KB).
  const short = options.shortRules ? shortRulesFromBundle(options) : null;
  if (options.shortRules && !short) {
    log('  Short rules need the files bundled with the Piezas plugin — writing the full contract instead.');
  }
  const instructions = short
    ? instructionsBlock(short.provenance, short.body)
    : instructionsBlock(contract.provenance, contract.body);

  let copy = null;
  if (importSource) {
    copy = copyImportedApp(importSource, projectDir);
    log(`  Copied your app into ${projectDir}. Your original folder was not changed.`);
  } else if (!existsSync(projectDir)) {
    mkdirSync(projectDir, { recursive: true });
    detail(`  Created ${targetArg}`);
  } else if (projectDir !== currentDir) {
    detail(`  Using ${targetArg}`);
  }

  ensurePackageJson(projectDir);

  if (options.skipInstall) {
    detail('  Skipped @piezas/sdk install');
  } else if (hasSdkDependency(projectDir)) {
    detail('  Preserving existing @piezas/sdk dependency (pin left untouched)');
  } else {
    log('  Installing the Piezas tools...');
    const pm = detectPackageManager(projectDir);
    try {
      execSync(`${pm} add @piezas/sdk`, { cwd: projectDir, stdio: 'pipe' });
      detail('  Installed @piezas/sdk');
    } catch {
      log('  Failed to install - run manually: npm install @piezas/sdk\n');
    }
  }

  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  const manifest = upsertManifest(manifestPath, {
    deploymentMode,
    productType,
    recipes: options.recipes,
    mcp: mcpRequested,
    appName,
    contractVersion: contract.version,
    contractFetchedAt: contract.fetchedAt,
  });

  if (options.sandbox && manifest && manifest.sandbox !== true) {
    // Mark the project BEFORE any platform call: from here on the simulator
    // answers every control-plane and hosting request for this folder.
    manifest.sandbox = true;
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  }
  if (options.sandbox) {
    options = { ...options, fromLogin: true };
    detail(`  ${SANDBOX_NOTE}`);
  }

  if (short) {
    const rulesDir = resolve(projectDir, STATE_DIR, 'rules');
    if (safeMkdir(rulesDir)) {
      for (const [name, content] of Object.entries(short.files)) writeFileSync(join(rulesDir, name), content);
      detail(`  Wrote .piezas/rules/ (${Object.keys(short.files).length} topic files, read on demand)`);
    }
    if (manifest) {
      manifest.rules = 'short';
      if (short.version) manifest.contractVersion = short.version;
      writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
    }
  }

  const piezasDir = resolve(projectDir, '.piezas');
  mkdirSync(piezasDir, { recursive: true });
  // The spec BUILDER is a local template, not the served spec doc: it teaches
  // the exact R-/S- formats `npx piezas spec check` validates, so it ships with
  // the binary that enforces them and can never drift from the checker. The
  // served spec doc still drives the /piezas-spec commands below.
  writeIfNew(
    resolve(piezasDir, 'spec-builder.md'),
    specBuilderTemplate(),
    '.piezas/spec-builder.md (Piezas spec mode)',
    { startMarker: PIEZAS_SPEC_START, appendIfNoMarker: false },
  );

  writeIfNew(resolve(projectDir, 'CLAUDE.md'), instructions, 'CLAUDE.md');

  const commandsDir = resolve(projectDir, '.claude', 'commands');
  safeMkdir(commandsDir);
  writeIfNew(
    resolve(commandsDir, 'piezas.md'),
    instructions,
    '.claude/commands/piezas.md (Claude Code slash command)',
  );
  writeIfNew(
    resolve(commandsDir, 'piezas-spec.md'),
    specInstructions,
    '.claude/commands/piezas-spec.md (Claude Code spec command)',
    { startMarker: PIEZAS_SPEC_START, appendIfNoMarker: false },
  );

  const cursorRulesPath = resolve(projectDir, '.cursor', 'rules', 'piezas.mdc');
  safeMkdir(dirname(cursorRulesPath));
  writeIfNew(
    cursorRulesPath,
    `---\ndescription: Use Piezas backend APIs and SDK\nalwaysApply: true\n---\n\n${instructions}`,
    '.cursor/rules/piezas.mdc',
  );
  writeIfNew(resolve(projectDir, '.cursorrules'), instructions, '.cursorrules');

  // Spec mode as a NATIVE command in the other agent tools. Rules files alone
  // don't cut it: a bare "/piezas-spec" is swallowed by the client before the
  // model sees it unless the tool has its own command file (Claude Code got
  // .claude/commands/piezas-spec.md above).
  const cursorCmdPath = resolve(projectDir, '.cursor', 'commands', 'piezas-spec.md');
  safeMkdir(dirname(cursorCmdPath));
  writeIfNew(
    cursorCmdPath,
    specInstructions,
    '.cursor/commands/piezas-spec.md (Cursor command)',
    { startMarker: PIEZAS_SPEC_START, appendIfNoMarker: false },
  );

  const windsurfWorkflowPath = resolve(projectDir, '.windsurf', 'workflows', 'piezas-spec.md');
  safeMkdir(dirname(windsurfWorkflowPath));
  writeIfNew(
    windsurfWorkflowPath,
    `---\ndescription: Piezas spec mode - interview one question at a time, write SPEC.md, stop\n---\n\n${specInstructions}`,
    '.windsurf/workflows/piezas-spec.md (Windsurf workflow)',
    { startMarker: PIEZAS_SPEC_START, appendIfNoMarker: false },
  );

  // Codex reads repo-level .codex/prompts on current versions; older ones only
  // read ~/.codex/prompts (the log below tells the user about the copy).
  const codexPromptPath = resolve(projectDir, '.codex', 'prompts', 'piezas-spec.md');
  safeMkdir(dirname(codexPromptPath));
  writeIfNew(
    codexPromptPath,
    specInstructions,
    '.codex/prompts/piezas-spec.md (Codex prompt)',
    { startMarker: PIEZAS_SPEC_START, appendIfNoMarker: false },
  );
  detail('  Codex note: if /piezas-spec is not offered, your Codex only reads global prompts - run: mkdir -p ~/.codex/prompts && cp .codex/prompts/piezas-spec.md ~/.codex/prompts/');

  writeIfNew(resolve(projectDir, 'AGENTS.md'), `# Project Instructions\n\n${instructions}`, 'AGENTS.md');
  writeIfNew(resolve(projectDir, '.windsurfrules'), instructions, '.windsurfrules');
  const mcpScaffold = scaffoldMcpRoute(projectDir, deploymentMode, mcpRequested);
  // The scenario harness: the BUILD gate needs one test per S-nnn, and that is
  // only cheap when the config, the smoke test and the seed stub already exist.
  const harness = scaffoldTestHarness(projectDir);

  const gitignoreUpdated = ensureGitignore(projectDir);

  const envPath = resolve(projectDir, '.env');
  const resolved = await resolveApiKey(envPath, projectDir, options);
  let apiKeyStatus = 'missing';
  let keyFormatWarning = false;
  if (resolved.key) {
    if (!API_KEY_FORMAT.test(resolved.key) && !options.sandbox) {
      keyFormatWarning = true;
      log('  Warning: the key does not look like sk_live_... / sk_test_... - using it anyway.');
    }
    const action = writeEnvKey(envPath, resolved.key);
    apiKeyStatus = action === 'kept' ? 'configured' : 'written';
    if (action === 'created') detail('  Created .env with PIEZAS_API_KEY');
    if (action === 'appended') detail('  Added PIEZAS_API_KEY to .env');
    if (action === 'replaced') detail('  Replaced PIEZAS_API_KEY in .env');
    // The key alone is not enough: without the gateway URL the SDK defaults
    // every service to localhost and a fresh hosted project ECONNREFUSEDs on
    // its first call. Write where the API lives next to the key that opens it.
    const apiBase = options.apiBaseUrl || DEFAULT_API_BASE_URL;
    const urlAction = writeEnvVar(envPath, 'PIEZAS_API_URL', apiBase);
    if (urlAction !== 'kept') detail(`  Set PIEZAS_API_URL=${apiBase} in .env`);
    // A --wait drop file other than .env itself is a transfer vehicle holding
    // the secret un-gitignored — remove it once the key lives in .env.
    if (resolved.sourceFile && resolved.sourceFile !== '.env') {
      try {
        unlinkSync(resolve(projectDir, resolved.sourceFile));
        log(`  Removed ${resolved.sourceFile} (key moved to .env)`);
      } catch {
        log(`  Warning: could not remove ${resolved.sourceFile} - delete it yourself; it contains your key and is not git-ignored.`);
      }
    }
  }

  // Record what the platform told us about the created app: the display name
  // and — critically — deploy.appId, the durable identity every later
  // `piezas deploy` uses to target the right app without guessing by name.
  if (manifest && (resolved.appName || resolved.appId)) {
    let changed = false;
    if (resolved.appName && manifest.appName !== resolved.appName) {
      manifest.appName = resolved.appName;
      changed = true;
    }
    if (resolved.appId && manifest.deploy?.appId !== resolved.appId) {
      manifest.deploy = { ...(manifest.deploy || {}), appId: resolved.appId };
      changed = true;
    }
    if (changed) {
      try {
        writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
      } catch {
        // ignore — manifest metadata is informational
      }
    }
  }

  // The guided build (describe -> see it -> build -> go live) starts for every
  // new or imported app. A project that already had code and no Piezas state
  // is left as it was: locking its code mid-build would be a surprise.
  const guided = Boolean(options.sandbox || importSource || !hadAppCode);
  if (guided) phaseInit(projectDir);
  const imported = copy ? recordImport(projectDir, copy) : null;

  const finalName = manifest?.appName ?? appName ?? basename(projectDir);
  printStartSummary({
    appName: finalName,
    projectDir,
    currentDir,
    sandbox: Boolean(options.sandbox),
    copy,
    imported,
    guided,
    apiKeyStatus,
    host,
    fromPlugin,
    mcpScaffold,
  });

  return {
    command: 'init',
    projectDir,
    harness: harness.created,
    apiKey: apiKeyStatus,
    apiKeySource: resolved.source,
    envPath,
    gitignoreUpdated,
    cursorRulesPath,
    appName: manifest?.appName ?? appName ?? null,
    apiBaseUrl: manifest?.apiBaseUrl ?? DEFAULT_API_BASE_URL,
    manifestPath,
    keyFormatWarning,
    phase: guided ? 'discover' : null,
    imported: copy ? { source: copy.source, dest: copy.dest, files: copy.files, leftOut: copy.leftOut } : null,
    host: host ?? null,
    checks: host ? (fromPlugin ? 'on' : 'off') : null,
  };
}

// printStartSummary — the one message a person reads after setup, the same
// whether they ran it in a terminal or their AI tool ran it for them. File by
// file detail is in the JSON summary (and on screen with --verbose).
function printStartSummary(info) {
  const { appName, projectDir, currentDir, sandbox, copy, imported, guided, apiKeyStatus, host, fromPlugin, mcpScaffold } = info;
  log('');
  log(sandbox
    ? `  ✓ ${appName} is set up on a practice version of Piezas. Everything works the same way; nothing is published.`
    : `  ✓ ${appName} is set up for Piezas.`);
  log('  ✓ Your AI tool now follows the Piezas rules for this app.');
  if (copy) {
    log(`  ✓ Your app was copied here: ${projectDir}`);
    if (copy.leftOut.length) log(`    Left out on purpose: ${copy.leftOut.join(', ')} (installed packages, history, build output and private settings are never copied).`);
    if (projectDir !== currentDir) log(`    Open that folder in your AI tool to continue.`);
  }
  if (imported) {
    const must = imported.mustMove.length;
    const offer = imported.canTakeOver.length;
    log(`  ✓ Checked your code: ${must === 0 ? 'nothing that must move' : `${must} thing${must === 1 ? '' : 's'} that must move to Piezas`}, ${offer === 0 ? 'nothing else to take over' : `${offer} thing${offer === 1 ? '' : 's'} Piezas can take over`}.`);
  }
  log('');
  if (guided) {
    log('  What happens next:');
    log(copy
      ? '    1. Describe the app: your AI tool reads your code and describes the app for you to check.'
      : '    1. Describe the app: tell your AI tool what it is for, and it asks the rest.');
    log('    2. See it: a clickable preview to approve.');
    log('    3. Build it on Piezas.');
    log('    4. Put it live.');
  } else {
    log('  Next: ask your AI tool for what you want to change. It now follows the Piezas rules.');
  }
  if (apiKeyStatus === 'missing' && !sandbox) {
    log('');
    log('  Not connected to a Piezas account yet: run `npx piezas login`, then run `npx piezas init` again.');
  }
  if (host && !fromPlugin) {
    log('');
    log(`  Safety checks: off in ${HOST_NAMES[host]} until the Piezas plugin is installed. They check every change as the app is built.`);
    log(`    ${PLUGIN_HINT[host]}`);
  }
  if (mcpScaffold?.enabled) {
    log('');
    log(`  MCP route: ${mcpScaffold.routePath} (protect with app auth before public use)`);
  }
  log('');
}

function readJsonFile(filePath) {
  return JSON.parse(readFileSync(filePath, 'utf-8'));
}

function lineNumber(content, index) {
  if (index < 0) return undefined;
  return content.slice(0, index).split('\n').length;
}

function addFinding(findings, severity, code, message, file, line) {
  findings.push({ severity, code, message, file, line });
}

function isTextFile(filePath) {
  const name = basename(filePath);
  return (
    TEXT_EXTENSIONS.has(extname(filePath)) ||
    name.startsWith('.env') ||
    name === '.gitignore' ||
    name === '.cursorrules' ||
    name === '.windsurfrules'
  );
}

function isCodeFile(filePath) {
  return CODE_EXTENSIONS.has(extname(filePath));
}

function listFiles(projectDir) {
  const files = [];

  function walk(dir) {
    for (const entry of readdirSync(dir)) {
      if (DEFAULT_EXCLUDED_DIRS.has(entry)) {
        continue;
      }

      const fullPath = join(dir, entry);
      const stat = statSync(fullPath);
      if (stat.isDirectory()) {
        walk(fullPath);
      } else if (stat.isFile() && isTextFile(fullPath)) {
        files.push(fullPath);
      }
    }
  }

  walk(projectDir);
  return files;
}

function normalizeRel(projectDir, filePath) {
  return relative(projectDir, filePath).replaceAll('\\', '/');
}

function loadManifest(projectDir, findings) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  if (!existsSync(manifestPath)) {
    addFinding(
      findings,
      'warn',
      'PZ000',
      'Missing piezas.manifest.json. Run `npx piezas init` so agents and doctor share a source of truth.',
    );
    return {
      exists: false,
      path: manifestPath,
      manifest: buildDefaultManifest({ deploymentMode: 'unknown' }),
    };
  }

  try {
    return {
      exists: true,
      path: manifestPath,
      manifest: readJsonFile(manifestPath),
    };
  } catch (error) {
    addFinding(
      findings,
      'error',
      'PZ000',
      `piezas.manifest.json is not valid JSON: ${error.message}`,
      'piezas.manifest.json',
    );
    return {
      exists: false,
      path: manifestPath,
      manifest: buildDefaultManifest({ deploymentMode: 'unknown' }),
    };
  }
}

function packageJson(projectDir) {
  const packagePath = resolve(projectDir, 'package.json');
  if (!existsSync(packagePath)) return undefined;
  try {
    return readJsonFile(packagePath);
  } catch {
    return undefined;
  }
}

function hasServerRuntimeArtifact(rel, content) {
  return (
    /^app\/api\/.+\/route\.[cm]?[tj]sx?$/.test(rel) ||
    /^pages\/api\//.test(rel) ||
    /(^|\/)middleware\.[cm]?[tj]s$/.test(rel) ||
    /['"]use server['"]/.test(content)
  );
}

function hasClientDirective(content) {
  return /^\s*['"]use client['"]/.test(content);
}

function scanSecretExposure(projectDir, files, findings) {
  for (const filePath of files) {
    const rel = normalizeRel(projectDir, filePath);
    if (!isCodeFile(filePath) && !basename(rel).startsWith('.env')) continue;
    const content = readFileSync(filePath, 'utf-8');
    const nextPublicIndex = content.indexOf('NEXT_PUBLIC_PIEZAS_API_KEY');
    if (nextPublicIndex >= 0) {
      addFinding(
        findings,
        'error',
        'PZ001',
        'PIEZAS_API_KEY must never use a NEXT_PUBLIC_ prefix.',
        rel,
        lineNumber(content, nextPublicIndex),
      );
    }

    if (hasClientDirective(content)) {
      for (const secret of ['PIEZAS_API_KEY', 'ADMIN_PASS', 'ADMIN_TOKEN', 'GOOGLE_CLIENT_SECRET', 'ZOOM_CLIENT_SECRET']) {
        const secretIndex = content.indexOf(secret);
        if (secretIndex >= 0) {
          addFinding(
            findings,
            'error',
            'PZ001',
            `${secret} is referenced from a client component. Keep secrets server-side only.`,
            rel,
            lineNumber(content, secretIndex),
          );
        }
      }
    }

    if (basename(rel).startsWith('.env') && content.includes('PIEZAS_API_KEY=')) {
      const gitignorePath = resolve(projectDir, '.gitignore');
      const gitignore = existsSync(gitignorePath) ? readFileSync(gitignorePath, 'utf-8') : '';
      if (!/(^|\n)\.env(\n|$)|(^|\n)\.env\*/.test(gitignore)) {
        addFinding(
          findings,
          'warn',
          'PZ001',
          '.env contains PIEZAS_API_KEY but .gitignore does not clearly ignore .env files.',
          rel,
        );
      }
    }
  }
}

function scanDeploymentMode(projectDir, files, manifest, findings) {
  if (manifest.deploymentMode !== 'static') {
    return;
  }

  for (const filePath of files) {
    if (!isCodeFile(filePath)) continue;
    const rel = normalizeRel(projectDir, filePath);
    const content = readFileSync(filePath, 'utf-8');
    if (hasServerRuntimeArtifact(rel, content)) {
      addFinding(
        findings,
        'error',
        'PZ002',
        'Static deployment mode cannot use API routes, middleware, or server actions.',
        rel,
      );
    }
    if (content.includes('PIEZAS_API_KEY') || content.includes('ADMIN_PASS') || content.includes('ADMIN_TOKEN')) {
      addFinding(
        findings,
        'error',
        'PZ002',
        'Static deployment mode cannot use server-only secrets in deployed app code.',
        rel,
      );
    }
  }
}

function scanLocalDatabase(projectDir, files, findings) {
  const pkg = packageJson(projectDir);
  const deps = {
    ...(pkg?.dependencies || {}),
    ...(pkg?.devDependencies || {}),
  };
  for (const packageName of LOCAL_DB_PACKAGES) {
    if (deps[packageName]) {
      addFinding(
        findings,
        'warn',
        'PZ003',
        `Detected ${packageName}. Do not create local database tables for Piezas-backed business records.`,
        'package.json',
      );
    }
  }

  for (const filePath of files) {
    const rel = normalizeRel(projectDir, filePath);
    if (/(^|\/)(schema\.prisma|drizzle\.config\.)/.test(rel)) {
      addFinding(
        findings,
        'warn',
        'PZ003',
        'Detected local database schema/config. Confirm this is not duplicating Piezas-owned data.',
        rel,
      );
    }
  }
}

function scanOAuthTokenStorage(projectDir, files, findings) {
  const tokenPattern = /\b(access_token|refresh_token|oauth_token|id_token)\b/i;
  for (const filePath of files) {
    if (!isCodeFile(filePath)) continue;
    const rel = normalizeRel(projectDir, filePath);
    if (rel.includes('.test.')) continue;
    const content = readFileSync(filePath, 'utf-8');
    const match = tokenPattern.exec(content);
    if (match) {
      addFinding(
        findings,
        'warn',
        'PZ004',
        'OAuth tokens should live in Piezas Integrations, not app storage or app database records.',
        rel,
        lineNumber(content, match.index),
      );
    }
  }
}

function scanAdminTokenInUrl(projectDir, files, findings) {
  for (const filePath of files) {
    if (!isCodeFile(filePath)) continue;
    const rel = normalizeRel(projectDir, filePath);
    const content = readFileSync(filePath, 'utf-8');
    const hasTokenQuery =
      /searchParams[\s\S]{0,300}\btoken\b/.test(content) ||
      /\?token=/.test(content) ||
      /method=["']get["'][\s\S]{0,300}name=["']token["']/.test(content);
    const hasAdminContext =
      /ADMIN_TOKEN|ADMIN_PASS|getOptionalAdminToken|admin token|Admin token/i.test(content) ||
      /(^|\/)admin(\/|$)/.test(rel);

    if (hasTokenQuery && hasAdminContext) {
      addFinding(
        findings,
        'error',
        'PZ005',
        'Do not put admin tokens/passwords in query params. Use a POST login and HTTP-only session cookie or an auth role.',
        rel,
        lineNumber(content, content.indexOf('searchParams')),
      );
    }
  }
}

function scanHiddenTimeTrust(projectDir, files, findings) {
  for (const filePath of files) {
    if (!isCodeFile(filePath)) continue;
    const rel = normalizeRel(projectDir, filePath);
    const content = readFileSync(filePath, 'utf-8');
    if (!/name=["']startTime["']/.test(content) || !/type=["']hidden["']/.test(content)) continue;
    if (!/formData\.get\(["']startTime["']\)/.test(content)) continue;
    if (!/create(Public)?Booking|book(ing)?/i.test(content)) continue;

    const serverActionIndex = content.search(/['"]use server['"]/);
    const serverActionBody = serverActionIndex >= 0 ? content.slice(serverActionIndex) : content;
    if (!/listAvailableSlots|isSlotAvailable|validate.*Slot|revalidate.*Slot/i.test(serverActionBody)) {
      addFinding(
        findings,
        'error',
        'PZ006',
        'Public booking flow appears to trust a hidden startTime. Re-fetch availability and validate the slot server-side before booking.',
        rel,
        lineNumber(content, content.indexOf('startTime')),
      );
    }
  }
}

function dynamicParamsFromPath(rel) {
  const params = [];
  const pattern = /\[([A-Za-z0-9_]+)\]/g;
  let match = pattern.exec(rel);
  while (match) {
    params.push(match[1]);
    match = pattern.exec(rel);
  }
  return params;
}

function scanUnusedDynamicRoutes(projectDir, files, findings) {
  for (const filePath of files) {
    const rel = normalizeRel(projectDir, filePath);
    if (!/(^|\/)(page|route)\.[cm]?[tj]sx?$/.test(rel)) continue;
    const params = dynamicParamsFromPath(rel);
    if (params.length === 0) continue;

    const content = readFileSync(filePath, 'utf-8');
    for (const param of params) {
      const uses = content.match(new RegExp(`\\b${param}\\b`, 'g')) || [];
      if (uses.length <= 1) {
        addFinding(
          findings,
          'warn',
          'PZ007',
          `Dynamic route param [${param}] appears unused. Public routes should use all identity/scope params to avoid collisions.`,
          rel,
        );
      }
    }
  }
}

function scanIntegrationActions(projectDir, files, findings) {
  const actionPattern = /['"](?:google_calendar|zoom|hubspot|salesforce|slack|gmail)\.[A-Za-z0-9_.-]+['"]/g;
  for (const filePath of files) {
    if (!isCodeFile(filePath)) continue;
    const rel = normalizeRel(projectDir, filePath);
    if (rel.includes('.test.')) continue;
    const content = readFileSync(filePath, 'utf-8');
    const actions = content.match(actionPattern);
    if (!actions) continue;

    if (!/connector\.actions|connectors\.[A-Za-z0-9_]*actions|\.actions\b|capabilities/i.test(content)) {
      addFinding(
        findings,
        'warn',
        'PZ008',
        'Hardcoded integration action IDs found without checking connector action metadata first.',
        rel,
        lineNumber(content, content.indexOf(actions[0].slice(1, -1))),
      );
    }
  }
}

// callArgumentText: the source of a call's argument list, given the index of
// its opening '('. Depth-tracks parens so nested calls are handled, and is
// BOUNDED so an unbalanced paren inside a string literal cannot run the scan to
// the end of the file.
function callArgumentText(content, openParen) {
  if (openParen < 0) return '';
  const limit = Math.min(content.length, openParen + 600);
  let depth = 0;
  for (let i = openParen; i < limit; i += 1) {
    const ch = content[i];
    if (ch === '(') depth += 1;
    else if (ch === ')') {
      depth -= 1;
      if (depth === 0) return content.slice(openParen + 1, i);
    }
  }
  return content.slice(openParen + 1, limit);
}

// scanAuthEmailReturnUrl (PZ013): forgotPassword / requestEmailVerification send
// an email whose link points at the app's reset/verify page. Without an explicit
// returnUrl the link falls back to the platform/APP_BASE_URL default — which is
// exactly how invite and reset emails went out pointing at localhost:3000. This
// is the one control a coding agent silently drops as its context window fills,
// so doctor ENFORCES it here instead of trusting the SDK docs to stay read. When
// the platform gains a registered per-app URL (server-side default), this check
// gets relaxed to account for it; today, omitting returnUrl ships a broken link.
const AUTH_EMAIL_METHODS = ['forgotPassword', 'requestEmailVerification'];

function scanAuthEmailReturnUrl(projectDir, files, findings) {
  for (const filePath of files) {
    if (!isCodeFile(filePath)) continue;
    const rel = normalizeRel(projectDir, filePath);
    if (rel.includes('.test.')) continue;
    const content = readFileSync(filePath, 'utf-8');
    for (const method of AUTH_EMAIL_METHODS) {
      const callPattern = new RegExp(`\\.${method}\\s*\\(`, 'g');
      let match = callPattern.exec(content);
      while (match) {
        const openParen = content.indexOf('(', match.index);
        const args = callArgumentText(content, openParen);
        if (!/\breturnUrl\b/.test(args)) {
          addFinding(
            findings,
            'error',
            'PZ013',
            `${method}() is missing a returnUrl, so the emailed link falls back to the platform default `
              + `(this is how invite/reset emails shipped pointing at localhost). Pass `
              + `{ returnUrl: 'https://<your-app>/<reset-or-verify-page>' }; its origin must be in the app's `
              + `allowedOrigins (configurePolicy) or the send is rejected.`,
            rel,
            lineNumber(content, match.index),
          );
        }
        match = callPattern.exec(content);
      }
    }
  }
}

function projectHasServerRisk(projectDir, files) {
  return files.some((filePath) => {
    const rel = normalizeRel(projectDir, filePath);
    const content = readFileSync(filePath, 'utf-8');
    return hasServerRuntimeArtifact(rel, content);
  });
}

function scanCoverageConfig(projectDir, files, findings) {
  const vitestConfig = files.find((filePath) => /(^|\/)vitest\.config\.[cm]?[tj]s$/.test(normalizeRel(projectDir, filePath)));
  if (!vitestConfig || !projectHasServerRisk(projectDir, files)) return;

  const rel = normalizeRel(projectDir, vitestConfig);
  const content = readFileSync(vitestConfig, 'utf-8');
  if (/coverage\s*:\s*\{[\s\S]*include\s*:/.test(content) && !/['"`](src\/)?app\/|['"`]app\/|route\.[cm]?[tj]s/.test(content)) {
    addFinding(
      findings,
      'warn',
      'PZ009',
      'Coverage include list appears to exclude app/API/server-action code. Coverage may look high while risky routes remain untested.',
      rel,
      lineNumber(content, content.indexOf('include')),
    );
  }
}

function scanPackageScripts(projectDir, findings) {
  const pkg = packageJson(projectDir);
  if (!pkg) return;
  const nextVersion = pkg.dependencies?.next || pkg.devDependencies?.next;
  const major = Number(String(nextVersion || '').replace(/^[^0-9]*/, '').split('.')[0]);
  if (major >= 16 && pkg.scripts?.lint?.includes('next lint')) {
    addFinding(
      findings,
      'warn',
      'PZ010',
      '`next lint` is not reliable with this Next.js version. Use ESLint directly or update the lint script.',
      'package.json',
    );
  }
}

// Deploy-day preflight: in a server mode, `npx piezas deploy` ships
// .next/standalone/server.js. A Next config without output: 'standalone' still
// builds, dev-runs, and starts — the miss stays invisible until the first
// deploy fails. Catch it while the app is being written instead.
function scanNextStandaloneOutput(projectDir, manifest, findings) {
  if (!SERVER_DEPLOYMENT_MODES.has(manifest.deploymentMode)) return;
  const config = findNextConfig(projectDir);
  if (!config || config.text.includes('standalone')) return;
  addFinding(
    findings,
    'warn',
    'PZ011',
    `${config.name} does not set output: 'standalone', so the build produces no `
      + '.next/standalone/server.js for `npx piezas deploy` to ship. Add '
      + `output: 'standalone', to the config object in ${config.name}, then run npm run build.`,
    config.name,
  );
}

// ===========================================================================
// Delivery-protocol rules (PZ020..PZ026).
//
// These are the BUILD gate's mechanical half.
// Each message is written as a machine-generated prompt: what is wrong, then
// the one line that fixes it — a verdict failure is a work order, not a wall.
// ===========================================================================

// App source = the code this app actually ships. Tests, scripts and tool
// configs are excluded on purpose: a fixture importing sqlite, or a Playwright
// config reading PW_BASE_URL, is the harness doing it, not the app.
const NON_APP_DIRS = /(^|\/)(tests?|__tests__|e2e|scripts)\//;
const TEST_FILE_NAME = /\.(test|spec)\.[cm]?[jt]sx?$/;
const CONFIG_FILE_NAME = /(^|\/)[A-Za-z0-9_.-]*\.config\.[cm]?[jt]sx?$/;

function isAppSource(filePath, rel) {
  return isCodeFile(filePath) && !NON_APP_DIRS.test(rel) && !TEST_FILE_NAME.test(rel) && !CONFIG_FILE_NAME.test(rel);
}

function appSourceFiles(projectDir, files) {
  return files
    .map((filePath) => ({ filePath, rel: normalizeRel(projectDir, filePath) }))
    .filter((entry) => isAppSource(entry.filePath, entry.rel));
}

function escapeForRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// PZ020 — business records belong to the platform. A local table is a second
// source of truth that nothing else in the system can see.
const LOCAL_DB_IMPORTS = [
  '@prisma/client', 'better-sqlite3', 'drizzle-orm', 'knex', 'mongoose', 'mysql2', 'pg', 'prisma', 'sqlite3',
];
const LOCAL_DB_IMPORT = new RegExp(
  `(?:from|import|require)\\s*\\(?\\s*['"\`](${LOCAL_DB_IMPORTS.map(escapeForRegExp).join('|')})(?:/[^'"\`]*)?['"\`]`,
);
const CREATE_TABLE = /\bCREATE\s+TABLE\b/i;

function scanLocalDatabaseUsage(projectDir, files, findings) {
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    const imported = LOCAL_DB_IMPORT.exec(content);
    const created = imported ? null : CREATE_TABLE.exec(content);
    if (!imported && !created) continue;
    const what = imported ? `imports ${imported[1]}` : 'creates a table with raw SQL (CREATE TABLE)';
    addFinding(
      findings,
      'error',
      'PZ020',
      `Piezas-backed business data must not live in a local database — ${rel} ${what}. `
        + 'Move those records to the Piezas services through @piezas/sdk and delete the local schema.',
      rel,
      lineNumber(content, (imported ?? created).index),
    );
  }
}

// PZ021 — a NEXT_PUBLIC_/VITE_/PUBLIC_ prefix means "compiled into the browser
// bundle". A secret with that prefix is already published.
// PUBLISHABLE keys are browser-safe by design (users service public path; the
// contract tells apps to ship them with a public prefix), so they are exempt.
// So is Supabase's "anon" key: it is public by design (row-level security
// protects the data). Its service_role key is a full-access secret and is not.
const PUBLIC_SECRET_NAME = /\b(?:NEXT_PUBLIC|VITE|PUBLIC)_(?![A-Z0-9_]*PUBLISHABLE)(?![A-Z0-9_]*SUPABASE_ANON_KEY\b)[A-Z0-9_]*(?:KEY|SECRET|TOKEN|PASSWORD)[A-Z0-9_]*\b/g;

function scanPublicSecretNames(projectDir, files, findings) {
  for (const filePath of files) {
    const rel = normalizeRel(projectDir, filePath);
    const isEnvFile = basename(rel).startsWith('.env');
    if (!isEnvFile && !isAppSource(filePath, rel)) continue;
    const content = readFileSync(filePath, 'utf-8');
    const seen = new Set();
    PUBLIC_SECRET_NAME.lastIndex = 0;
    let match = PUBLIC_SECRET_NAME.exec(content);
    while (match) {
      if (!seen.has(match[0])) {
        seen.add(match[0]);
        addFinding(
          findings,
          'error',
          'PZ021',
          `${match[0]} ships to the browser: the NEXT_PUBLIC_/VITE_/PUBLIC_ prefix publishes it to every visitor. `
            + `Drop the public prefix, read the value server-side only, and rotate the credential if it has been deployed.`,
          rel,
          lineNumber(content, match.index),
        );
      }
      match = PUBLIC_SECRET_NAME.exec(content);
    }
  }
}

// PZ022 — a Next app that runs server code must build a standalone server, or
// there is nothing for `piezas deploy` to ship. PZ011 asks the same question of
// the DECLARED deployment mode; this one asks it of the app as written.
function hasNextServerSurface(projectDir, files) {
  return files.some((filePath) => {
    const rel = normalizeRel(projectDir, filePath);
    return (
      /^(src\/)?app\/api\//.test(rel) ||
      /^(src\/)?pages\/api\//.test(rel) ||
      /^(src\/)?middleware\.[cm]?[tj]s$/.test(rel)
    );
  });
}

function scanStandaloneOutputRequired(projectDir, files, findings) {
  const pkg = packageJson(projectDir);
  if (!pkg?.dependencies?.next && !pkg?.devDependencies?.next) return;
  if (!hasNextServerSurface(projectDir, files)) return;
  const config = findNextConfig(projectDir);
  if (config && /output\s*:\s*['"`]standalone['"`]/.test(config.text)) return;
  addFinding(
    findings,
    'error',
    'PZ022',
    `This Next app runs server code (API routes or middleware), but ${config ? config.name : 'no next.config.js|mjs|ts'} `
      + "sets output: 'standalone' — so the build produces no .next/standalone/server.js and the deploy has nothing to ship. "
      + `Add output: 'standalone', to ${config ? config.name : 'a next.config.mjs'}, then run npm run build.`,
    config?.name ?? 'next.config.mjs',
  );
}

// PZ023 — the manifest's requiredEnv is what `piezas deploy` checks against the
// HOSTED environment before it uploads. A variable the app reads but never
// declares is a variable that boots missing, in production, silently.
const ENV_READ = /process\.env\s*(?:\.\s*([A-Za-z_][A-Za-z0-9_]*)|\[\s*['"`]([A-Za-z_][A-Za-z0-9_]*)['"`]\s*\])/g;
// Provided by the runtime or provisioned by the platform — never declared.
const AUTO_PROVISIONED_ENV = new Set(['NODE_ENV', 'PORT', 'HOSTNAME', 'PIEZAS_API_KEY', 'PIEZAS_API_URL']);

function scanRequiredEnvAccuracy(projectDir, files, manifest, findings) {
  const declared = new Set(
    Array.isArray(manifest?.deploy?.requiredEnv)
      ? manifest.deploy.requiredEnv.filter((name) => typeof name === 'string')
      : [],
  );
  const missing = new Map();
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    ENV_READ.lastIndex = 0;
    let match = ENV_READ.exec(content);
    while (match) {
      const name = match[1] ?? match[2];
      if (name && !AUTO_PROVISIONED_ENV.has(name) && !declared.has(name) && !missing.has(name)) {
        missing.set(name, rel);
      }
      match = ENV_READ.exec(content);
    }
  }
  if (missing.size === 0) return;
  const names = [...missing.keys()].sort();
  addFinding(
    findings,
    'error',
    'PZ023',
    `The app reads env this project never declares: ${names.join(', ')}. `
      + 'Add them to deploy.requiredEnv in piezas.manifest.json (deploy verifies that list against the hosted '
      + 'environment and refuses to upload an app that would boot without it).',
    'piezas.manifest.json',
  );
}

// PZ024 — one commit is all it takes. Unlike PZ001 (which only speaks up when
// .env already holds a Piezas key) this asks the question unconditionally.
function scanEnvIgnored(projectDir, findings) {
  const gitignorePath = resolve(projectDir, '.gitignore');
  const exists = existsSync(gitignorePath);
  const covered = exists
    && readFileSync(gitignorePath, 'utf-8')
      .split(/\r?\n/)
      .some((line) => GITIGNORE_ENV_PATTERNS.has(line.trim()));
  if (covered) return;
  addFinding(
    findings,
    'error',
    'PZ024',
    `.env is not git-ignored (${exists ? '.gitignore has no .env pattern' : 'there is no .gitignore'}) — one commit `
      + 'publishes every key in it. Add a line reading .env to .gitignore (or run `npx piezas init`, which writes it).',
    '.gitignore',
  );
}

// PZ025 — the BUILD gate, reported where the agent is already looking. Doctor
// repeats spec check + scenario coverage verbatim: same rule ids, same named
// gaps, so the repair prompt is identical wherever it is read.
function scanScenarioCoverage(projectDir, findings) {
  if (!existsSync(join(projectDir, SPEC_FILE))) return;
  const gaps = [...checkSpec(projectDir).gaps, ...checkCoverage(projectDir).gaps];
  const seen = new Set();
  for (const entry of gaps) {
    const key = `${entry.rule}: ${entry.message}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const fix = entry.rule === 'COVERAGE'
      ? 'Write that scenario test, then re-run `npx piezas spec coverage`.'
      : 'Close the gap with the customer in SPEC.md, then re-run `npx piezas spec check`.';
    addFinding(findings, 'error', 'PZ025', `${key} — ${fix}`, SPEC_FILE);
  }
}

// PZ026 — a NOTICE, never a gate. Scenario tests select by data-testid; an app
// without them forces text/CSS selectors that break on the next redesign.
const INTERACTIVE_TAG = /<(button|input|select|a)(?=[\s/>])/g;

// jsxTagText returns an element's opening tag, tracking braces and quotes so a
// `>` inside {() => x} or a string does not end the tag early. Bounded, so an
// unbalanced brace cannot run the scan to the end of the file.
function jsxTagText(content, start) {
  const limit = Math.min(content.length, start + 800);
  let depth = 0;
  let quote = null;
  for (let i = start; i < limit; i += 1) {
    const char = content[i];
    if (quote) {
      if (char === quote && content[i - 1] !== '\\') quote = null;
      continue;
    }
    if (char === '"' || char === "'" || char === '`') quote = char;
    else if (char === '{') depth += 1;
    else if (char === '}') depth -= 1;
    else if (char === '>' && depth === 0) return content.slice(start, i + 1);
  }
  return content.slice(start, limit);
}

function scanTestIdCoverage(projectDir, files, findings) {
  let untagged = 0;
  const fileSet = new Set();
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    INTERACTIVE_TAG.lastIndex = 0;
    let match = INTERACTIVE_TAG.exec(content);
    while (match) {
      if (!jsxTagText(content, match.index).includes('data-testid')) {
        untagged += 1;
        fileSet.add(rel);
      }
      match = INTERACTIVE_TAG.exec(content);
    }
  }
  if (untagged === 0) return;
  addFinding(
    findings,
    'notice',
    'PZ026',
    `${untagged} interactive element(s) across ${fileSet.size} file(s) have no data-testid, so scenario tests must `
      + 'select them by text or CSS and will break on the next redesign. Add data-testid to the elements your '
      + 'S-nnn scenarios drive (tests/scenarios/README.md has the convention).',
  );
}

// isNewerContract: contract versions are hand-bumped revisions ("1", "2", ...),
// so a numeric comparison is the honest one. When either side is not a number
// (a future scheme), "different from what the service serves" is the most we
// can claim — and it is still worth saying.
function isNewerContract(live, local) {
  const liveNumber = Number(live);
  const localNumber = Number(local);
  if (Number.isFinite(liveNumber) && Number.isFinite(localNumber)) {
    return liveNumber > localNumber;
  }
  return live !== local;
}

// scanContractFreshness (PZ012): the contract is SERVED, so the copy sitting in
// this project is a cache — and a cache of RULES that silently goes stale is
// exactly what this check exists to prevent. It asks the cheap
// /contract/version probe (no 40KB transfer) and says nothing at all when that
// probe fails: a doctor that fails offline is noise, not a finding.
async function scanContractFreshness(manifest, findings, options) {
  const local = typeof manifest.contractVersion === 'string' && manifest.contractVersion
    ? manifest.contractVersion
    : null;
  if (!local) {
    // 'notice', not 'warn': every project created before contract fetching
    // existed has no recorded version, and turning `doctor --strict` red for
    // all of them on upgrade would break CI for a state the user has not done
    // anything wrong to reach. It is reported, it just does not fail the gate.
    // Being BEHIND a served version (below) is a real warn — that one is
    // actionable and self-inflicted-by-time.
    addFinding(
      findings,
      'notice',
      'PZ012',
      'This project has no recorded contract version, so its Piezas instructions came from a CLI bundle instead of the served contract. Run `npx piezas init` to adopt the contract the platform serves today.',
      'piezas.manifest.json',
    );
    return;
  }

  const env = options.env ?? process.env;
  const contractUrl = resolveContractUrl(options, env);
  let probe;
  try {
    probe = await fetchJson(options.fetchFn ?? fetch, `${contractUrl}/version`, {
      timeoutMs: CONTRACT_TIMEOUT_MS,
    });
  } catch {
    return; // offline / timeout — stay silent
  }
  if (!probe || probe.status !== 200) return;
  const live = probe.data?.version === undefined || probe.data?.version === null
    ? ''
    : String(probe.data.version).trim();
  if (!live || !isNewerContract(live, local)) return;

  addFinding(
    findings,
    'warn',
    'PZ012',
    `This project is on contract v${local}; ${contractUrl} now serves v${live}. Run \`npx piezas init\` to refresh the agent instruction files.`,
    'piezas.manifest.json',
  );
}

export async function runDoctor(projectDir, options = {}) {
  const resolvedDir = resolve(projectDir);
  const findings = [];
  const manifestInfo = loadManifest(resolvedDir, findings);
  const files = existsSync(resolvedDir) ? listFiles(resolvedDir) : [];

  scanSecretExposure(resolvedDir, files, findings);
  scanDeploymentMode(resolvedDir, files, manifestInfo.manifest, findings);
  scanLocalDatabase(resolvedDir, files, findings);
  scanOAuthTokenStorage(resolvedDir, files, findings);
  scanAdminTokenInUrl(resolvedDir, files, findings);
  scanHiddenTimeTrust(resolvedDir, files, findings);
  scanUnusedDynamicRoutes(resolvedDir, files, findings);
  scanIntegrationActions(resolvedDir, files, findings);
  scanAuthEmailReturnUrl(resolvedDir, files, findings);
  scanCoverageConfig(resolvedDir, files, findings);
  scanPackageScripts(resolvedDir, findings);
  scanNextStandaloneOutput(resolvedDir, manifestInfo.manifest, findings);
  // The delivery-protocol rules. PZ023 judges the manifest's declarations, so
  // it only speaks where there IS a manifest — a missing one already got PZ000
  // ("run init"), and listing every env var of an un-init'd folder is noise.
  scanLocalDatabaseUsage(resolvedDir, files, findings);
  scanPublicSecretNames(resolvedDir, files, findings);
  scanStandaloneOutputRequired(resolvedDir, files, findings);
  if (manifestInfo.exists) {
    scanRequiredEnvAccuracy(resolvedDir, files, manifestInfo.manifest, findings);
  }
  scanEnvIgnored(resolvedDir, findings);
  scanScenarioCoverage(resolvedDir, findings);
  scanTestIdCoverage(resolvedDir, files, findings);
  // Only for a real project: a missing manifest already got PZ000 ("run init"),
  // which is the same advice PZ012 would repeat.
  if (manifestInfo.exists) {
    await scanContractFreshness(manifestInfo.manifest, findings, options);
  }

  const errors = findings.filter((finding) => finding.severity === 'error').length;
  const warnings = findings.filter((finding) => finding.severity === 'warn').length;
  // 'notice' findings are informational: printed, never gating. --strict
  // promotes warnings to failures; it must not promote notices, or upgrading
  // the CLI would fail every pre-existing project's CI.
  const notices = findings.filter((finding) => finding.severity === 'notice').length;

  return {
    projectDir: resolvedDir,
    manifest: manifestInfo.manifest,
    manifestFound: manifestInfo.exists,
    findings,
    errors,
    warnings,
    notices,
    passed: errors === 0 && (!options.strict || warnings === 0),
  };
}

export function formatDoctorResult(result) {
  const lines = [
    '',
    '  🧱 Piezas Doctor',
    '',
    `  Project: ${result.projectDir}`,
    `  Manifest: ${result.manifestFound ? 'found' : 'missing'}`,
    `  Deployment mode: ${result.manifest.deploymentMode || 'unknown'}`,
    '',
  ];

  if (result.findings.length === 0) {
    lines.push('  No issues found.');
  } else {
    for (const finding of result.findings) {
      const marker =
        finding.severity === 'error' ? 'ERROR' : finding.severity === 'notice' ? 'NOTE ' : 'WARN ';
      const location = finding.file
        ? ` (${finding.file}${finding.line ? `:${finding.line}` : ''})`
        : '';
      lines.push(`  ${marker} ${finding.code}${location}`);
      lines.push(`        ${finding.message}`);
    }
  }

  lines.push('');
  lines.push(
    `  Summary: ${result.errors} error(s), ${result.warnings} warning(s)` +
      (result.notices ? `, ${result.notices} note(s)` : ''),
  );
  lines.push('');
  return lines.join('\n');
}

// ===========================================================================
// The delivery protocol: state, spec verdicts, phase gates, hook guard.
//
// Everything below is AGENT-FIRST: terse deterministic lines, stable rule IDs,
// exit codes that carry the verdict. It is the engine the Claude Code plugin
// drives — the plugin is choreography, this is judgment.
// ===========================================================================

export const PHASES = ['discover', 'mock', 'build', 'ship'];
const NEXT_PHASE = { discover: 'mock', mock: 'build', build: 'ship' };
const STATE_VERSION = 1;
const STATE_DIR = '.piezas';
const STATE_FILE = 'state.json';
const STATE_REL = `${STATE_DIR}/${STATE_FILE}`;
const SPEC_FILE = 'SPEC.md';
const SCENARIO_TEST_DIR = 'tests/scenarios';
const SCENARIO_TEST_EXTENSIONS = ['.spec.ts', '.spec.js'];
// The only gate a human signs today: the customer approving INTENT on the mock.
const APPROVAL_GATES = new Set(['mock']);
const GATE_BY_PHASE = {
  discover: 'spec-check',
  mock: 'user-approval',
  build: 'scenario-coverage',
  ship: 'deploy-attestation',
};

const RUN_INIT_HINT = 'run `npx piezas phase init`';

function toPosix(value) {
  return value.split('\\').join('/');
}

// findProjectRoot walks up from startDir for the directory holding
// .piezas/state.json. The STATE FILE (not the .piezas dir) is the anchor:
// `piezas init` creates .piezas/ for the spec-builder doc alone, and a project
// without state is not a protocol project — the guard must stay silent there.
export function findProjectRoot(startDir = process.cwd()) {
  let dir = resolve(startDir);
  for (;;) {
    if (existsSync(join(dir, STATE_DIR, STATE_FILE))) return dir;
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

function stateError(message) {
  const error = new Error(message);
  error.protocol = true;
  return error;
}

function requireProjectRoot(startDir) {
  const root = findProjectRoot(startDir);
  if (!root) {
    throw stateError(`no Piezas project state (${STATE_REL}) at or above ${resolve(startDir)} — ${RUN_INIT_HINT}`);
  }
  return root;
}

function validateState(parsed) {
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return 'not an object';
  if (parsed.version !== STATE_VERSION) return `unsupported version ${JSON.stringify(parsed.version)} (expected ${STATE_VERSION})`;
  if (!PHASES.includes(parsed.phase)) return `unknown phase ${JSON.stringify(parsed.phase)}`;
  if (!Array.isArray(parsed.approvals)) return 'approvals is not an array';
  for (const approval of parsed.approvals) {
    if (!approval || typeof approval.gate !== 'string' || typeof approval.by !== 'string' || typeof approval.at !== 'string') {
      return 'an approval entry is missing gate/by/at';
    }
  }
  return null;
}

// loadState reads the state for the project containing startDir. Missing or
// corrupt state is a HARD error with a repair instruction — never a silent
// default, because a defaulted phase is an unlocked phase.
export function loadState(startDir = process.cwd()) {
  const root = requireProjectRoot(startDir);
  const filePath = join(root, STATE_DIR, STATE_FILE);
  let parsed;
  try {
    parsed = JSON.parse(readFileSync(filePath, 'utf-8'));
  } catch (error) {
    throw stateError(`${STATE_REL} is not readable JSON (${error?.message || error}) — delete it and ${RUN_INIT_HINT}`);
  }
  const problem = validateState(parsed);
  if (problem) {
    throw stateError(`${STATE_REL} is invalid: ${problem} — delete it and ${RUN_INIT_HINT}`);
  }
  return {
    version: STATE_VERSION,
    phase: parsed.phase,
    approvals: parsed.approvals,
    createdAt: typeof parsed.createdAt === 'string' ? parsed.createdAt : null,
    updatedAt: typeof parsed.updatedAt === 'string' ? parsed.updatedAt : null,
  };
}

// saveState writes the v1 schema and nothing else: extra keys on the passed
// object are dropped, so callers can spread a loaded state freely. updatedAt is
// always stamped here — no caller sets it.
export function saveState(startDir, state) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const now = new Date().toISOString();
  const next = {
    version: STATE_VERSION,
    phase: state.phase,
    approvals: Array.isArray(state.approvals) ? state.approvals : [],
    createdAt: typeof state.createdAt === 'string' ? state.createdAt : now,
    updatedAt: now,
  };
  const problem = validateState(next);
  if (problem) throw stateError(`refusing to write invalid state: ${problem}`);
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(join(root, STATE_DIR, STATE_FILE), `${JSON.stringify(next, null, 2)}\n`);
  return next;
}

// --- SPEC.md: the parser and the six rules -------------------------------

// Unresolved markers are matched CASE-SENSITIVELY: a to-do app's spec says
// "todo item" all over, and only the shouting form is a placeholder.
const UNRESOLVED_MARKER = /\bTBD\b|\bTODO\b|\bUNRESOLVED\b|\[\?\]/g;
const REQUIREMENT_LINE = /^\s*[-*]\s*\**\s*(R-\d+)\s*\**\s*:/;
const SCENARIO_HEADING = /^###\s*\**\s*(S-\d+)\s*\**\s*:\s*(.*)$/;
const COVERS_LINE = /^\s*(?:[-*]\s*)?\**\s*covers\s*\**\s*:\s*(.+)$/i;
const GWT_LINE = /^\s*(?:[-*]\s*)?\**\s*(Given|When|Then)\b/;

// blankComments removes HTML comments while PRESERVING line numbers, so the
// template's format guidance can name the banned markers without tripping
// SPEC05 and every reported line number still matches the file.
function blankComments(text) {
  return text.replace(/<!--[\s\S]*?-->/g, (match) => match.replace(/[^\n]/g, ''));
}

// splitSections maps "## Heading" -> the lines beneath it (with 1-based line
// numbers). "###" scenario headings stay inside their parent section.
function splitSections(lines) {
  const sections = new Map();
  let current = null;
  lines.forEach((text, index) => {
    const heading = /^##\s+(.+?)\s*$/.exec(text);
    if (heading) {
      current = { title: heading[1].trim(), line: index + 1, lines: [] };
      sections.set(current.title.toLowerCase(), current);
      return;
    }
    if (current) current.lines.push({ text, number: index + 1 });
  });
  return sections;
}

function parseSpec(text) {
  const lines = blankComments(text).split(/\r?\n/);
  const sections = splitSections(lines);

  const requirementsSection = sections.get('requirements');
  const requirements = (requirementsSection?.lines ?? [])
    .map((line) => {
      const match = REQUIREMENT_LINE.exec(line.text);
      return match ? { id: match[1], line: line.number } : null;
    })
    .filter(Boolean);

  const scenariosSection = sections.get('acceptance scenarios');
  const scenarios = [];
  for (const line of scenariosSection?.lines ?? []) {
    const heading = SCENARIO_HEADING.exec(line.text);
    if (heading) {
      scenarios.push({
        id: heading[1],
        title: heading[2].trim(),
        line: line.number,
        covers: [],
        given: false,
        when: false,
        then: false,
      });
      continue;
    }
    const current = scenarios[scenarios.length - 1];
    if (!current) continue;
    const covers = COVERS_LINE.exec(line.text);
    if (covers) {
      for (const token of covers[1].split(',')) {
        const id = /R-\d+/.exec(token);
        if (id) current.covers.push(id[0]);
      }
      continue;
    }
    const gwt = GWT_LINE.exec(line.text);
    if (gwt) current[gwt[1].toLowerCase()] = true;
  }

  const markers = [];
  lines.forEach((text, index) => {
    UNRESOLVED_MARKER.lastIndex = 0;
    let match;
    while ((match = UNRESOLVED_MARKER.exec(text)) !== null) {
      markers.push({ marker: match[0], line: index + 1 });
    }
  });

  return { lines, sections, requirements, scenarios, markers };
}

function openConflictsLeft(sections) {
  const section = sections.get('open conflicts');
  if (!section) return [];
  return section.lines
    .map((line) => line.text.trim())
    .filter((text) => text.length > 0)
    .filter((text) => text.replace(/^[-*]\s*/, '').replace(/[.\s]/g, '').toLowerCase() !== 'none');
}

function gap(rule, message) {
  return { rule, message };
}

// checkSpec is the DISCOVER gate. Every failure is a named gap — a
// machine-generated work order the agent can close, one at a time.
export function checkSpec(projectDir) {
  const specPath = join(resolve(projectDir), SPEC_FILE);
  const empty = { command: 'spec check', specPath, requirements: [], scenarios: [] };

  if (!existsSync(specPath)) {
    return { ...empty, ok: false, gaps: [gap('SPEC01', `${SPEC_FILE} is missing — ${RUN_INIT_HINT} to create it from the template`)] };
  }
  const raw = readFileSync(specPath, 'utf-8');
  if (!raw.trim()) {
    return { ...empty, ok: false, gaps: [gap('SPEC01', `${SPEC_FILE} is empty`)] };
  }

  const parsed = parseSpec(raw);
  const gaps = [];

  // SPEC02 — requirements exist, in the checkable "- R-001: ..." form.
  if (!parsed.sections.has('requirements')) {
    gaps.push(gap('SPEC02', 'no "## Requirements" section'));
  } else if (parsed.requirements.length === 0) {
    gaps.push(gap('SPEC02', 'no requirements under "## Requirements" (expected lines like "- R-001: <claim>")'));
  }

  // SPEC03 — scenarios exist and each is a complete Given/When/Then.
  if (!parsed.sections.has('acceptance scenarios')) {
    gaps.push(gap('SPEC03', 'no "## Acceptance Scenarios" section'));
  } else if (parsed.scenarios.length === 0) {
    gaps.push(gap('SPEC03', 'no scenarios under "## Acceptance Scenarios" (expected blocks like "### S-001: <title>")'));
  } else {
    for (const scenario of parsed.scenarios) {
      const missing = ['Given', 'When', 'Then'].filter((step) => !scenario[step.toLowerCase()]);
      if (missing.length > 0) {
        gaps.push(gap('SPEC03', `${scenario.id} is missing ${missing.join('/')} line${missing.length > 1 ? 's' : ''}`));
      }
    }
  }

  // SPEC04 — the coverage claim: every requirement is exercised by a scenario.
  const covered = new Set(parsed.scenarios.flatMap((scenario) => scenario.covers));
  for (const requirement of parsed.requirements) {
    if (!covered.has(requirement.id)) {
      gaps.push(gap('SPEC04', `${requirement.id} has no covering scenario`));
    }
  }

  // SPEC05 — no placeholders. An unresolved marker is an unasked question.
  for (const marker of parsed.markers) {
    gaps.push(gap('SPEC05', `unresolved marker "${marker.marker}" at line ${marker.line}`));
  }

  // SPEC06 — conflicts are decisions the customer still owes us.
  const conflicts = openConflictsLeft(parsed.sections);
  for (const conflict of conflicts) {
    gaps.push(gap('SPEC06', `"## Open Conflicts" still lists: ${conflict}`));
  }

  return {
    command: 'spec check',
    specPath,
    ok: gaps.length === 0,
    requirements: parsed.requirements.map((entry) => entry.id),
    scenarios: parsed.scenarios.map((entry) => entry.id),
    gaps,
  };
}

// checkCoverage is the BUILD gate's mechanical half: one test file per
// scenario. It deliberately does NOT read the spec's other rules — a project
// mid-build should not be told about spec style while it is closing coverage.
export function checkCoverage(projectDir) {
  const root = resolve(projectDir);
  const specPath = join(root, SPEC_FILE);
  if (!existsSync(specPath) || !readFileSync(specPath, 'utf-8').trim()) {
    const spec = checkSpec(root);
    return { command: 'spec coverage', ok: false, scenarios: [], missing: [], gaps: spec.gaps };
  }
  const parsed = parseSpec(readFileSync(specPath, 'utf-8'));
  const scenarios = parsed.scenarios.map((entry) => entry.id);
  const missing = scenarios.filter(
    (id) => !SCENARIO_TEST_EXTENSIONS.some((ext) => existsSync(join(root, 'tests', 'scenarios', `${id}${ext}`))),
  );
  const gaps = missing.map((id) =>
    gap('COVERAGE', `${id} has no scenario test (expected ${SCENARIO_TEST_DIR}/${id}.spec.ts or ${SCENARIO_TEST_DIR}/${id}.spec.js)`),
  );
  if (scenarios.length === 0) {
    gaps.push(gap('COVERAGE', `${SPEC_FILE} declares no scenarios — nothing to prove`));
  }
  return { command: 'spec coverage', ok: gaps.length === 0, scenarios, missing, gaps };
}

function gapLines(gaps) {
  return gaps.map((entry) => `${entry.rule}: ${entry.message}`);
}

export function formatSpecCheck(result) {
  if (!result.ok) return gapLines(result.gaps);
  return [`spec check: ok (${result.requirements.length} requirements, ${result.scenarios.length} scenarios)`];
}

export function formatSpecCoverage(result) {
  if (!result.ok) return gapLines(result.gaps);
  return [`spec coverage: ok (${result.scenarios.length} scenarios, ${result.scenarios.length} tests)`];
}

// --- piezas test: run the suite, attest the result -------------------------
//
// The BUILD gate proves a test FILE exists per scenario; only a RUN proves the
// app works. `piezas test` is that run, and its output is evidence rather than
// a claim: .piezas/test-attestation.json travels with the next deploy, so the
// platform can judge what was actually proven (total local defection ends in
// a blocked project, never a shipped lie).

const ATTESTATION_FILE = 'test-attestation.json';
const ATTESTATION_REL = `${STATE_DIR}/${ATTESTATION_FILE}`;
const ATTESTATION_VERSION = 1;
// A day: long enough that a normal build/deploy loop never trips it, short
// enough that "I tested it last week" is called what it is.
const ATTESTATION_MAX_AGE_MS = 24 * 60 * 60 * 1000;
const DEFAULT_TEST_COMMAND = 'npx playwright test --reporter=json';

// parseTestReport reads Playwright's JSON reporter. The stats block is the
// cheap path; walking the suites is the fallback for reporters (and versions)
// that omit it. Anything we cannot count returns null — an uncounted run must
// never become a green attestation.
function parseTestReport(text) {
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    return null;
  }
  if (!data || typeof data !== 'object') return null;

  const stats = data.stats;
  if (stats && (Number.isFinite(stats.expected) || Number.isFinite(stats.unexpected))) {
    return {
      passed: (Number(stats.expected) || 0) + (Number(stats.flaky) || 0),
      failed: Number(stats.unexpected) || 0,
    };
  }

  let passed = 0;
  let failed = 0;
  const walk = (suite) => {
    for (const spec of suite?.specs ?? []) {
      if (spec.ok) passed += 1;
      else failed += 1;
    }
    for (const child of suite?.suites ?? []) walk(child);
  };
  for (const suite of data.suites ?? []) walk(suite);
  if (passed + failed === 0) return null;
  return { passed, failed };
}

export async function runTests(startDir = process.cwd(), options = {}) {
  const env = options.env ?? process.env;
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const override = typeof env.PIEZAS_TEST_CMD === 'string' ? env.PIEZAS_TEST_CMD.trim() : '';
  const command = override || DEFAULT_TEST_COMMAND;

  // The JSON reporter prints to stdout unless told otherwise; a temp file keeps
  // the report clean of whatever else the runner writes.
  const reportDir = mkdtempSync(join(tmpdir(), 'piezas-test-'));
  const reportPath = join(reportDir, 'report.json');
  let stdout = '';
  let stderr = '';
  try {
    stdout = execSync(command, {
      cwd: root,
      env: { ...env, PLAYWRIGHT_JSON_OUTPUT_NAME: reportPath },
      encoding: 'utf-8',
      stdio: ['ignore', 'pipe', 'pipe'],
      maxBuffer: 64 * 1024 * 1024,
    }) ?? '';
  } catch (error) {
    // A red suite exits non-zero — that is a RESULT, not an error. Keep the
    // output and let the report decide which of the two happened.
    stdout = typeof error?.stdout === 'string' ? error.stdout : error?.stdout?.toString?.() ?? '';
    stderr = typeof error?.stderr === 'string' ? error.stderr : error?.stderr?.toString?.() ?? '';
  }

  let report = null;
  try {
    if (existsSync(reportPath)) report = parseTestReport(readFileSync(reportPath, 'utf-8'));
  } catch { /* unreadable -> fall through to stdout */ }
  if (!report) report = parseTestReport(stdout);
  try { rmSync(reportDir, { recursive: true, force: true }); } catch { /* best-effort */ }

  const coverage = checkCoverage(root);
  const scenarios = coverage.scenarios.length;
  const covered = scenarios - coverage.missing.length;

  if (!report) {
    // No countable result: say so and attest NOTHING. A run nobody can read is
    // not a green run, and writing an attestation here would launder it.
    const detail = (stderr || stdout).split('\n').map((line) => line.trim()).filter(Boolean)[0];
    const json = { command: 'test', ok: false, ran: command, attestation: null };
    return {
      exitCode: 1,
      command: 'test',
      attestation: null,
      json,
      output: [
        `test: no results — \`${command}\` produced no JSON report`,
        ...(detail ? [`runner: ${detail.slice(0, 200)}`] : []),
        'fix: install the harness (npm install && npx playwright install), then re-run `npx piezas test`',
      ],
    };
  }

  const attestation = {
    version: ATTESTATION_VERSION,
    scenarios,
    covered,
    passed: report.passed,
    failed: report.failed,
    ranAt: new Date().toISOString(),
  };
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(join(root, STATE_DIR, ATTESTATION_FILE), `${JSON.stringify(attestation, null, 2)}\n`);

  const output = [
    `test: ${attestation.passed} passed, ${attestation.failed} failed`,
    `scenarios: ${scenarios} in ${SPEC_FILE}, ${covered} with tests`,
    `attested: ${ATTESTATION_REL} (${attestation.ranAt})`,
  ];
  if (covered < scenarios) {
    output.push(...gapLines(coverage.gaps));
  }
  return {
    exitCode: attestation.failed > 0 ? 1 : 0,
    command: 'test',
    attestation,
    json: { command: 'test', ok: attestation.failed === 0, ran: command, attestation },
    output,
  };
}

// readTestAttestation returns the attestation for a project, or null when it is
// absent OR unreadable — an unparseable file attests nothing, and saying so is
// the honest reading.
export function readTestAttestation(projectDir) {
  try {
    const parsed = readJsonFile(join(resolve(projectDir), STATE_DIR, ATTESTATION_FILE));
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
    return parsed;
  } catch {
    return null;
  }
}

// attestationWarning is v1's whole enforcement at the client: ONE line, never a
// block. Blocking here would only teach people to deploy around the CLI; the
// platform is where "untested cannot ship" gets teeth.
export function attestationWarning(attestation, now = Date.now()) {
  if (!attestation) {
    return 'deploy is untested: run `npx piezas test` first — this build ships with nothing attesting it.';
  }
  const failed = Number(attestation.failed) || 0;
  if (failed > 0) {
    return `deploy is RED: ${failed} test(s) failed in the last \`npx piezas test\` run (${attestation.ranAt}) — `
      + 'fix them and re-run before shipping.';
  }
  const ranAt = Date.parse(attestation.ranAt);
  if (!Number.isFinite(ranAt) || now - ranAt > ATTESTATION_MAX_AGE_MS) {
    return `deploy attestation is stale: the last \`npx piezas test\` run was ${attestation.ranAt} (over 24h ago) — `
      + 're-run `npx piezas test` so this deploy carries current evidence.';
  }
  return null;
}

// --- SPEC.md template ------------------------------------------------------

// The template is read by AGENTS as much as by humans: the comments carry the
// exact formats `spec check` enforces, so a fresh session can fill it without
// guessing. Comments are stripped before checking, which is why the banned
// markers can be named literally here.
export function specTemplate() {
  return `# Product Spec

<!--
Piezas SPEC.md — the contract this app is built, tested and shipped against.
\`npx piezas spec check\` enforces these formats:

  Requirement   - R-001: <one testable claim, in the customer's words>
  Scenario      ### S-002: <short title>
                covers: R-001, R-003
                Given <starting state>
                When <the action>
                Then <the observable result>

Rules the checker applies:
  SPEC02  at least one "- R-nnn:" line under "## Requirements"
  SPEC03  every "### S-nnn:" block has Given, When and Then lines
  SPEC04  every R-nnn is named by the "covers:" line of some scenario
  SPEC05  no unresolved markers anywhere: TBD, TODO, UNRESOLVED, [?]
  SPEC06  "## Open Conflicts" reads "none"

Write provenance next to each claim (which artifact or which person it came
from). Later, each S-nnn needs a test at tests/scenarios/S-nnn.spec.ts|js
before the project may advance to ship.
-->

## Overview

<!-- Two or three sentences: who uses this, and what job it does for them. -->

## Requirements

<!-- One line per claim, in business language, each independently testable:
     - R-001: A guest can reserve a table for a given date and time.
     - R-002: Staff can cancel a reservation and free the slot. -->

## Acceptance Scenarios

### S-001: Example — replace this with a real scenario

covers: R-001
Given a staff member signed in to the dashboard
When they open today's reservations
Then the reservations appear in time order

## Open Conflicts

none
`;
}

// --- spec-builder: the interview guide the agent reads --------------------

// specBuilderTemplate is the DISCOVER-phase prompt, written to
// .piezas/spec-builder.md. It ships with the binary that enforces the formats
// it teaches, so the guide and `spec check` can never drift apart. Two
// mechanisms carry it: mine artifacts and
// PROPOSE a draft (LLMs are excellent at "correct this", poor at "interview
// until done"), then let the checker's named gaps drive the remaining work.
export function specBuilderTemplate() {
  return `${PIEZAS_SPEC_START}
# Piezas spec mode

Your job in this mode is one file: \`SPEC.md\` — the requirements this app is
built, tested and shipped against. You are the product manager for a
non-technical customer. Only they know their business; you own getting it
written down in a form a machine can check.

Write no application code in this mode. Stop when the spec is complete.

Start by running \`npx piezas phase init\` (creates \`SPEC.md\` and the project
state), then \`npx piezas phase status --context\` to see where the project is.

## 1. Mine their artifacts before you ask anything

Their business is already written down somewhere. Reading beats interviewing.

- Ask once, up front: "What do you already have? Spreadsheets, a current site or
  app, forms, exports, screenshots, sketches, an SOP doc, past invoices, an
  email thread — anything. Point me at the folder or paste the paths."
- Read what they give you and mine it into claims. Column headers are entities
  and fields. Status values are workflow states. Form fields are required
  inputs. Repeated manual steps are automations. Notes in the margins are the
  edge cases that matter most.
- Record where every claim came from, inline:
  \`- R-004: An invoice may be split across two projects. (from billing-2025.xlsx, "Split %" column)\`
- Provenance is not decoration: it is what lets a reviewer — or an engineer
  picking this up cold — trust a claim without re-interviewing the customer.

Never ask for something you can read. Never guess at a file you cannot open —
ask them to paste it.

## 2. Propose a complete draft, then interview by delta

An open-ended interview is the failure mode: it exhausts the customer and still
misses things.

- Pick the closest recipe (booking site, CRM/projects/finance, client-services
  portal) and write a complete first-pass understanding from their artifacts:
  entities, roles, the main flows, the obvious edge cases.
- Present it as a draft to correct, not a questionnaire to fill: "Here's what I
  think you need — tell me where I'm wrong."
- Then ask only about the DELTAS: what the recipe assumes that they contradict,
  and what their artifacts show that the recipe has no place for.

**One question at a time.** Never a numbered list. Ask, listen, write it into
\`SPEC.md\`, then ask the next one. Ask about consequences in their language —
"When two people book the same slot, who wins?", not "What is your concurrency
strategy?" Prioritise what changes the build: money, permissions, who sees
what, what happens when something fails, and what they do today when the happy
path breaks.

## 3. Write every agreed answer down immediately, as a pair

The moment the customer confirms something, write both halves. Never batch it.

\`\`\`markdown
## Requirements

- R-007: Staff can cancel a booking up to 24h before it starts. (from the intake call)

## Acceptance Scenarios

### S-011: Staff cancels inside the cancellation window

covers: R-007
Given a booking that starts in 48 hours
When a staff member cancels it
Then the slot returns to availability and the guest is notified
\`\`\`

The formats are exact — \`npx piezas spec check\` parses them:

- \`- R-nnn: <claim>\` lines under \`## Requirements\`.
- \`### S-nnn: <title>\` blocks under \`## Acceptance Scenarios\`, each with a
  \`covers:\` line naming the requirements it proves and its own Given, When and
  Then lines.
- Every R-nnn must be named by some scenario's \`covers:\`.
- No unresolved markers anywhere in the file (the checker rejects TBD, TODO,
  UNRESOLVED and bracketed question marks). A placeholder is an unasked
  question — ask it now instead of parking it.
- \`## Open Conflicts\` must read \`none\`. When the customer says two things that
  cannot both be true, list the conflict there, resolve it with them
  explicitly, then delete it. Never silently pick a side.

Write scenarios about observable behaviour — what the customer would see
happen — never about implementation.

## 4. Let the verdict drive the work

After every meaningful edit, run \`npx piezas spec check\` and work the gaps it
names, one at a time:

- \`SPEC02\` — no requirements yet. Keep interviewing.
- \`SPEC03\` — a scenario is missing a Given/When/Then line. Finish it.
- \`SPEC04: R-007 has no covering scenario\` — ask the customer how they would
  know R-007 works, and write their answer as a scenario.
- \`SPEC05\` — a placeholder is still in the file. Ask the question it stands for.
- \`SPEC06\` — an open conflict. Get the decision.

## 5. Stop at spec completion

When it prints \`spec check: ok\`, summarise the spec back to the customer in
their own words, ask what is obviously missing, and stop. Later each S-nnn gets
a test at \`tests/scenarios/S-nnn.spec.ts\` and the build begins; neither belongs
in this mode. Post-launch changes re-enter this same loop as a small delta:
mine what changed, propose, interview the delta, add R-/S- pairs, re-check.
`;
}

// --- phase: the only state mutators ---------------------------------------

function approvalFor(state, gate) {
  return state.approvals.find((entry) => entry.gate === gate);
}

// gateGaps answers "what is between this project and the next phase?" — the
// same list drives status, --context, advance and the discover block message.
function gateGaps(root, state) {
  if (state.phase === 'discover') return checkSpec(root).gaps;
  if (state.phase === 'mock') {
    const approval = approvalFor(state, 'mock')
      ? []
      : [gap('GATE', 'the user has not approved the mock — show it to them, then run `npx piezas phase approve --gate mock`')];
    return [...approval, ...importGaps(root, 'mock')];
  }
  if (state.phase === 'build') return [...checkCoverage(root).gaps, ...importGaps(root, 'build')];
  return [];
}

const PHASE_ALLOWED = {
  discover: `${SPEC_FILE}, ${STATE_DIR}/**, docs/** — interview and spec work only`,
  mock: 'UI files and fake/seed data — the customer must be able to react to it',
  build: 'everything: real SDK calls, API routes, and one test per scenario',
  ship: 'deploy — the platform accepts the attested test run',
};
const PHASE_BLOCKED = {
  discover: 'all application code (the PreToolUse hook rejects the write)',
  mock: `${STATE_DIR}/${STATE_FILE} writes, app/api/**, and any file importing @piezas/sdk`,
  build: `${STATE_DIR}/${STATE_FILE} writes`,
  ship: `${STATE_DIR}/${STATE_FILE} writes`,
};
const PHASE_GATE_TEXT = {
  discover: '`npx piezas spec check` passes, then `npx piezas phase advance`',
  mock: 'the USER approves the mock (`/piezas:approve` -> `npx piezas phase approve --gate mock`), then `npx piezas phase advance`',
  build: 'scenario coverage: every S-nnn in SPEC.md has tests/scenarios/S-nnn.spec.ts|js, then `npx piezas phase advance`',
  ship: 'server-side deploy attestation — the platform is the last gate',
};

function approvalsLine(state) {
  if (state.approvals.length === 0) return 'approvals: none';
  return `approvals: ${state.approvals.map((entry) => `${entry.gate}@${entry.at}`).join(', ')}`;
}

function statusLines(state, gaps) {
  const lines = [
    `phase: ${state.phase}`,
    approvalsLine(state),
    `gate: ${GATE_BY_PHASE[state.phase]}`,
    `gaps: ${gaps.length}`,
    ...gapLines(gaps),
  ];
  return lines;
}

// contextLines is what SessionStart injects: everything a fresh session needs
// to resume mid-project — the phase, its rules, and the named gaps. State makes
// sessions disposable; this block is how the state reaches the model.
function contextLines(state, gaps) {
  return [
    '<piezas-protocol>',
    `phase: ${state.phase}`,
    `allowed: ${PHASE_ALLOWED[state.phase]}`,
    `blocked: ${PHASE_BLOCKED[state.phase]}`,
    `gate: ${PHASE_GATE_TEXT[state.phase]}`,
    approvalsLine(state),
    `gaps: ${gaps.length}`,
    ...gapLines(gaps),
    'rules: phase changes ONLY through `npx piezas phase ...`; never edit .piezas/state.json.',
    '</piezas-protocol>',
  ];
}

export function phaseStatus(startDir = process.cwd(), options = {}) {
  // No project yet is a normal answer (an agent asks before starting one),
  // not an error: exit 0 and say how to begin.
  if (!findProjectRoot(startDir)) {
    const json = { command: 'phase status', projectRoot: null, phase: null, gaps: [] };
    return {
      exitCode: 0,
      ...json,
      json,
      output: ['phase: none — there is no Piezas project in this folder yet', 'start: piezas init --sandbox --app "<App name>" --yes (no account needed)'],
    };
  }
  const root = requireProjectRoot(startDir);
  const state = loadState(root);
  const gaps = gateGaps(root, state);
  const json = {
    command: 'phase status',
    projectRoot: root,
    version: state.version,
    phase: state.phase,
    approvals: state.approvals,
    gate: GATE_BY_PHASE[state.phase],
    gaps,
    createdAt: state.createdAt,
    updatedAt: state.updatedAt,
  };
  // status REPORTS; it never fails. The SessionStart hook depends on it, and
  // `advance` is the command whose exit code is a verdict.
  return {
    exitCode: 0,
    ...json,
    json,
    output: options.context ? contextLines(state, gaps) : statusLines(state, gaps),
  };
}

export function phaseInit(startDir = process.cwd()) {
  const existingRoot = findProjectRoot(startDir);
  const root = existingRoot ?? resolve(startDir);
  const created = [];

  if (!existingRoot) {
    saveState(root, { phase: 'discover', approvals: [], createdAt: new Date().toISOString() });
    created.push(STATE_REL);
  }
  const specPath = join(root, SPEC_FILE);
  if (!existsSync(specPath)) {
    writeFileSync(specPath, specTemplate());
    created.push(SPEC_FILE);
  }
  // The interview guide travels with the state: `phase init` is the protocol's
  // entry point for a project that never ran `piezas init` (or whose session is
  // fresh), and DISCOVER without the guide is a blank page.
  const builderPath = join(root, STATE_DIR, 'spec-builder.md');
  if (!existsSync(builderPath)) {
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    writeFileSync(builderPath, specBuilderTemplate());
    created.push(`${STATE_DIR}/spec-builder.md`);
  }

  const status = phaseStatus(root);
  return {
    exitCode: 0,
    command: 'phase init',
    projectRoot: root,
    phase: status.phase,
    created,
    json: { ...status.json, command: 'phase init', created },
    output: [...created.map((file) => `created: ${file}`), ...status.output],
  };
}

export function phaseApprove(startDir = process.cwd(), options = {}) {
  const root = requireProjectRoot(startDir);
  const state = loadState(root);
  const gate = typeof options.gate === 'string' ? options.gate.trim() : '';

  if (!APPROVAL_GATES.has(gate)) {
    return {
      exitCode: 1,
      command: 'phase approve',
      json: { command: 'phase approve', ok: false, gate: gate || null, phase: state.phase },
      output: [`refused: unknown gate ${JSON.stringify(gate)} — the only recorded approval is --gate mock`],
    };
  }
  if (state.phase !== gate) {
    return {
      exitCode: 1,
      command: 'phase approve',
      json: { command: 'phase approve', ok: false, gate, phase: state.phase },
      output: [
        `refused: approve --gate ${gate} requires phase=${gate} (current: ${state.phase})`,
        `gate: ${GATE_BY_PHASE[state.phase]}`,
      ],
    };
  }

  const existing = approvalFor(state, gate);
  if (existing) {
    return {
      exitCode: 0,
      command: 'phase approve',
      json: { command: 'phase approve', ok: true, gate, phase: state.phase, approval: existing, recorded: false },
      output: [`approved: ${gate} (already recorded at ${existing.at})`],
    };
  }

  const approval = { gate, by: 'user', at: new Date().toISOString() };
  const saved = saveState(root, { ...state, approvals: [...state.approvals, approval] });
  return {
    exitCode: 0,
    command: 'phase approve',
    json: { command: 'phase approve', ok: true, gate, phase: saved.phase, approval, recorded: true },
    output: [`approved: ${gate}`, `by: ${approval.by}`, `at: ${approval.at}`, 'next: npx piezas phase advance'],
  };
}

export function phaseAdvance(startDir = process.cwd()) {
  const root = requireProjectRoot(startDir);
  const state = loadState(root);
  const next = NEXT_PHASE[state.phase];

  if (!next) {
    return {
      exitCode: 1,
      command: 'phase advance',
      json: { command: 'phase advance', ok: false, phase: state.phase, gaps: [] },
      output: [
        'blocked: ship is the final local phase',
        `gate: ${PHASE_GATE_TEXT.ship}`,
      ],
    };
  }

  // BUILD -> SHIP checks that a test FILE exists per scenario; it does not run
  // the suite. Suite-green is enforced where it cannot be faked — the deploy
  // attestation the platform accepts server-side.
  // The never-rules hold at every step change, whether or not a hook ran. An
  // imported app may describe and preview what it already has (its inherited
  // findings are the build's work order), but leaving the build needs them all
  // fixed: the build-step hard stop has no exceptions.
  const found = next === 'ship' ? hardNoFindings(root) : newHardNoFindings(root);
  const hardNo = found.map((f) => gap(f.code, `${f.file ?? ''}: ${f.message}`));
  const gaps = [...hardNo, ...gateGaps(root, state)];
  if (gaps.length > 0) {
    return {
      exitCode: 1,
      command: 'phase advance',
      json: { command: 'phase advance', ok: false, phase: state.phase, to: next, gaps },
      output: [`blocked: ${state.phase} -> ${next}`, ...gapLines(gaps), `gate: ${GATE_BY_PHASE[state.phase]}`],
    };
  }

  const saved = saveState(root, { ...state, phase: next });
  return {
    exitCode: 0,
    command: 'phase advance',
    json: { command: 'phase advance', ok: true, phase: saved.phase, from: state.phase, to: next, gaps: [] },
    output: [
      `advanced: ${state.phase} -> ${next}`,
      `allowed: ${PHASE_ALLOWED[next]}`,
      `gate: ${PHASE_GATE_TEXT[next]}`,
    ],
  };
}

// --- phase guard: the PreToolUse verdict ----------------------------------

// Write-ish shell patterns. A command that merely READS state.json is fine;
// one that could rewrite it is not, whatever the phase.
const WRITEISH_SHELL = [
  />/,
  /(^|[\s;|&(])(mv|cp|rm|tee|truncate|install)(\s|$)/,
  /(^|[\s;|&(])sed\b[^\n]*\s-i\b/,
];
const MENTIONS_STATE_FILE = /(?:\.piezas[/\\]state\.json)|(?:(?:^|[\s'"(=])state\.json)/;
const STATE_WRITE_BLOCK =
  `Piezas: ${STATE_REL} is protocol state, not a file to edit. Phase and approvals change ONLY through ` +
  '`npx piezas phase init|approve|advance` — rewriting the file by hand (or through the shell) is the one ' +
  'thing that can never be allowed. Run `npx piezas phase status` to see where the project actually is.';

const MENTIONS_IMPORT_FILE = /(?:\.piezas[/\\]import\.json)|(?:(?:^|[\s'"(=])import\.json)/;
const IMPORT_WRITE_BLOCK =
  'Piezas: .piezas/import.json records what the imported app came with and what the owner chose. It changes only through ' +
  '`piezas import scan`, and the owner\'s own replies to `piezas import ask`. Do not edit it by hand.';

function guardAllow() {
  return { exitCode: 0, verdict: 'allow', reason: '' };
}

function guardBlock(reason) {
  return { exitCode: 2, verdict: 'block', reason };
}

// phaseGuard is called by the plugin's PreToolUse hook for every Write/Edit/Bash
// call. Exit 0 = allow (silent), exit 2 = block with the reason on stderr, which
// Claude Code feeds back to the model — a machine-generated prompt, not a wall.
export function phaseGuard(options = {}) {
  const cwd = resolve(options.cwd || process.cwd());
  // Locate the project from the file being written when there is one: the
  // session may have been opened in a parent folder of the app.
  const target = typeof options.file === 'string' && options.file ? resolve(cwd, options.file) : undefined;
  const root = (target && findProjectRoot(dirname(target))) || findProjectRoot(cwd);
  // Not a protocol project: the guard has no jurisdiction here.
  if (!root) return guardAllow();

  let state;
  try {
    state = loadState(root);
  } catch (error) {
    // Unreadable state is indistinguishable from tampered state. Blocked
    // project beats shipped lie.
    return guardBlock(`Piezas: ${error.message}`);
  }

  const tool = typeof options.tool === 'string' ? options.tool : '';
  const filePath = target;
  const command = typeof options.command === 'string' ? options.command : '';

  // 1. The state file is off-limits to every tool in every phase. So is the
  //    import record: it holds the owner's choices and what the app came with.
  if (filePath && filePath === join(root, STATE_DIR, STATE_FILE)) {
    return guardBlock(STATE_WRITE_BLOCK);
  }
  if (filePath && filePath === join(root, STATE_DIR, IMPORT_FILE)) {
    return guardBlock(IMPORT_WRITE_BLOCK);
  }
  if (tool === 'Bash' && command && MENTIONS_IMPORT_FILE.test(command)
    && (WRITEISH_SHELL.some((re) => re.test(command)) || SCRIPTED_WRITE.test(command))) {
    return guardBlock(IMPORT_WRITE_BLOCK);
  }
  if (tool === 'Bash' && command && MENTIONS_STATE_FILE.test(command)
    && (WRITEISH_SHELL.some((re) => re.test(command)) || SCRIPTED_WRITE.test(command))) {
    return guardBlock(STATE_WRITE_BLOCK);
  }

  // 2. Shell commands: the always-on Hard No rules (approval is the customer's
  //    alone; no local database). Anything else is allowed through — doctor and
  //    the server attestation cover what shell heuristics cannot.
  if (tool === 'Bash') {
    const hardNo = hardNoShellVerdict(command);
    if (hardNo) return hardNo;
    // A shell redirect or tee that writes a file gets the same file rules as a
    // Write — otherwise `cat > lib/db.ts <<EOF` walks around every write rule.
    for (const target of shellWriteTargets(command)) {
      const verdict = phaseGuard({ cwd, tool: 'Write', file: target, content: command });
      if (verdict.exitCode === 2) return verdict;
    }
    return guardAllow();
  }

  const isFileWrite = tool === 'Write' || tool === 'Edit' || tool === 'MultiEdit';
  if (!filePath || !isFileWrite) return guardAllow();

  const relPath = toPosix(relative(root, filePath));
  // Outside the project (temp files, other repos) — not ours to police.
  if (relPath.startsWith('../')) return guardAllow();

  // 3. The Hard No rules hold in EVERY phase. They are exact conditions on the
  //    text being written, so they are enforced here at write time instead of
  //    waiting for doctor (docs: CLAUDE.md instruction-file review, Rec 4).
  const hardNo = hardNoWriteVerdict(relPath, guardContent(options));
  if (hardNo) return hardNo;

  if (state.phase === 'discover') {
    const allowed =
      relPath === SPEC_FILE ||
      relPath.startsWith(`${STATE_DIR}/`) ||
      relPath.startsWith('docs/');
    if (allowed) return guardAllow();
    const gaps = checkSpec(root).gaps;
    const missing = gaps.length > 0 ? gapLines(gaps).join('; ') : 'none — run `npx piezas phase advance`';
    return guardBlock(
      `Piezas: you are in DISCOVER. App code is locked until the spec is complete — ${relPath} is not writable yet. ` +
        `Write only ${SPEC_FILE}, ${STATE_DIR}/**, docs/**. Missing: ${missing}. ` +
        'Go back to the interview, close those gaps in SPEC.md, then run `npx piezas spec check` and `npx piezas phase advance`.',
    );
  }

  if (state.phase === 'mock') {
    const content = guardContent(options);
    const isApiRoute = /(^|\/)app\/api\//.test(relPath);
    const usesSdk = typeof content === 'string' && content.includes('@piezas/sdk');
    if (isApiRoute || usesSdk) {
      const what = isApiRoute ? `${relPath} is an API route` : `${relPath} imports @piezas/sdk`;
      return guardBlock(
        `Piezas: MOCK phase is UI + fake data only — ${what}. Real endpoints and @piezas/sdk calls wait for BUILD, ` +
          'because the point of the mock is that the customer can react to it before anyone pays for wiring. ' +
          'Use local seed data now. When the user says the mock is right: `npx piezas phase approve --gate mock`, then `npx piezas phase advance`.',
      );
    }
    return guardAllow();
  }

  // build / ship: writes are open; doctor and the deploy attestation judge them.
  return guardAllow();
}

// ===========================================================================
// Hard No rules at write time (always on, every phase)
// ===========================================================================

// A script interpreter writing the state file (node -e, python -c, ...) is a
// rewrite even without a shell redirect.
const SCRIPTED_WRITE = /(^|[\s;|&(])(node|python3?|ruby|perl|deno|bun)\s+(-e|-c|--eval)\b/;

// Approval is the customer's decision. The agent may never record it; the
// UserPromptSubmit hook records it from the customer's own typed message.
const AGENT_APPROVE = /(?:\bpiezas(?:\.mjs)?|\bindex\.js)["']?\s+phase\s+approve\b/;
// Same for an imported app's choices: the owner's reply records them.
const AGENT_IMPORT_CHOOSE = /(?:\bpiezas(?:\.mjs)?|\bindex\.js)["']?\s+import\s+choose\b/;

const LOCAL_DB_INSTALL = new RegExp(
  `(^|[\\s;|&(])(?:npm|pnpm|yarn|bun)\\s+(?:install|i|add)\\b[^\\n;|&]*?\\s(${LOCAL_DB_PACKAGES.map(escapeForRegExp).join('|')})(?:@[^\\s]*)?(?=\\s|$)`,
);
const LOCAL_DB_CLI = /(^|[\s;|&(])npx\s+(?:--?\S+\s+)*(prisma|drizzle-kit|knex|sequelize-cli|typeorm)\b/;

const HARD_NO_DB =
  'Piezas: business data lives in Piezas, never in a local database. ' +
  'Store records through @piezas/sdk (Entity Records) instead — read the `entities` rules before writing that code.';

// shellWriteTargets — files a shell command writes via > / >> / tee. Ignores fd
// redirects (2>&1, >&2) and /dev/null. Best effort: it is a guard, not a parser.
export function shellWriteTargets(command) {
  const targets = new Set();
  const text = String(command || '');
  const redirect = /(?:^|[^0-9&<>])>{1,2}\s*(?!&)("[^"]+"|'[^']+'|[^\s;|&<>()]+)/g;
  let m = redirect.exec(text);
  while (m) {
    targets.add(m[1].replace(/^['"]|['"]$/g, ''));
    m = redirect.exec(text);
  }
  const tee = /(?:^|[\s;|&(])tee\s+(?:-[a-z]+\s+)*("[^"]+"|'[^']+'|[^\s;|&<>()]+)/g;
  m = tee.exec(text);
  while (m) {
    targets.add(m[1].replace(/^['"]|['"]$/g, ''));
    m = tee.exec(text);
  }
  return [...targets].filter((t) => t && t !== '/dev/null' && !t.startsWith('/dev/'));
}

function hardNoShellVerdict(command) {
  if (!command) return null;
  if (AGENT_APPROVE.test(command)) {
    return guardBlock(
      'Piezas: only the customer can approve the design. Do not run the approve command yourself. ' +
        'Show them the preview and ask them to reply with the single word "approve" when they are happy. ' +
        'Their reply is recorded automatically.',
    );
  }
  if (AGENT_IMPORT_CHOOSE.test(command)) {
    return guardBlock(
      'Piezas: only the owner can choose what Piezas takes over. Do not record it yourself. ' +
        'Run `piezas import ask <item>`, ask the question it prints, and wait: their reply is recorded automatically.',
    );
  }
  const install = LOCAL_DB_INSTALL.exec(command);
  if (install) return guardBlock(`${HARD_NO_DB} (blocked: installing ${install[2]})`);
  const cli = LOCAL_DB_CLI.exec(command);
  if (cli) return guardBlock(`${HARD_NO_DB} (blocked: npx ${cli[2]})`);
  return null;
}

const PIEZAS_KEY_PUBLIC = /\b(?:NEXT_PUBLIC|VITE|PUBLIC)_[A-Z0-9_]*PIEZAS_API_KEY\b|\b(?:NEXT_PUBLIC|VITE|PUBLIC)_PIEZAS_(?![A-Z0-9_]*PUBLISHABLE)[A-Z0-9_]*(?:KEY|SECRET|TOKEN)\b/;
const USE_CLIENT = /^\s*(?:\/\/[^\n]*\n|\/\*[\s\S]*?\*\/\s*)*\s*['"]use client['"]/;
const PIEZAS_SECRET_LITERAL = /\bsk_(?:live|test)_[A-Za-z0-9]{12,}\b/;

function hardNoWriteVerdict(relPath, content) {
  if (typeof content !== 'string' || !content) return null;
  const name = basename(relPath);
  const isEnvFile = name.startsWith('.env');

  if (PIEZAS_KEY_PUBLIC.test(content)) {
    return guardBlock(
      `Piezas: ${relPath} would publish the Piezas API key to the browser — a NEXT_PUBLIC_/VITE_/PUBLIC_ prefix compiles it into the page for every visitor. ` +
        'Read PIEZAS_API_KEY with no prefix, on the server only (an API route or server component).',
    );
  }
  if (!isEnvFile && PIEZAS_SECRET_LITERAL.test(content)) {
    return guardBlock(
      `Piezas: ${relPath} contains a Piezas secret key written into the code. Keys belong in .env only (and .env stays out of git). ` +
        'Read it from process.env.PIEZAS_API_KEY on the server.',
    );
  }
  if (USE_CLIENT.test(content) && /\bPIEZAS_API_KEY\b/.test(content)) {
    return guardBlock(
      `Piezas: ${relPath} is a client component ('use client') but reads PIEZAS_API_KEY. The key must stay on the server: ` +
        'move the Piezas call into an API route or a server component and pass only the data down.',
    );
  }

  const appSource = isCodeFile(relPath) && !NON_APP_DIRS.test(relPath) && !TEST_FILE_NAME.test(relPath) && !CONFIG_FILE_NAME.test(relPath);
  if (appSource) {
    const imported = LOCAL_DB_IMPORT.exec(content);
    if (imported) return guardBlock(`${HARD_NO_DB} (blocked: ${relPath} imports ${imported[1]})`);
    if (CREATE_TABLE.test(content)) return guardBlock(`${HARD_NO_DB} (blocked: ${relPath} creates a table with raw SQL)`);
  }
  if (name === 'package.json') {
    try {
      const pkg = JSON.parse(content);
      const deps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };
      const found = LOCAL_DB_PACKAGES.find((dep) => Object.prototype.hasOwnProperty.call(deps, dep));
      if (found) return guardBlock(`${HARD_NO_DB} (blocked: package.json adds ${found})`);
    } catch {
      // Partial JSON (an Edit fragment) — doctor judges the finished file.
    }
  }
  return null;
}

// ===========================================================================
// Sandbox: a simulated Piezas platform behind the injectable fetch
// ===========================================================================
//
// JIGSAW SEAM. `init --sandbox` marks the project (manifest.sandbox = true).
// From then on every platform call the CLI makes — create app, mint key, stage
// the hosted env, deploy, status, logs, env — is answered by this in-process
// simulator, with state in .piezas/sandbox.json. The CLI's own logic runs
// UNCHANGED: real preflight checks, real packaging, real requiredEnv gate, real
// attestation. Only the transport is fake. When Piezas sign-in for coding tools
// lands, `connect` signs in, creates the real app and drops `sandbox` — the same
// commands then reach the real platform. Anonymous downloads (the contract, the
// spec, the npm registry) still go to the network.

const SANDBOX_STATE = 'sandbox.json';
const SANDBOX_CONNECT_EXIT = 3;

export const SANDBOX_CREDENTIALS = Object.freeze({
  cliToken: 'sandbox-cli-token',
  tenantId: 'sandbox',
  tenantName: 'your workspace (sandbox)',
  email: 'you@sandbox.piezas.ai',
  apiBase: DEFAULT_API_BASE_URL,
  sandbox: true,
});

export const SANDBOX_NOTE =
  'SANDBOX: Piezas is simulated for this project — the app, its key, its hosted settings and its deployments ' +
  'are real-shaped but nothing is created or published. The same commands reach the real platform once the ' +
  'app is connected (Piezas sign-in for coding tools).';

function readManifestSafe(projectDir) {
  try {
    return readJsonFile(resolve(projectDir, 'piezas.manifest.json'));
  } catch {
    return null;
  }
}

export function isSandboxProject(projectDir) {
  return readManifestSafe(projectDir)?.sandbox === true;
}

function platformCredentials(projectDir, env) {
  return isSandboxProject(projectDir) ? { ...SANDBOX_CREDENTIALS } : readCredentials(env);
}

function platformFetch(projectDir, options) {
  const inner = options.fetchFn ?? fetch;
  return isSandboxProject(projectDir) ? sandboxFetch(projectDir, inner) : inner;
}

function sandboxStatePath(projectDir) {
  return join(projectDir, STATE_DIR, SANDBOX_STATE);
}

function loadSandbox(projectDir) {
  try {
    const parsed = JSON.parse(readFileSync(sandboxStatePath(projectDir), 'utf-8'));
    return { version: 1, apps: [], keys: [], env: {}, deployments: {}, ...parsed };
  } catch {
    return { version: 1, apps: [], keys: [], env: {}, deployments: {} };
  }
}

function saveSandbox(projectDir, state) {
  mkdirSync(join(projectDir, STATE_DIR), { recursive: true });
  writeFileSync(sandboxStatePath(projectDir), `${JSON.stringify(state, null, 2)}\n`);
}

function sandboxResponse(status, data) {
  return { status, ok: status >= 200 && status < 300, json: async () => data, text: async () => JSON.stringify(data) };
}

// sandboxFetch — answers the platform routes the CLI uses; everything else is
// passed to `inner` (the real network, or a test stub).
export function sandboxFetch(projectDir, inner = fetch) {
  return async (url, init = {}) => {
    let parsed;
    try {
      parsed = new URL(String(url));
    } catch {
      return inner(url, init);
    }
    const path = parsed.pathname;
    const method = String(init.method || 'GET').toUpperCase();
    const isPlatform = /\/v1\/(tenants|deployments|portal)(\/|$)/.test(path);
    if (!isPlatform) return inner(url, init);

    const state = loadSandbox(projectDir);
    const json = () => {
      try {
        return typeof init.body === 'string' ? JSON.parse(init.body) : {};
      } catch {
        return {};
      }
    };
    const appBy = (appId, slug) =>
      state.apps.find((a) => (appId && a.id === appId) || (slug && a.slug === slug));
    const envKeys = (app) => Object.keys(state.env[app.id] || {}).sort();
    const reply = (status, data) => {
      saveSandbox(projectDir, state);
      return sandboxResponse(status, data);
    };

    let m;
    // --- control plane -------------------------------------------------------
    if ((m = /\/v1\/tenants\/[^/]+\/partitions$/.exec(path)) && method === 'POST') {
      const name = String(json().name || '').trim() || 'app';
      const slug = slugifyAppName(name);
      if (appBy(null, slug)) return reply(409, { error: `an app named "${name}" already exists` });
      const app = { id: randomUUID(), tenantId: 'sandbox', name, slug, createdAt: new Date().toISOString() };
      state.apps.push(app);
      return reply(201, app);
    }
    if (/\/v1\/tenants\/[^/]+\/(my-apps|partitions)$/.test(path) && method === 'GET') {
      return reply(200, { data: state.apps });
    }
    if (/\/v1\/tenants\/[^/]+\/api-keys$/.test(path) && method === 'POST') {
      const body = json();
      if (!appBy(body.partitionId, null)) return reply(404, { error: 'unknown app' });
      const key = `sk_test_sandbox_${randomBytes(16).toString('hex')}`;
      state.keys.push({ id: randomUUID(), appId: body.partitionId, prefix: key.slice(0, 20), createdAt: new Date().toISOString() });
      return reply(201, { key, environment: 'test' });
    }
    if (path.includes('/v1/portal/')) {
      return reply(400, { error: 'sandbox: sign-in is simulated; nothing to do here' });
    }

    // --- apps server -----------------------------------------------------------
    if (/\/v1\/deployments$/.test(path) && method === 'GET') {
      return reply(200, { data: Object.values(state.deployments), limits: { used: Object.keys(state.deployments).length, maxApps: 0 } });
    }
    if (/\/v1\/deployments$/.test(path) && method === 'POST') {
      const form = init.body;
      const field = (k) => (form && typeof form.get === 'function' ? form.get(k) : undefined);
      const app = appBy(field('appId'), slugifyAppName(String(field('app') || '')));
      if (!app) return reply(404, { error: 'unknown app — run init again' });
      const sent = (() => {
        try { return JSON.parse(field('env') || '{}'); } catch { return {}; }
      })();
      state.env[app.id] = { ...(state.env[app.id] || {}), ...sent };
      const required = (() => {
        try { return JSON.parse(field('requiredEnv') || '[]'); } catch { return []; }
      })();
      const missing = required.filter((k) => !(k in state.env[app.id]));
      if (missing.length) return reply(422, { error: `required settings not set: ${missing.join(', ')}` });
      const artifact = field('artifact');
      const artifactBytes = artifact && typeof artifact.size === 'number' ? artifact.size : 0;
      if (!artifactBytes) return reply(400, { error: 'empty artifact' });
      // Simulates the hosting check's confirm mode, from the project's own files.
      const RULE_OF = { PZ020: 'local-database', PZ021: 'key-in-browser', PZ001: 'key-in-browser', PZ002: 'key-in-browser' };
      const findings = hardNoFindings(projectDir).map((f) => ({ rule: RULE_OF[f.code] ?? 'other', path: f.file ?? '', detail: f.code }));
      let riskAcknowledged = null;
      if (findings.length) {
        const fp = createHash('sha256')
          .update(findings.map((f) => `${f.rule}\u0000${f.path}`).sort().join('\n'))
          .digest('hex')
          .slice(0, 24);
        if (String(field('acknowledgeHardNo') || '') !== fp) {
          const what = findings
            .map((f) => (f.rule === 'local-database'
              ? `the app keeps its own local database (${f.path})`
              : `the Piezas key would be visible to everyone who opens the app (${f.path})`))
            .join('; ');
          return reply(409, {
            error: `Paused before going live: ${what}. Your AI tool can usually fix this. To deploy this version anyway, the app owner must confirm.`,
            needsConfirmation: true,
            fingerprint: fp,
            hardNo: findings,
          });
        }
        riskAcknowledged = { fingerprint: fp, findings, by: 'sandbox-owner', at: new Date().toISOString() };
      }
      const attestation = (() => {
        try { return JSON.parse(field('attestation') || 'null'); } catch { return null; }
      })();
      const dep = {
        slug: app.slug,
        appId: app.id,
        url: `https://${app.slug}.apps.piezas.ai`,
        status: 'running',
        kind: field('kind') || 'server',
        artifactBytes,
        attestation,
        deployedAt: new Date().toISOString(),
        simulated: true,
        ...(riskAcknowledged ? { riskAcknowledged } : {}),
      };
      state.deployments[app.slug] = dep;
      return reply(201, { slug: dep.slug, url: dep.url, status: dep.status, kind: dep.kind, simulated: true });
    }
    if ((m = /\/v1\/deployments\/([^/]+)\/logs$/.exec(path)) && method === 'GET') {
      const dep = state.deployments[m[1]];
      if (!dep) return reply(404, { error: 'no deployment' });
      return reply(200, { logs: `[sandbox] ${dep.slug} was deployed (simulated) at ${dep.deployedAt}. No server runs in the sandbox, so there is no live output.` });
    }
    if ((m = /\/v1\/deployments\/([^/]+)\/env$/.exec(path)) && method === 'PATCH') {
      const app = appBy(parsed.searchParams.get('appId'), m[1]);
      if (!app) return reply(404, { error: 'unknown app' });
      const body = json();
      const cur = { ...(state.env[app.id] || {}), ...(body.set || {}) };
      for (const k of body.unset || []) delete cur[k];
      state.env[app.id] = cur;
      return reply(200, { slug: app.slug, status: state.deployments[app.slug] ? 'running' : 'not deployed', envKeys: envKeys(app) });
    }
    if ((m = /\/v1\/deployments\/([^/]+)$/.exec(path))) {
      const app = appBy(parsed.searchParams.get('appId'), m[1]);
      if (!app) return reply(404, { error: 'no such app' });
      const dep = state.deployments[app.slug];
      if (method === 'DELETE') {
        if (!dep) return reply(404, { error: 'no deployment' });
        delete state.deployments[app.slug];
        return reply(200, { slug: app.slug, deleted: true });
      }
      return reply(200, {
        slug: app.slug,
        url: dep?.url ?? null,
        status: dep ? dep.status : 'not deployed',
        envKeys: envKeys(app),
        simulated: true,
      });
    }
    return reply(404, { error: `sandbox: no simulated route for ${method} ${path}` });
  };
}

// connect — the socket the sign-in piece plugs into. Today it only explains.
export function connectApp(startDir = process.cwd()) {
  const sandbox = isSandboxProject(startDir);
  return {
    exitCode: SANDBOX_CONNECT_EXIT,
    command: 'connect',
    json: { command: 'connect', ok: false, status: 'not-available-yet', sandbox },
    output: [
      sandbox ? SANDBOX_NOTE : 'Connecting a project to Piezas from a coding tool arrives with Piezas sign-in.',
      'Until then, an existing account can still use `npx piezas login` and `npx piezas init`.',
    ],
  };
}

// ===========================================================================
// Deploying despite a never-rule finding: the OWNER confirms, not the AI
// ===========================================================================
//
// The hosting server pauses a deploy whose build breaks a never-rule and
// returns a fingerprint of exactly what it found. The owner confirms that
// fingerprint — at the terminal prompt, or by typing "deploy anyway" in their
// AI tool (recorded by the UserPromptSubmit hook into the guarded state file,
// so the AI cannot confirm for them). The next deploy sends it back; anything
// new asks again. During the BUILD the rules are never optional: the guards
// and the step gate still refuse.

const DEPLOY_RISK_FILE = 'deploy-confirm.json';
const DEPLOY_ANYWAY = 'deploy anyway';

function pendingDeployRisk(projectDir) {
  const root = findProjectRoot(projectDir) ?? resolve(projectDir);
  try {
    return JSON.parse(readFileSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), 'utf-8'));
  } catch {
    return null;
  }
}

function clearPendingDeployRisk(projectDir) {
  const root = findProjectRoot(projectDir) ?? resolve(projectDir);
  try {
    rmSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), { force: true });
  } catch {
    // best effort
  }
}

function recordDeployRisk(projectDir, fingerprint, via) {
  const root = findProjectRoot(projectDir);
  if (!root) return false;
  const state = loadState(root);
  if (state.approvals.some((a) => a.gate === 'deploy-risk' && a.fingerprint === fingerprint)) return true;
  saveState(root, {
    ...state,
    approvals: [...state.approvals, { gate: 'deploy-risk', by: 'user', via, fingerprint, at: new Date().toISOString() }],
  });
  return true;
}

// confirmedDeployRisk — the pending fingerprint, if the owner has confirmed it.
function confirmedDeployRisk(projectDir) {
  const pending = pendingDeployRisk(projectDir);
  const root = findProjectRoot(projectDir);
  if (!pending?.fingerprint || !root) return null;
  try {
    const ok = loadState(root).approvals.some((a) => a.gate === 'deploy-risk' && a.fingerprint === pending.fingerprint);
    return ok ? pending.fingerprint : null;
  } catch {
    return null;
  }
}

async function deployNeedsConfirmation(projectDir, options, data) {
  const root = findProjectRoot(projectDir) ?? resolve(projectDir);
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(
    join(root, STATE_DIR, DEPLOY_RISK_FILE),
    `${JSON.stringify({ fingerprint: data.fingerprint, hardNo: data.hardNo ?? [], message: data.error ?? '', at: new Date().toISOString() }, null, 2)}\n`,
  );
  log('');
  log(`  ${data.error || 'Paused before going live: this version breaks a Piezas rule.'}`);
  log('  The version that is already live keeps running.');

  const canAsk = !options.acknowledge && options.interactive !== false &&
    (options.promptFn || (options.interactive === true && process.stdin.isTTY));
  if (canAsk) {
    const promptFn = options.promptFn ?? promptViaTerminal;
    const answer = String((await promptFn(`  Type "${DEPLOY_ANYWAY}" to put this version live anyway, or press Enter to stop and fix it: `)) ?? '')
      .trim()
      .toLowerCase();
    if (answer === DEPLOY_ANYWAY) {
      recordDeployRisk(projectDir, data.fingerprint, 'terminal');
      log('');
      return deploy({ ...options, acknowledge: data.fingerprint });
    }
    log('  Stopped. Fix the problem (your AI tool can), then deploy again.\n');
  } else {
    log(`  To go live anyway, the app owner must reply "${DEPLOY_ANYWAY}". Otherwise, fix the problem and deploy again.\n`);
  }
  return { exitCode: 1, command: 'deploy', status: 'needs-confirmation', fingerprint: data.fingerprint, hardNo: data.hardNo ?? [] };
}

// ===========================================================================
// Showcase: what the customer looks at instead of reading a requirements doc
// ===========================================================================
//
// .piezas/showcase/index.html — the app in plain words (overview + what it
// does, no ids), screenshots of the key screens (desktop + phone), and short
// clips of each journey recorded from the scenario tests. The customer approves
// what they SAW. Screens and clips use the Playwright the test harness installs.

const SHOWCASE_DIR = 'showcase';

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function readSpecForShowcase(root) {
  let text = '';
  try {
    text = readFileSync(join(root, SPEC_FILE), 'utf-8');
  } catch {
    return { overview: '', requirements: [], scenarios: [] };
  }
  const lines = blankComments(text).split(/\r?\n/);
  const sections = splitSections(lines);
  // Provenance notes ("(Stated: …)", "(Assumed)", "(from x.xlsx)") are for the
  // builder; the customer only needs to know which lines were GUESSES.
  const PROVENANCE = /\s*\((?:stated|assumed|assumption|from|source)\b[^)]*\)/gi;
  const overview = (sections.get('overview')?.lines ?? [])
    .map((l) => l.text.trim())
    .filter((t) => t && !t.startsWith('#'))
    .join(' ')
    .replace(PROVENANCE, '')
    .trim();
  const requirements = (sections.get('requirements')?.lines ?? [])
    .map((l) => {
      const m = REQUIREMENT_LINE.exec(l.text);
      if (!m) return null;
      const raw = l.text.slice(m.index + m[0].length);
      const assumed = /\((?:[^)]*;\s*)?assum/i.test(raw);
      const text = raw.replace(PROVENANCE, '').replace(/\*\*/g, '').trim();
      return text ? { text, assumed } : null;
    })
    .filter(Boolean);
  const scenarios = parseSpec(text).scenarios.map((sc) => ({ id: sc.id, title: sc.title }));
  return { overview, requirements, scenarios };
}

function showcasePath(root, ...parts) {
  return join(root, STATE_DIR, SHOWCASE_DIR, ...parts);
}

function listDirSafe(dir) {
  try {
    return readdirSync(dir).sort();
  } catch {
    return [];
  }
}

export function buildShowcase(startDir = process.cwd(), options = {}) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const appName = readManifestSafe(root)?.appName || basename(root);
  const spec = readSpecForShowcase(root);
  const stateFile = showcasePath(root, 'showcase.json');
  let saved = {};
  try {
    saved = JSON.parse(readFileSync(stateFile, 'utf-8'));
  } catch {
    // first build
  }
  const previewUrl = options.previewUrl || saved.previewUrl || '';
  // Journey-end screens (S-nnn.png: signed in, real state) lead; URL shots follow.
  const allShots = listDirSafe(showcasePath(root, 'shots')).filter((f) => f.endsWith('.png'));
  const shots = [...allShots.filter((f) => /^S-\d{3,}\.png$/.test(f)), ...allShots.filter((f) => !/^S-\d{3,}\.png$/.test(f))];
  const clips = listDirSafe(showcasePath(root, 'clips')).filter((f) => f.endsWith('.webm'));
  const titleFor = (id) => spec.scenarios.find((sc) => sc.id === id)?.title || 'Journey';
  const label = (file) => {
    const id = /^(S-\d{3,})\.png$/.exec(file)?.[1];
    if (id) return titleFor(id);
    return file.replace(/\.png$/, '').replace(/-(desktop|phone)$/, ' ($1)').replace(/-/g, ' ');
  };

  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(appName)}</title>
<style>
:root{--bg:#faf9f6;--ink:#1c1b19;--muted:#5d5a54;--card:#fff;--line:#e5e1d8;--accent:#0e7c5a}
@media (prefers-color-scheme:dark){:root{--bg:#161512;--ink:#f1eee8;--muted:#b3ada3;--card:#211f1b;--line:#38342d;--accent:#5fc59e}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;padding:32px 20px 64px}
main{max-width:960px;margin:0 auto}h1{font-size:32px;margin:0 0 8px}h2{font-size:20px;margin:40px 0 12px}
.lede{color:var(--muted);font-size:18px;max-width:65ch}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:18px 22px}
ul{margin:0;padding-left:20px}li{margin:6px 0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px}
figure{margin:0}img,video{width:100%;border:1px solid var(--line);border-radius:10px;background:#000}figcaption{color:var(--muted);font-size:14px;margin-top:6px}
a{color:var(--accent)}.empty{color:var(--muted)}.guess{display:inline-block;margin-left:6px;padding:1px 8px;border-radius:999px;font-size:12px;background:#fdf1d8;color:#7a5200}@media (prefers-color-scheme:dark){.guess{background:#4a3a14;color:#f3d48a}}
</style></head><body><main>
<h1>${escapeHtml(appName)}</h1>
${spec.overview ? `<p class="lede">${escapeHtml(spec.overview)}</p>` : ''}
${previewUrl ? `<p>Try it yourself: <a href="${escapeHtml(previewUrl)}">${escapeHtml(previewUrl)}</a> (sample data only)</p>` : ''}
<h2>What it does</h2>
<div class="card">${spec.requirements.length ? `<ul>${spec.requirements.map((r) => `<li>${escapeHtml(r.text)}${r.assumed ? ' <span class="guess">my guess — check this</span>' : ''}</li>`).join('')}</ul>` : '<p class="empty">The description is still being written.</p>'}</div>
<h2>The screens</h2>
${shots.length ? `<div class="grid">${shots.map((f) => `<figure><img src="shots/${escapeHtml(f)}" alt="${escapeHtml(label(f))}"><figcaption>${escapeHtml(label(f))}</figcaption></figure>`).join('')}</div>` : '<p class="empty">Screens appear here once the preview is running.</p>'}
<h2>Watch it work</h2>
${clips.length ? `<div class="grid">${clips.map((f) => `<figure><video src="clips/${escapeHtml(f)}" controls muted playsinline></video><figcaption>${escapeHtml(titleFor(f.replace(/\.webm$/, '')))}</figcaption></figure>`).join('')}</div>` : '<p class="empty">Short clips of each journey appear here once the app is built and tested.</p>'}
</main></body></html>
`;
  mkdirSync(showcasePath(root), { recursive: true });
  writeFileSync(showcasePath(root, 'index.html'), html);
  writeFileSync(stateFile, `${JSON.stringify({ previewUrl }, null, 2)}\n`);
  return { page: showcasePath(root, 'index.html'), shots: shots.length, clips: clips.length };
}

// collectClips — Playwright writes one folder per test with video.webm; keep
// one clip per scenario (the folder name carries the S-nnn of its file).
export function collectClips(startDir = process.cwd()) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const raw = showcasePath(root, 'clips-raw');
  const out = showcasePath(root, 'clips');
  mkdirSync(out, { recursive: true });
  const found = [];
  for (const name of listDirSafe(raw)) {
    const id = /\b(S-\d{3,})\b/.exec(name)?.[1];
    const video = join(raw, name, 'video.webm');
    if (!id || !existsSync(video) || found.some((c) => c.scenario === id)) continue;
    copyFileSync(video, join(out, `${id}.webm`));
    // The screen at the END of the journey — signed in, real state — beats a
    // screenshot of a URL, which for most apps is the sign-in page.
    const still = listDirSafe(join(raw, name)).find((f) => /^test-finished.*\.png$/.test(f));
    if (still) {
      mkdirSync(showcasePath(root, 'shots'), { recursive: true });
      copyFileSync(join(raw, name, still), showcasePath(root, 'shots', `${id}.png`));
    }
    found.push({ scenario: id, file: `${id}.webm` });
  }
  return found.sort((a, b) => a.scenario.localeCompare(b.scenario));
}

function hasPlaywright(root) {
  return existsSync(join(root, 'node_modules', '@playwright', 'test', 'package.json'));
}

const PLAYWRIGHT_MISSING = 'screens and clips need the test tools installed once: npm install && npx playwright install';

function routeSlug(route) {
  return route.replace(/^\/+|\/+$/g, '').replace(/[^a-zA-Z0-9]+/g, '-').toLowerCase() || 'home';
}

export async function previewShots(startDir = process.cwd(), options = {}) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const url = typeof options.url === 'string' && options.url ? options.url.replace(/\/+$/, '') : '';
  const routes = Array.isArray(options.routes) && options.routes.length ? options.routes : ['/'];
  if (!url) return { exitCode: 2, command: 'preview shots', output: ['preview shots needs --url <the running preview, e.g. http://localhost:3000>'] };
  if (!hasPlaywright(root)) return { exitCode: 1, command: 'preview shots', output: [PLAYWRIGHT_MISSING] };

  const dir = showcasePath(root, 'shots');
  mkdirSync(dir, { recursive: true });
  const script = showcasePath(root, 'shots.mjs');
  writeFileSync(script, `import { chromium, devices } from '@playwright/test';
const [url, outDir, routes] = [process.argv[2], process.argv[3], JSON.parse(process.argv[4])];
const browser = await chromium.launch();
const sizes = { desktop: { viewport: { width: 1280, height: 800 } }, phone: devices['iPhone 13'] };
for (const [name, ctxOpts] of Object.entries(sizes)) {
  const context = await browser.newContext(ctxOpts);
  const page = await context.newPage();
  for (const { route, slug } of routes) {
    await page.goto(url + route, { waitUntil: 'networkidle' });
    await page.screenshot({ path: outDir + '/' + slug + '-' + name + '.png', fullPage: false });
  }
  await context.close();
}
await browser.close();
`);
  const runner = options.execFn ?? ((cmd, args, opts) => spawnSync(cmd, args, opts));
  const result = runner(process.execPath, [script, url, dir, JSON.stringify(routes.map((r) => ({ route: r.startsWith('/') ? r : `/${r}`, slug: routeSlug(r) })))], {
    cwd: root,
    encoding: 'utf-8',
  });
  if (result.status !== 0) {
    const detail = String(result.stderr || result.stdout || '').split('\n').find((l) => l.trim()) || 'unknown error';
    return { exitCode: 1, command: 'preview shots', output: [`could not capture the screens: ${detail.slice(0, 200)}`, `is the preview running at ${url}?`] };
  }
  const page = buildShowcase(root, { previewUrl: url });
  return { exitCode: 0, command: 'preview shots', page: page.page, output: [`screens: ${page.shots} captured`, `showcase: ${page.page}`] };
}

export async function previewClips(startDir = process.cwd(), options = {}) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  if (!hasPlaywright(root)) return { exitCode: 1, command: 'preview clips', output: [PLAYWRIGHT_MISSING] };
  const configName = existsSync(join(root, 'playwright.config.ts')) ? 'playwright.config.ts' : 'playwright.config.js';
  mkdirSync(showcasePath(root), { recursive: true });
  rmSync(showcasePath(root, 'clips-raw'), { recursive: true, force: true });
  const wrapper = showcasePath(root, 'clips.config.ts');
  // A wrapper, so ANY project's config gets video without being edited.
  // Relative paths in the project's config (its webServer's cwd above all)
  // resolve against the CONFIG's folder, so point them back at the project.
  writeFileSync(wrapper, `import base from '../../${configName.replace(/\.(ts|js)$/, '')}';
const atRoot = (w) => ({ ...w, cwd: w.cwd ? '../../' + w.cwd : '../..' });
export default {
  ...base,
  testDir: '../../tests/scenarios',
  outputDir: './clips-raw',
  reporter: 'line',
  retries: 0,
  use: { ...(base.use ?? {}), video: 'on', screenshot: 'on' },
  webServer: Array.isArray(base.webServer) ? base.webServer.map(atRoot) : base.webServer ? atRoot(base.webServer) : undefined,
};
`);
  const env = { ...process.env, ...(options.url ? { PW_BASE_URL: options.url } : {}) };
  const runner = options.execFn ?? ((cmd, args, opts) => spawnSync(cmd, args, opts));
  runner('npx', ['playwright', 'test', '--config', wrapper], { cwd: root, env, encoding: 'utf-8' });
  const clips = collectClips(root);
  const page = buildShowcase(root, { previewUrl: options.url });
  return {
    exitCode: clips.length ? 0 : 1,
    command: 'preview clips',
    page: page.page,
    output: clips.length
      ? [`clips: ${clips.length} journeys recorded`, `showcase: ${page.page}`]
      : ['no clips were recorded — are there scenario tests in tests/scenarios, and is the app running?'],
  };
}

// ===========================================================================
// When hooks are off: notice it, and re-check at checkpoints
// ===========================================================================

const GUARD_MARKER = 'guard.json';
const GUARD_STALE_MS = 15 * 60 * 1000;

// hardNoFindings — the never-rules only, synchronously, from the SAME scanners
// doctor uses (one source of truth). Used where a hook may not have run:
// moving to the next step, deploying, and the end-of-turn check.
export function hardNoFindings(projectDir) {
  const dir = resolve(projectDir);
  const findings = [];
  const files = existsSync(dir) ? listFiles(dir) : [];
  scanSecretExposure(dir, files, findings);
  scanOAuthTokenStorage(dir, files, findings);
  scanLocalDatabaseUsage(dir, files, findings);
  scanPublicSecretNames(dir, files, findings);
  return findings.filter((f) => f.severity === 'error' && HARD_NO_CODES.has(f.code));
}

function writeGuardMarker(root, payload) {
  try {
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    const host = payload && typeof payload.turn_id === 'string' ? 'codex' : 'claude-code';
    writeFileSync(
      join(root, STATE_DIR, GUARD_MARKER),
      `${JSON.stringify({ active: true, host, lastSeen: new Date().toISOString() })}\n`,
    );
  } catch {
    // best effort: a marker we cannot write must never break a hook
  }
}

// guardWarning — a plain sentence when this project's guardrails have not run
// recently (hooks off, plugin missing, Node missing), else null. Commands an
// agent runs go through PreToolUse first, so a live session is always fresh.
export function guardWarning(startDir = process.cwd()) {
  const root = findProjectRoot(startDir);
  if (!root) return null;
  try {
    const marker = JSON.parse(readFileSync(join(root, STATE_DIR, GUARD_MARKER), 'utf-8'));
    const age = Date.now() - Date.parse(marker.lastSeen);
    if (marker.active === true && Number.isFinite(age) && age < GUARD_STALE_MS) return null;
  } catch {
    // missing or unreadable marker -> warn below
  }
  return (
    "Piezas safety checks are off in this session, so the app's Piezas rules are not being enforced as it is built. " +
    'In Claude Code or Codex, turn them back on: keep the Piezas plugin enabled (Codex: open /hooks and trust Piezas). ' +
    'Running this command yourself in a terminal? Then you can ignore this.'
  );
}

// ===========================================================================
// Import: bring an app the owner already has onto Piezas
// ===========================================================================
//
// Many owners arrive with an app already started (Lovable, Claude Code, a
// freelancer). `init --import <folder>` COPIES it into the project folder, never
// touching the original, and starts the same guided flow as a fresh app: the
// description is drafted from what the code does, the owner confirms by seeing
// it, and the build moves it onto Piezas.
//
// The scan sorts what it finds into two lists:
//   must move     — the never-rules (hardNoFindings). The app cannot leave the
//                   build step, and a deploy pauses, until they are gone.
//   can take over — services Piezas can replace (records, sign-in, files,
//                   email). Recommended; the owner decides.
// Findings that came WITH the code are recorded as inherited, so they do not
// stop the owner from describing and previewing the app they already have.
// The build-step hard stop is unchanged: leaving the build requires every
// never-rule fixed, inherited or not.

const IMPORT_FILE = 'import.json';
const IMPORT_REL = `${STATE_DIR}/${IMPORT_FILE}`;
const IMPORT_VERSION = 1;
const IMPORT_MAX_FILES = 20_000;
const IMPORT_SKIP_DIRS = new Set([
  'node_modules', '.git', '.hg', '.svn', 'dist', 'build', 'out', '.next', '.nuxt', '.svelte-kit', '.output',
  '.vercel', '.netlify', '.turbo', '.cache', '.parcel-cache', 'coverage', '.piezas', '.expo', '.vite',
]);
const IMPORT_SKIP_FILES = new Set(['.DS_Store', 'Thumbs.db']);
// A folder holding only these is treated as empty: the AI tool may have created them.
const IGNORABLE_IN_EMPTY_DIR = new Set(['.DS_Store', '.claude', '.codex']);
const ENV_TEMPLATE_NAME = /\.(example|sample|template)$/;

function isSecretEnvFile(name) {
  return name.startsWith('.env') && !ENV_TEMPLATE_NAME.test(name);
}

function isInsideDir(child, parent) {
  const rel = relative(parent, child);
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel));
}

function isEffectivelyEmptyDir(dir) {
  try {
    return readdirSync(dir).every((name) => IGNORABLE_IN_EMPTY_DIR.has(name));
  } catch {
    return true; // missing counts as empty
  }
}

// A path typed or dragged into a terminal: quotes and backslash-escaped spaces.
export function cleanTypedPath(value) {
  let text = String(value ?? '').trim();
  const quoted = /^(['"])(.*)\1$/.exec(text);
  if (quoted) text = quoted[2];
  text = text.replace(/\\ /g, ' ');
  if (text === '~' || text.startsWith('~/')) text = join(homedir(), text.slice(1));
  return text;
}

// importDestination — where the copy goes. An explicit target wins. Otherwise
// the current folder when it is empty (the usual case: the owner opened their
// AI tool in a new folder), else a new folder named after the app.
export function importDestination(source, currentDir, targetArg) {
  const src = resolve(source);
  if (targetArg) return resolve(currentDir, targetArg);
  const name = basename(src);
  const candidates = [currentDir, resolve(currentDir, name), resolve(currentDir, `${name}-piezas`), resolve(dirname(src), `${name}-piezas`)];
  for (const dir of candidates) {
    if (isInsideDir(dir, src)) continue;
    if (isEffectivelyEmptyDir(dir)) return dir;
  }
  throw new Error(`Could not find an empty folder for the copy. Name one: piezas init <new-folder> --import "${source}"`);
}

// copyImportedApp — read-only on the source. Leaves out installed packages,
// history, build output and private settings (.env files; templates are kept).
export function copyImportedApp(source, dest) {
  const src = resolve(source);
  let stats;
  try {
    stats = statSync(src);
  } catch {
    throw new Error(`There is no folder at ${source}. Check the path and try again.`);
  }
  if (!stats.isDirectory()) throw new Error(`${source} is a file, not a folder. Point to the folder that holds the app.`);
  const target = resolve(dest);
  const realSrc = realpathSync(src);
  if (isInsideDir(target, src) || isInsideDir(target, realSrc)) {
    throw new Error('The new project folder cannot be inside the app being imported. Choose a folder next to it instead.');
  }
  if (!isEffectivelyEmptyDir(target)) {
    throw new Error(`${target} already has files in it. Choose an empty or new folder for the imported app.`);
  }
  let count = 0;
  const leftOut = new Set();
  const walk = (from, to) => {
    for (const entry of readdirSync(from, { withFileTypes: true })) {
      const name = entry.name;
      const fromPath = join(from, name);
      if (entry.isSymbolicLink()) {
        leftOut.add('shortcuts (links)');
        continue;
      }
      if (entry.isDirectory()) {
        if (IMPORT_SKIP_DIRS.has(name)) {
          leftOut.add(name);
          continue;
        }
        walk(fromPath, join(to, name));
        continue;
      }
      if (!entry.isFile() || IMPORT_SKIP_FILES.has(name)) continue;
      if (isSecretEnvFile(name)) {
        leftOut.add(name);
        continue;
      }
      count += 1;
      if (count > IMPORT_MAX_FILES) {
        throw new Error(`That folder has more than ${IMPORT_MAX_FILES} files. Point to the app's own folder, not a folder that holds many projects.`);
      }
      mkdirSync(to, { recursive: true });
      copyFileSync(fromPath, join(to, name));
    }
  };
  mkdirSync(target, { recursive: true });
  walk(src, target);
  if (count === 0) throw new Error(`${source} has no files to import.`);
  return { source: src, dest: target, files: count, leftOut: [...leftOut].sort() };
}

// --- the scan -------------------------------------------------------------

const TAKEOVER_TEXT = {
  records: {
    title: 'Business records',
    piezas: 'Piezas keeps your records in one safe place, backed up, with the access rules your app needs.',
  },
  'sign-in': {
    title: 'Sign-in and accounts',
    piezas: 'Piezas handles sign-up, sign-in and password resets, so the app never stores passwords itself.',
  },
  files: {
    title: 'Files and uploads',
    piezas: 'Piezas stores uploaded files and documents, with access controls.',
  },
  email: {
    title: 'Email',
    piezas: "Piezas sends the app's account and transactional emails, such as confirmations and password resets.",
  },
};
const TAKEOVER_ORDER = ['records', 'sign-in', 'files', 'email'];

const SIGN_IN_PACKAGES = [
  [/^(next-auth|@auth\/)/, 'Auth.js'],
  [/^@clerk\//, 'Clerk'],
  [/^@auth0\//, 'Auth0'],
  [/^@kinde-oss\//, 'Kinde'],
  [/^(lucia|passport|bcrypt|bcryptjs|argon2|jsonwebtoken|iron-session)$/, 'its own sign-in code'],
];
const FILE_PACKAGES = [
  [/^(@aws-sdk\/client-s3|aws-sdk)$/, 'Amazon S3'],
  [/^@vercel\/blob$/, 'Vercel Blob'],
  [/^(uploadthing|@uploadthing\/)/, 'UploadThing'],
  [/^cloudinary$/, 'Cloudinary'],
  [/^@google-cloud\/storage$/, 'Google Cloud Storage'],
  [/^multer$/, 'its own upload handling'],
];
const EMAIL_PACKAGES = [
  [/^nodemailer$/, 'its own email sending'],
  [/^resend$/, 'Resend'],
  [/^@sendgrid\/mail$/, 'SendGrid'],
  [/^postmark$/, 'Postmark'],
  [/^mailgun\.js$/, 'Mailgun'],
  [/^@mailchimp\/mailchimp_transactional$/, 'Mailchimp'],
  [/^(@emailjs\/browser|emailjs-com)$/, 'EmailJS'],
];
const CONNECTS_TO = [
  [/^(stripe|@stripe\/)/, 'Stripe'],
  [/^openai$/, 'OpenAI'],
  [/^@anthropic-ai\/sdk$/, 'Anthropic'],
  [/^twilio$/, 'Twilio'],
  [/^googleapis$/, 'Google'],
  [/^(@google\/generative-ai|@google\/genai)$/, 'Google Gemini'],
];
const BROWSER_AUTH_KEY = /localStorage\.setItem\(\s*['"`][^'"`]*(user|auth|session|token|login|account)[^'"`]*['"`]/i;
const BROWSER_RECORD_KEY = /localStorage\.setItem\(\s*['"`]([^'"`]+)['"`]\s*,\s*JSON\.stringify/g;
const UI_STORAGE_KEY = /theme|lang|locale|sidebar|tour|onboard|dismiss|cookie|consent|prefer|setting|user|auth|session|token|login|account/i;

function hardNoKey(finding) {
  return `${finding.code}|${finding.file ?? ''}`;
}

function packageDeps(projectDir) {
  const pkg = packageJson(projectDir) || {};
  return Object.keys({ ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) });
}

function firstMatch(table, name) {
  const hit = table.find(([re]) => re.test(name));
  return hit ? hit[1] : null;
}

function joinWords(items) {
  const list = [...new Set(items)];
  if (list.length <= 1) return list.join('');
  return `${list.slice(0, -1).join(', ')} and ${list[list.length - 1]}`;
}

function mustMoveItems(findings) {
  const groups = new Map();
  for (const f of findings) {
    const id = f.code === 'PZ020' ? 'own-database' : ['PZ004', 'PZ005', 'PZ006'].includes(f.code) ? 'provider-tokens' : 'key-in-browser';
    const group = groups.get(id) ?? { id, files: new Set(), names: new Set(), codes: new Set() };
    if (f.file) group.files.add(f.file);
    group.codes.add(f.code);
    const name = /^([A-Z][A-Z0-9_]{2,})\b/.exec(f.message || '');
    if (id === 'key-in-browser' && name) group.names.add(name[1]);
    groups.set(id, group);
  }
  const items = [];
  for (const g of groups.values()) {
    const files = [...g.files].sort();
    if (g.id === 'own-database') {
      items.push({
        id: g.id,
        title: 'The app keeps its own database',
        found: 'Records are stored in a database the app runs itself, which nothing else can see or back up.',
        piezas: 'Your records move to Piezas, where they are backed up and kept in one place.',
        files,
        codes: [...g.codes],
      });
    } else if (g.id === 'key-in-browser') {
      const names = [...g.names];
      items.push({
        id: g.id,
        title: 'A key is built into the pages people open',
        found: `${names.length ? joinWords(names) : 'A key'} can be copied by anyone who opens the app.`,
        piezas: 'The key moves to the server side, where visitors cannot see it. Replace the key afterwards, since it may already have been copied.',
        files,
        codes: [...g.codes],
      });
    } else {
      items.push({
        id: g.id,
        title: 'The app stores access passes for other services',
        found: 'The app keeps the passes that let it act in other services (for example Google).',
        piezas: 'Piezas keeps those connections, and the app keeps only a reference to them.',
        files,
        codes: [...g.codes],
      });
    }
  }
  return items;
}

// detectTakeovers — services Piezas can replace, from the packages the app
// uses and from what its code does. Plain sources ("Supabase", "the browser").
function detectTakeovers(projectDir, files) {
  const found = new Map(); // id -> { sources:Set, files:Set }
  const add = (id, source, file) => {
    const entry = found.get(id) ?? { sources: new Set(), files: new Set() };
    entry.sources.add(source);
    if (file) entry.files.add(file);
    found.set(id, entry);
  };
  const deps = packageDeps(projectDir);
  const hasSupabase = deps.some((d) => d.startsWith('@supabase/'));
  const hasFirebase = deps.some((d) => d === 'firebase' || d === 'firebase-admin');
  for (const dep of deps) {
    const signIn = firstMatch(SIGN_IN_PACKAGES, dep);
    if (signIn) add('sign-in', signIn);
    const fileStore = firstMatch(FILE_PACKAGES, dep);
    if (fileStore) add('files', fileStore);
    const email = firstMatch(EMAIL_PACKAGES, dep);
    if (email) add('email', email);
  }
  let supabaseUse = false;
  let firebaseUse = false;
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    if (/supabase/i.test(content)) {
      if (/(?<!storage)\.from\(\s*['"`]/.test(content)) { add('records', 'Supabase', rel); supabaseUse = true; }
      if (/\.auth\./.test(content)) { add('sign-in', 'Supabase', rel); supabaseUse = true; }
      if (/\.storage\b/.test(content)) { add('files', 'Supabase', rel); supabaseUse = true; }
    }
    if (/firebase/i.test(content)) {
      if (/firebase\/firestore|getFirestore\(|firestore\(\)/.test(content)) { add('records', 'Firebase', rel); firebaseUse = true; }
      if (/firebase\/auth|getAuth\(/.test(content)) { add('sign-in', 'Firebase', rel); firebaseUse = true; }
      if (/firebase\/storage|getStorage\(/.test(content)) { add('files', 'Firebase', rel); firebaseUse = true; }
    }
    if (BROWSER_AUTH_KEY.test(content) && /password/i.test(content)) add('sign-in', 'the browser', rel);
    BROWSER_RECORD_KEY.lastIndex = 0;
    let m = BROWSER_RECORD_KEY.exec(content);
    while (m) {
      if (!UI_STORAGE_KEY.test(m[1])) add('records', 'the browser', rel);
      m = BROWSER_RECORD_KEY.exec(content);
    }
  }
  if (files.some((f) => /(^|\/)supabase\/migrations\/[^/]+\.sql$/.test(normalizeRel(projectDir, f)))) add('records', 'Supabase');
  if (hasSupabase && !supabaseUse && !found.has('records')) add('records', 'Supabase');
  if (hasFirebase && !firebaseUse && !found.has('records')) add('records', 'Firebase');

  const SOURCE_PHRASE = { records: 'Records are kept in', 'sign-in': 'Sign-in is handled by', files: 'Files are stored with', email: 'Email is sent through' };
  return TAKEOVER_ORDER.filter((id) => found.has(id)).map((id) => {
    const entry = found.get(id);
    const sources = [...entry.sources];
    const phrase = sources.map((s) => {
      if (s !== 'the browser') return s;
      return id === 'records' ? 'the browser only (they disappear when the browser is cleared)' : 'accounts saved in the browser';
    });
    return {
      id,
      title: TAKEOVER_TEXT[id].title,
      found: `${SOURCE_PHRASE[id]} ${joinWords(phrase)}.`,
      piezas: TAKEOVER_TEXT[id].piezas,
      sources,
      files: [...entry.files].sort(),
      choice: null,
    };
  });
}

function routeFromAppPage(rel) {
  const parts = rel.replace(/^src\//, '').split('/');
  parts.shift(); // app
  parts.pop(); // page.tsx
  const route = parts.filter((p) => !/^\(.*\)$/.test(p)).join('/');
  return `/${route}`;
}

// importInventory — what the code shows, to seed the description: screens,
// kinds of records, sign-in and outside services. Heuristic, never exhaustive.
function importInventory(projectDir, files, takeovers) {
  const deps = packageDeps(projectDir);
  const isNext = deps.includes('next');
  const screens = [];
  const records = new Set();
  const seenScreen = new Set();
  const addScreen = (name, file) => {
    const key = `${name}|${file}`;
    if (seenScreen.has(key) || screens.length >= 40) return;
    seenScreen.add(key);
    screens.push({ name, file });
  };
  for (const filePath of files) {
    const rel = normalizeRel(projectDir, filePath);
    if (/\.sql$/.test(rel)) {
      const content = readFileSync(filePath, 'utf-8');
      for (const m of content.matchAll(/create\s+table\s+(?:if\s+not\s+exists\s+)?(?:"?public"?\.)?"?([A-Za-z_][\w]*)"?/gi)) records.add(m[1]);
    }
  }
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    if (/(^|\/)app\/(.*\/)?page\.[cm]?[jt]sx?$/.test(rel)) addScreen(routeFromAppPage(rel), rel);
    else if (isNext && /(^|\/)pages\/(?!api\/|_)[^]*\.[jt]sx?$/.test(rel)) {
      const route = rel.replace(/^(src\/)?pages\//, '').replace(/\.[jt]sx?$/, '').replace(/(^|\/)index$/, '');
      addScreen(`/${route}`, rel);
    } else if (!isNext && /(^|\/)(pages|screens|views)\/[^/]+\.[jt]sx$/.test(rel)) {
      addScreen(basename(rel).replace(/\.[jt]sx$/, ''), rel);
    }
    if (/react-router|createBrowserRouter/.test(content)) {
      for (const m of content.matchAll(/<Route\b[^>]*\bpath=["'`]([^"'`]+)["'`]/g)) addScreen(m[1], rel);
      for (const m of content.matchAll(/\bpath:\s*["'`](\/[^"'`]*)["'`]/g)) addScreen(m[1], rel);
    }
    if (/supabase/i.test(content)) {
      for (const m of content.matchAll(/(?<!storage)\.from\(\s*['"`]([A-Za-z_][\w-]*)['"`]\s*\)/g)) records.add(m[1]);
      for (const m of content.matchAll(/^\s*([a-z_][\w]*):\s*\{\s*\n\s*Row:/gm)) records.add(m[1]);
    }
    for (const m of content.matchAll(/collection\(\s*\w+\s*,\s*['"`]([\w-]+)['"`]/g)) records.add(m[1]);
  }
  // Routes from a router say more than page file names; keep names only when
  // no routes were found.
  if (screens.some((s) => s.name.startsWith('/'))) {
    for (let i = screens.length - 1; i >= 0; i -= 1) if (!screens[i].name.startsWith('/')) screens.splice(i, 1);
  }
  const signIn = (takeovers.find((t) => t.id === 'sign-in')?.sources ?? []).map((s) => (s === 'the browser' ? 'accounts saved in the browser' : s));
  const connects = [...new Set(deps.map((d) => firstMatch(CONNECTS_TO, d)).filter(Boolean))];
  return { screens, records: [...records].sort().slice(0, 40), signIn, connectsTo: connects };
}

export function importScan(projectDir) {
  const dir = resolve(projectDir);
  const files = listFiles(dir);
  const hardNo = hardNoFindings(dir);
  const canTakeOver = detectTakeovers(dir, files);
  return {
    mustMove: mustMoveItems(hardNo),
    canTakeOver,
    inventory: importInventory(dir, files, canTakeOver),
    hardNo,
  };
}

export function readImportState(startDir) {
  const root = findProjectRoot(startDir);
  if (!root) return null;
  try {
    const parsed = JSON.parse(readFileSync(join(root, STATE_DIR, IMPORT_FILE), 'utf-8'));
    return parsed && parsed.version === IMPORT_VERSION ? parsed : null;
  } catch {
    return null;
  }
}

function writeImportState(root, data) {
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(join(root, STATE_DIR, IMPORT_FILE), `${JSON.stringify(data, null, 2)}\n`);
}

// recordImport — the first scan of a freshly copied app. The never-rule
// findings present NOW are what the owner brought; they are the baseline.
function recordImport(root, copy) {
  const scan = importScan(root);
  const now = new Date().toISOString();
  const data = {
    version: IMPORT_VERSION,
    source: copy.source,
    importedAt: now,
    scannedAt: now,
    inherited: [...new Set(scan.hardNo.map(hardNoKey))].sort(),
    mustMove: scan.mustMove,
    canTakeOver: scan.canTakeOver,
    customerData: null,
    inventory: scan.inventory,
  };
  writeImportState(root, data);
  return data;
}

// newHardNoFindings — never-rule findings the owner did NOT bring with the
// code. Inherited ones are the build's work order, not a reason to stop them
// describing or previewing their own app.
export function newHardNoFindings(root) {
  const all = hardNoFindings(root);
  const imported = readImportState(root);
  if (!imported || !Array.isArray(imported.inherited)) return all;
  const baseline = new Set(imported.inherited);
  return all.filter((f) => !baseline.has(hardNoKey(f)));
}

// importGaps — what must be settled before the build (owner's choices) and
// before going live (every accepted replacement actually done).
function importGaps(root, phase) {
  const imported = readImportState(root);
  if (!imported) return [];
  const gaps = [];
  if (phase === 'mock') {
    const open = (imported.canTakeOver || []).filter((item) => item.choice !== 'take' && item.choice !== 'keep');
    if (open.length > 0) {
      gaps.push(gap('IMPORT', `ask the owner which services Piezas should take over (${open.map((i) => i.id).join(', ')}): run \`piezas import ask <item>\` for each and ask exactly the question it prints; their own reply is recorded automatically`));
    }
    if (imported.customerData !== 'yes' && imported.customerData !== 'no') {
      gaps.push(gap('IMPORT', 'ask the owner "Does this app already hold real customer data?": run `piezas import ask customer-data` and ask exactly the question it prints; their own reply is recorded automatically'));
    }
  }
  if (phase === 'build') {
    const still = detectTakeovers(root, listFiles(root));
    for (const item of imported.canTakeOver || []) {
      if (item.choice !== 'take') continue;
      const now = still.find((s) => s.id === item.id);
      const left = now ? now.sources.filter((s) => item.sources.includes(s)) : [];
      if (left.length > 0) gaps.push(gap('IMPORT', `${item.title} was to move to Piezas, but the app still uses ${joinWords(left)}`));
    }
  }
  return gaps;
}

function importItemLines(item, marker) {
  const lines = [`  ${marker} ${item.title} — ${item.found}`, `     Piezas: ${item.piezas}`];
  if (item.files?.length) lines.push(`     Where: ${item.files.slice(0, 6).join(', ')}${item.files.length > 6 ? ', …' : ''}`);
  return lines;
}

export function formatImportScan(data) {
  const inv = data.inventory || {};
  const lines = ['What the code shows (draft the description from this and from reading the code; mark each requirement "found in your code: <file>"):'];
  lines.push(`  Screens: ${inv.screens?.length ? inv.screens.map((s) => `${s.name} (${s.file})`).join(', ') : 'none found — read the code'}`);
  lines.push(`  Kinds of records: ${inv.records?.length ? inv.records.join(', ') : 'none found — read the code'}`);
  lines.push(`  Sign-in: ${inv.signIn?.length ? joinWords(inv.signIn) : 'none found'}`);
  if (inv.connectsTo?.length) lines.push(`  Connects to: ${joinWords(inv.connectsTo)}`);
  lines.push('');
  lines.push('Must move to Piezas (the app cannot go live until these are moved):');
  if (data.mustMove?.length) data.mustMove.forEach((item, i) => lines.push(...importItemLines(item, `${i + 1}.`)));
  else lines.push('  nothing');
  lines.push('');
  lines.push('Piezas can take this over (recommended; the owner decides):');
  if (data.canTakeOver?.length) {
    for (const item of data.canTakeOver) {
      const choice = item.choice === 'take' ? '[owner: move to Piezas]' : item.choice === 'keep' ? '[owner: keep as is]' : '[owner: not asked yet]';
      lines.push(...importItemLines({ ...item, title: `${item.title} (${item.id}) ${choice}` }, '-'));
    }
  } else {
    lines.push('  nothing');
  }
  lines.push('');
  const data_ = data.customerData === 'yes' ? 'yes (moving that data is a later, separate step — do not copy or migrate it now)' : data.customerData === 'no' ? 'no' : 'not asked yet';
  lines.push(`Does this app already hold real customer data? ${data_}`);
  return lines;
}

export function importPlanLines(data) {
  const lines = [];
  for (const item of data.mustMove || []) lines.push(`- Must move: ${item.title}. ${item.piezas}`);
  for (const item of data.canTakeOver || []) {
    if (item.choice === 'take') lines.push(`- Move to Piezas (owner's choice): ${item.title} from ${joinWords(item.sources)}. ${item.piezas}`);
  }
  for (const item of data.canTakeOver || []) {
    if (item.choice === 'keep') lines.push(`- Keep as is (owner's choice): ${item.title} with ${joinWords(item.sources)}.`);
  }
  if (data.customerData === 'yes') {
    lines.push('- Existing customer data stays where it is for now. Moving it is a separate, later step: do not copy, export or migrate any data.');
  }
  return lines;
}

export function importCommand(sub, startDir = process.cwd(), options = {}) {
  const root = findProjectRoot(startDir);
  const fail = (message) => ({ exitCode: 1, json: { command: `import ${sub}`, ok: false, error: message }, output: [message] });
  if (!root) return fail('There is no Piezas project here yet. To bring in an existing app: piezas init --import <folder>');
  const current = readImportState(root);
  if (!current) return fail('This project was not imported from existing code, so there is nothing to scan or choose. (Start an import with: piezas init --import <folder>)');

  if (sub === 'scan') {
    const scan = importScan(root);
    // Rescans refresh what is found but never widen the inherited baseline:
    // a never-rule broken after the import is new, whoever broke it.
    const previous = new Map((current.canTakeOver || []).map((i) => [i.id, i]));
    const data = {
      ...current,
      scannedAt: new Date().toISOString(),
      mustMove: scan.mustMove,
      canTakeOver: scan.canTakeOver.map((item) => {
        const before = previous.get(item.id);
        return before?.choice ? { ...item, choice: before.choice } : item;
      }),
      inventory: scan.inventory,
    };
    // An accepted replacement that is now done stays visible as decided.
    for (const [id, before] of previous) {
      if (!data.canTakeOver.some((i) => i.id === id) && before.choice) data.canTakeOver.push({ ...before, done: true });
    }
    writeImportState(root, data);
    return { exitCode: 0, json: { command: 'import scan', ok: true, ...data }, output: formatImportScan(data) };
  }

  if (sub === 'ask') {
    const item = options.item;
    const question = importQuestion(current, item);
    if (!question) {
      const ids = (current.canTakeOver || []).map((i) => i.id);
      return fail(`Ask about one of: ${[...ids, ...(ids.length > 1 ? ['all'] : []), 'customer-data'].join(', ')}.`);
    }
    const data = { ...current, pendingQuestion: { id: item, askedAt: new Date().toISOString() } };
    writeImportState(root, data);
    return {
      exitCode: 0,
      json: { command: 'import ask', ok: true, item, question },
      output: [
        'Ask the owner exactly this, then stop and wait for their reply (it is recorded automatically from their own message):',
        '',
        question,
      ],
    };
  }

  if (sub === 'choose') {
    // Inside an AI tool the owner answers in the chat and the hook records it;
    // the AI never records a choice. This command is for a person at a terminal.
    if (agentHost(options.env ?? process.env)) {
      return fail('The owner\'s choices are recorded from their own replies. Run `piezas import ask <item>`, ask the question it prints, and wait for their answer.');
    }
    const ids = new Set((current.canTakeOver || []).map((i) => i.id));
    const list = (value) => (Array.isArray(value) ? value : value === undefined || value === true ? [] : [value])
      .flatMap((v) => String(v).split(','))
      .map((v) => v.trim())
      .filter(Boolean);
    const take = list(options.take);
    const keep = list(options.keep);
    const unknown = [...take, ...keep].filter((id) => !ids.has(id));
    if (unknown.length) return fail(`Unknown item(s): ${unknown.join(', ')}. Choose from: ${[...ids].join(', ') || 'none'}.`);
    const both = take.filter((id) => keep.includes(id));
    if (both.length) return fail(`${both.join(', ')} cannot be both taken over and kept.`);
    let customerData = current.customerData;
    if (options.customerData !== undefined) {
      const answer = String(options.customerData).trim().toLowerCase();
      if (!['yes', 'no'].includes(answer)) return fail('--customer-data takes yes or no.');
      customerData = answer;
    }
    const data = {
      ...current,
      canTakeOver: (current.canTakeOver || []).map((item) => (
        take.includes(item.id) ? { ...item, choice: 'take' } : keep.includes(item.id) ? { ...item, choice: 'keep' } : item
      )),
      customerData,
      dataMigration: customerData === 'yes' ? 'later' : null,
      decidedAt: new Date().toISOString(),
    };
    writeImportState(root, data);
    return { exitCode: 0, json: { command: 'import choose', ok: true, ...data }, output: ['recorded.', ...importPlanLines(data)] };
  }

  if (sub === 'plan') {
    const lines = importPlanLines(current);
    return {
      exitCode: 0,
      json: { command: 'import plan', ok: true, plan: lines },
      output: lines.length ? ['Build plan for this imported app:', ...lines] : ['Nothing needs to move: the app already follows the Piezas rules.'],
    };
  }
  return fail(`Unknown import command "${sub}". Use: piezas import scan | ask | choose | plan`);
}

// --- the owner's consent ------------------------------------------------------
//
// Each "Piezas can take this over" item is the owner's decision. The AI asks
// one question (`piezas import ask <item>`); the owner's next message is read by
// the UserPromptSubmit hook and recorded only when it is a clear answer. Handing
// the decision back ("use your judgment") is not an answer.

function importQuestion(data, id) {
  if (id === 'customer-data') {
    return 'Does this app already hold real customer data, such as real bookings or real people\'s details? (yes or no)';
  }
  const items = data.canTakeOver || [];
  if (id === 'all' && items.length > 1) {
    return `Should Piezas take over all of these: ${joinWords(items.map((i) => `${i.title.toLowerCase()} (now ${joinWords(i.sources)})`))}? `
      + 'Reply "yes" to move them all, "keep all" to leave them as they are, or tell me which ones to move.';
  }
  const item = items.find((i) => i.id === id);
  if (!item) return null;
  return `${item.title}: your app uses ${joinWords(item.sources)} today. ${item.piezas} Should Piezas take this over? (move or keep)`;
}

const HANDS_BACK = /\b(your (?:call|choice|judge?ment|decision|recommendation)|you (?:decide|choose|pick|know best)|up to you|whatever you (?:think|want|recommend|prefer|suggest)|(?:i )?(?:don'?t|do not) (?:know|mind|care)|what(?:ever)? (?:do )?you (?:think|recommend|suggest)|you tell me|no preference|either is fine|either way)\b/;
const SAYS_KEEP = /\b(no|nope|keep|leave|don'?t|do not|stay|not now|not yet)\b/;
const SAYS_MOVE = /\b(yes|yeah|yep|yup|sure|ok|okay|move|switch|take (?:it |them )?over|go ahead|do it|please do|let'?s do it)\b/;
const SAYS_HAS_DATA = /\b(yes|yeah|yep|yup|it does|we do|real (?:customers?|people|bookings|data))\b/;
const SAYS_NO_DATA = /\b(no|nope|not yet|none|only (?:test|sample|fake)|just (?:test|sample|fake)|it doesn'?t|we don'?t)\b/;

// readOwnerAnswer — the owner's reply to the pending question, or null when it
// is not a clear answer (including when they hand the decision back).
export function readOwnerAnswer(questionId, prompt) {
  const said = String(prompt || '').toLowerCase().replace(/[’]/g, "'").replace(/\s+/g, ' ').trim();
  if (!said || HANDS_BACK.test(said)) return null;
  if (questionId === 'customer-data') {
    const plain = said.replace(/\b(?:no|not any|without) real\b/g, 'no');
    const yes = SAYS_HAS_DATA.test(plain);
    const no = SAYS_NO_DATA.test(plain);
    return yes === no ? null : yes ? 'yes' : 'no';
  }
  if (questionId === 'all') {
    if (/\b(keep (?:them )?all|keep everything|none of them|leave (?:them|everything|it all))\b/.test(said)) return 'keep';
    const keep = SAYS_KEEP.test(said);
    return SAYS_MOVE.test(said) && !keep ? 'take' : null;
  }
  const move = SAYS_MOVE.test(said);
  const keep = SAYS_KEEP.test(said);
  return move === keep ? null : move ? 'take' : 'keep';
}

// recordOwnerReply — called by the UserPromptSubmit hook. Returns a note for
// the session, or '' when no import question was waiting.
function recordOwnerReply(root, prompt) {
  const current = readImportState(root);
  const pending = current?.pendingQuestion;
  if (!pending?.id) return '';
  const answer = readOwnerAnswer(pending.id, prompt);
  const quote = String(prompt || '').trim().slice(0, 200);
  const at = new Date().toISOString();
  if (!answer) {
    writeImportState(root, { ...current, pendingQuestion: null });
    return 'The owner\'s reply was not a clear answer to the question, so nothing was recorded. It is their decision: '
      + 'give your recommendation in one sentence, then run `piezas import ask` again and ask plainly. Do not decide for them.';
  }
  const consent = { question: pending.id, answer, said: quote, at, via: 'owner-reply' };
  let data = { ...current, pendingQuestion: null, consents: [...(current.consents || []), consent], decidedAt: at };
  if (pending.id === 'customer-data') {
    data = { ...data, customerData: answer, dataMigration: answer === 'yes' ? 'later' : null };
  } else {
    data = {
      ...data,
      canTakeOver: (current.canTakeOver || []).map((item) => (
        pending.id === 'all' || item.id === pending.id ? { ...item, choice: answer, decidedBy: 'owner' } : item
      )),
    };
  }
  writeImportState(root, data);
  const what = pending.id === 'customer-data'
    ? `whether the app holds real customer data: ${answer}`
    : `${pending.id === 'all' ? 'every service' : pending.id}: ${answer === 'take' ? 'move to Piezas' : 'keep as is'}`;
  return `The owner answered, and it is recorded (${what}). Continue with the next question, or show the plan if all are answered.`;
}

// importNote — what a session needs to know about an imported app, by step.
function importNote(root, phase) {
  const imported = readImportState(root);
  if (!imported) return '';
  const head = "This app was IMPORTED from the owner's existing code (a copy; their original folder is untouched).";
  if (phase === 'discover') {
    return [
      head,
      'Do not interview from scratch. Run `piezas import scan`, read the code, and draft the description (SPEC.md) from what the app actually does.',
      'Mark each requirement "(found in your code: <file>)". Ask the owner only about what the code cannot tell you (who uses it, what matters most), one question at a time.',
      'Then show the short card and the two lists in plain words (must move to Piezas; Piezas can take this over).',
      "The owner decides each service. For each item on \"Piezas can take this over\", run `piezas import ask <item>` (or `piezas import ask all` to offer them all at once) and ask exactly the question it prints, then wait for their reply. Then run `piezas import ask customer-data` to ask \"Does this app already hold real customer data?\".",
      'Their own reply is recorded automatically. You cannot record a choice for them: "use your judgment", "you decide" or "whatever you think" is not a choice. Give your recommendation in one sentence and ask again.',
      'When everything is answered, ask "Want to see it?".',
    ].join(' ');
  }
  if (phase === 'mock') {
    const lines = [head, 'The preview is their own app running, with sample data where it needs settings it does not have yet. Show it and change only what they ask for.'];
    const gaps = importGaps(root, 'mock');
    if (gaps.length) lines.push(`Still to ask the owner before building: ${gaps.map((g) => g.message).join('; ')}.`);
    return lines.join(' ');
  }
  if (phase === 'build') {
    const plan = importPlanLines(imported);
    return plan.length
      ? [head, 'Build plan (the work of this step; the app cannot go live until it is done):', ...plan].join('\n')
      : head;
  }
  return '';
}

// --- inside an AI tool ------------------------------------------------------

// agentHost — is this command running inside Claude Code or Codex? Their shell
// tools set these variables for every command they run.
export function agentHost(env = process.env) {
  // PIEZAS_AGENT_HOST overrides detection (tests set "none").
  if (env.PIEZAS_AGENT_HOST) return ['claude-code', 'codex'].includes(env.PIEZAS_AGENT_HOST) ? env.PIEZAS_AGENT_HOST : null;
  // Codex first: its variables are set per command, while CLAUDECODE is also
  // inherited by anything started from a Claude Code session.
  if (Object.keys(env).some((key) => /^CODEX_(SANDBOX|THREAD_ID|SESSION_ID|MANAGED_BY)/.test(key))) return 'codex';
  if (env.CLAUDECODE === '1' || env.CLAUDE_CODE_ENTRYPOINT) return 'claude-code';
  return null;
}

// The plugin runs its own copy of this file from <plugin>/vendor/; next to it
// sit the plugin manifests. A CLI from npm has none.
function runningFromPlugin() {
  const root = join(__dirname, '..');
  return existsSync(join(root, '.claude-plugin', 'plugin.json')) || existsSync(join(root, '.codex-plugin', 'plugin.json'));
}

const HOST_NAMES = { 'claude-code': 'Claude Code', codex: 'Codex' };
const PLUGIN_HINT = {
  'claude-code': 'In Claude Code, type /plugin, find Piezas and install it, then start a new session in this folder.',
  codex: 'In Codex, type /plugins, find Piezas and install it, then open /hooks and trust Piezas.',
};

// ===========================================================================
// phase hook — ONE entry point for Claude Code and Codex lifecycle hooks
// ===========================================================================
//
// Both tools send the event as JSON on stdin with `hook_event_name`, `cwd`, and
// for tool events `tool_name` + `tool_input`. Codex edits files through
// `apply_patch` (patch text); Claude Code through Write/Edit/MultiEdit.
// Contract: exit 2 + stderr blocks a PreToolUse; stdout JSON carries context.

const STEP_NAMES = {
  discover: 'Step 1 of 4 — describe the app',
  mock: 'Step 2 of 4 — preview the design',
  build: 'Step 3 of 4 — build it for real',
  ship: 'Step 4 of 4 — go live',
};

const PLAIN_LANGUAGE =
  'Talk to the user as a friendly product manager would talk to a business owner: plain words, short answers, one question at a time. ' +
  'Never show them internal words such as phase, gate, hook, SPEC, R-001/S-001 ids, npx, CLI commands, JSON, or file paths unless they ask. ' +
  'Describe progress as the four steps: describe the app, preview the design, build it for real, go live. ' +
  'When something is blocked, fix it yourself and tell them in one plain sentence what you changed and why.';

function readRuleFile(rulesDir, topic) {
  if (!rulesDir) return '';
  try {
    return readFileSync(join(rulesDir, `${topic}.md`), 'utf-8').trim();
  } catch {
    return '';
  }
}

function hookContext(event, text) {
  return JSON.stringify({ hookSpecificOutput: { hookEventName: event, additionalContext: text } });
}

function isApprovalPrompt(prompt) {
  const p = String(prompt || '').trim().toLowerCase().replace(/[.!]+$/, '');
  return p === 'approve' || p === 'approved' || p === 'i approve' || p === '/piezas:approve' || p === '/approve';
}

function patchTextFrom(input) {
  if (typeof input === 'string') return input.includes('*** Begin Patch') ? input : null;
  if (Array.isArray(input)) {
    for (const part of input) {
      const found = patchTextFrom(part);
      if (found) return found;
    }
    return null;
  }
  if (input && typeof input === 'object') {
    for (const value of Object.values(input)) {
      const found = patchTextFrom(value);
      if (found) return found;
    }
  }
  return null;
}

// parsePatch — Codex's apply_patch envelope -> [{ path, added }].
export function parsePatch(text) {
  const files = [];
  let current = null;
  for (const line of String(text).split('\n')) {
    const header = /^\*\*\* (Add|Update|Delete) File: (.+)$/.exec(line);
    const move = /^\*\*\* Move to: (.+)$/.exec(line);
    if (header) {
      current = { path: header[2].trim(), op: header[1].toLowerCase(), added: [] };
      files.push(current);
    } else if (move && current) {
      current = { path: move[1].trim(), op: 'move', added: current.added };
      files.push(current);
    } else if (current && line.startsWith('+')) {
      current.added.push(line.slice(1));
    }
  }
  return files.map((f) => ({ path: f.path, op: f.op, added: f.added.join('\n') }));
}

function shellCommandFrom(input) {
  const cmd = input?.command ?? input?.cmd;
  if (Array.isArray(cmd)) return cmd.join(' ');
  return typeof cmd === 'string' ? cmd : '';
}

function preToolUse(payload, cwd) {
  const tool = typeof payload.tool_name === 'string' ? payload.tool_name : '';
  const input = payload.tool_input ?? {};

  const patch = tool === 'apply_patch' || tool === 'Edit' || tool === 'Write' ? patchTextFrom(input) : null;
  if (patch) {
    for (const file of parsePatch(patch)) {
      const verdict = phaseGuard({ cwd, tool: 'Write', file: file.path, content: file.added });
      if (verdict.exitCode === 2) return verdict;
    }
    return guardAllow();
  }

  if (tool === 'Bash' || tool === 'shell' || tool === 'exec_command') {
    return phaseGuard({ cwd, tool: 'Bash', command: shellCommandFrom(input) });
  }

  if (tool === 'Write' || tool === 'Edit' || tool === 'MultiEdit') {
    const content =
      typeof input.content === 'string'
        ? input.content
        : typeof input.new_string === 'string'
          ? input.new_string
          : Array.isArray(input.edits)
            ? input.edits.map((e) => (e && typeof e.new_string === 'string' ? e.new_string : '')).join('\n')
            : undefined;
    return phaseGuard({ cwd, tool, file: input.file_path, content });
  }
  return guardAllow();
}

const OFFLINE_FETCH = () => Promise.reject(new Error('offline'));
// Doctor codes for the Hard No rules: secret exposure (PZ001/PZ002), provider
// token storage (PZ004-PZ006), local database (PZ020), public-prefixed secret (PZ021).
const HARD_NO_CODES = new Set(['PZ001', 'PZ002', 'PZ004', 'PZ005', 'PZ006', 'PZ020', 'PZ021']);

export async function phaseHook(payload, options = {}) {
  const done = (exitCode = 0, stdout = '', stderr = '') => ({ exitCode, stdout, stderr });
  if (!payload || typeof payload !== 'object') return done();
  const event = payload.hook_event_name;
  const cwd = typeof payload.cwd === 'string' && payload.cwd ? payload.cwd : process.cwd();
  const root = findProjectRoot(cwd);
  if (root && event) writeGuardMarker(root, payload);

  try {
    if (event === 'PreToolUse') {
      const verdict = preToolUse(payload, cwd);
      if (verdict.exitCode !== 2) return done();
      // Structured deny: both Claude Code and Codex read it, show it as a clean
      // "blocked" notice, and hand the reason to the model as a work order.
      return done(
        0,
        JSON.stringify({
          hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: verdict.reason },
        }),
      );
    }

    if (event === 'SessionStart') {
      const cliLine = options.cliPath
        ? `Piezas command (run it with the shell tool): node "${options.cliPath}" <args> — e.g. node "${options.cliPath}" phase status --context. ` +
          `Wherever a Piezas message says \`npx piezas ...\`, run node "${options.cliPath}" ... instead.`
        : '';
      if (!root) {
        return done(
          0,
          hookContext(
            'SessionStart',
            ['The Piezas plugin is installed. If the user wants to build a business app (bookings, CRM, intake, projects, a client portal), use the piezas skill to guide them.', cliLine]
              .filter(Boolean)
              .join('\n'),
          ),
        );
      }
      const state = loadState(root);
      const gaps = gateGaps(root, state);
      const sandbox = isSandboxProject(root);
      const manifest = sandbox ? readManifestSafe(root) : null;
      const appUrl = manifest?.deploy?.url || (manifest?.appName ? `https://${slugifyAppName(manifest.appName)}.apps.piezas.ai` : '');
      const parts = [
        `[Piezas] This project is a Piezas app. ${STEP_NAMES[state.phase]}.`,
        PLAIN_LANGUAGE,
        sandbox
          ? `${SANDBOX_NOTE} Use the normal Piezas commands (init, deploy, env, status); they run against the simulator. ` +
            `The app's address will be ${appUrl} (simulated). The running app's own data calls cannot reach real Piezas until it is connected, so test screens with sample data.`
          : '',
        cliLine,
        readRuleFile(options.rulesDir, 'core'),
        options.rulesDir
          ? `Before writing code against a Piezas service, read its rules file in ${options.rulesDir}: entities.md, users.md, integrations.md, calendar.md, documents.md, deploy.md, testing.md, patterns.md.`
          : '',
        importNote(root, state.phase),
        'Project state (for you, not for the user):',
        ...contextLines(state, gaps),
      ];
      return done(0, hookContext('SessionStart', parts.filter(Boolean).join('\n\n')));
    }

    if (event === 'UserPromptSubmit') {
      if (!root) return done();
      let state = loadState(root);
      const notes = [];
      const said = String(payload.prompt || '').trim().toLowerCase().replace(/[.!]+$/, '');
      if (said === DEPLOY_ANYWAY || said === '/piezas:deploy-anyway') {
        const pending = pendingDeployRisk(root);
        if (pending?.fingerprint) {
          recordDeployRisk(root, pending.fingerprint, 'user-prompt');
          state = loadState(root);
          notes.push('The owner confirmed (they typed "deploy anyway") putting this version live despite the problems found. Run the deploy again now; tell them in one sentence that it is going live and that fixing the problem is still recommended.');
        } else {
          notes.push('The owner typed "deploy anyway", but no deploy is waiting for confirmation. Tell them where things stand in one sentence.');
        }
      }
      const importReply = recordOwnerReply(root, payload.prompt);
      if (importReply) notes.push(importReply);
      if (isApprovalPrompt(payload.prompt)) {
        if (state.phase === 'mock') {
          if (!approvalFor(state, 'mock')) {
            const approval = { gate: 'mock', by: 'user', via: 'user-prompt', at: new Date().toISOString() };
            state = saveState(root, { ...state, approvals: [...state.approvals, approval] });
          }
          notes.push('The customer approved the design (they typed "approve" themselves), and it is recorded. Move to the next step now and tell them in one sentence what happens next.');
        } else {
          notes.push('The customer typed "approve", but there is nothing waiting for approval right now. Tell them where things stand in one sentence.');
        }
      }
      const reminder =
        `[Piezas] ${STEP_NAMES[state.phase]} (phase: ${state.phase}). ` +
        'Always: no local database; PIEZAS_API_KEY server-side only; no provider tokens in the app; plain language with the user.';
      return done(0, hookContext('UserPromptSubmit', [reminder, ...notes].join(' ')));
    }

    if (event === 'Stop') {
      if (!root || payload.stop_hook_active) return done();
      const state = loadState(root);
      if (state.phase === 'discover') return done();
      // Only the Hard No findings hold a turn open. Ordinary build gaps (tests
      // still to write, config to finish) belong to the work, not to every
      // reply — otherwise a user's quick question turns into a forced fix-up.
      const errors = newHardNoFindings(root);
      if (errors.length === 0) return done();
      const lines = errors.slice(0, 8).map((f) => `- ${f.code} ${f.file ?? ''}: ${f.message}`);
      return done(
        0,
        JSON.stringify({
          decision: 'block',
          reason:
            `Piezas check found ${errors.length} problem(s) that would break the app or its rules. Fix them before finishing:\n${lines.join('\n')}`,
        }),
      );
    }
  } catch (error) {
    // Fail open on our own bugs: a hook that crashes every call is worse than one that misses.
    return done(0, '', `piezas hook: ${error?.message || error}`);
  }
  return done();
}

function guardContent(options) {
  if (typeof options.content === 'string') return options.content;
  if (typeof options.contentFile === 'string' && options.contentFile && existsSync(options.contentFile)) {
    try {
      return readFileSync(options.contentFile, 'utf-8');
    } catch {
      return undefined;
    }
  }
  return undefined;
}

